-- =====================================================
-- pgwhite_weread_import.sql
-- 批次: 2026-07-26 微信读书划线导入
--
-- 【本次选择】用户编号: 1,3,4,5,7,8,12,13,15,16,23,30,32,39,40
-- 【内容范围】仅划线 markText；不包含想法/点评 review、不包含书签 bookmark
-- 【quote 形态】每条仅 quote_translations.zh；暂不写 en 译文
-- 【tag 策略】仅通过 book_id 关联作者+书名；不写入 quote_characters / quote_tags
-- 【前端约定】无二级 tag 的 quote 卡片只显示作者+书名（见 useSentenceTags hasSecondaryTags）
-- 【作者复用】石黑一雄→authors.id=1；黑塞→authors.id=2；其余作者从 id=5 起新建
-- 【执行前】确认 MAX(quotes.id) < 119 或调整下方 START_QUOTE_ID
-- =====================================================

USE pgwhite;

-- --- 本文件共 15 本书 · 选择 #1, #3, #4, #5, #7, #8, #12, #13, #15, #16, #23, #30, #32, #39, #40 ---

-- 新建作者 pick #1 · 伊塔洛·卡尔维诺
INSERT INTO authors (id, emoji) VALUES (5, '🇮🇹');
INSERT INTO author_translations (author_id, language_code, name) VALUES (5, 'zh', '伊塔洛·卡尔维诺'), (5, 'en', 'Italo Calvino');
-- pick #1 · weread bookId=24953413 · 如果在冬夜，一个旅人 · 14 条划线
INSERT INTO books (id, author_id, emoji) VALUES (5, 5, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (5, 'zh', '如果在冬夜，一个旅人'), (5, 'en', 'If on a Winter''s Night a Traveler');

INSERT INTO quotes (id, book_id) VALUES (119, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (119, 'zh', '这里严肃的墙壁上到处是大学生们留下的超大字迹和微型图画，就像穴居的原始人觉得有必要装饰冰凉的穴壁，以便主宰折磨人的矿物的异己感，让它们变得熟悉起来');
INSERT INTO quotes (id, book_id) VALUES (120, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (120, 'zh', '这部充满了各种感觉的小说突然被这些不知深浅的漩涡隔断了，犹如你希望生活充实结果却发现了生活中的空虚。');
INSERT INTO quotes (id, book_id) VALUES (121, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (121, 'zh', '你用刀刃在纸张中开路犹如用思想在文字中开路，因为阅读就像在密林中前进。');
INSERT INTO quotes (id, book_id) VALUES (122, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (122, 'zh', '你说你喜欢书，因为书是明确的、具体的、看得见摸得着的，不冒任何风险就能享受到的，而生活经历呢，却是捉摸不定的，时断时续的，相互矛盾的。');
INSERT INTO quotes (id, book_id) VALUES (123, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (123, 'zh', '你原来认为对生活寄托希望的年代已经过去了，现在却心满意足地走出书店。');
INSERT INTO quotes (id, book_id) VALUES (124, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (124, 'zh', '读者啊！那位幸福的女读者进入你的视野，进入你注意的范围，或者说你陷入了一个磁场，而且摆脱不了这个磁场的吸引力。');
INSERT INTO quotes (id, book_id) VALUES (125, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (125, 'zh', '你在梦境之中要寻找一种抽象的、绝对的时空，并沿着一条明确的路线前进。但是，当你觉得你快要找到的时候，你却醒了，发现你躺在床上并未动弹，只得一切重新开始。');
INSERT INTO quotes (id, book_id) VALUES (126, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (126, 'zh', '但是我生活中的每个时刻都是由一些新的事件组成的，而每个新的事件又必然带来新的后果，因此我愈想回复到最初的“零”位置，反而离开这个位置愈远。');
INSERT INTO quotes (id, book_id) VALUES (127, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (127, 'zh', '读者你之所以在下车的旅客中注意到了我并注视着我在酒吧与公共电话亭之间的穿梭行动，那是因为我的名字叫“我”。');
INSERT INTO quotes (id, book_id) VALUES (128, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (128, 'zh', '难道你就没有想到我手表上的日历在那个小方框里啪啪倒退，仿佛断头台上被屠刀砍下的头颅一个个从我脚下滚过吗？');
INSERT INTO quotes (id, book_id) VALUES (129, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (129, 'zh', '眼睛盯着挂钟的指针，徒劳地要使那巨大的时针倒转，倒着经历那已经属于过去的时刻。');
INSERT INTO quotes (id, book_id) VALUES (130, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (130, 'zh', '火车的长鸣在雨水中闪烁着寒光的铁轨尽头渐渐消逝。');
INSERT INTO quotes (id, book_id) VALUES (131, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (131, 'zh', '今天写长篇小说也许是自相矛盾，时间的维度被打碎了，我们只能在时间的碎片中爱和思考，每一个时间的碎片沿着自己的轨迹运行，在瞬间消失。');
INSERT INTO quotes (id, book_id) VALUES (132, 5);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (132, 'zh', '你茫然地向周围的图书又看了一眼，便走出书店(或者说得更确切些，周围的图书怏怏地望着你走开，仿佛一只只丢失后被收容在市政府特意设置的笼子里的狗，看见一个同伴被其主人认领后牵着链子救走了)。');

-- 新建作者 pick #3 · 乔叟
INSERT INTO authors (id, emoji) VALUES (6, '🇬🇧');
INSERT INTO author_translations (author_id, language_code, name) VALUES (6, 'zh', '乔叟'), (6, 'en', 'Geoffrey Chaucer');
-- pick #3 · weread bookId=25561821 · 坎特伯雷故事（译文名著典藏） · 56 条划线
INSERT INTO books (id, author_id, emoji) VALUES (6, 6, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (6, 'zh', '坎特伯雷故事（译文名著典藏）'), (6, 'en', 'The Canterbury Tales');

INSERT INTO quotes (id, book_id) VALUES (133, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (133, 'zh', '所罗门说：‘同甜言蜜语的骗人精相比，责备人家做蠢事的人更蒙受天恩。’');
INSERT INTO quotes (id, book_id) VALUES (134, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (134, 'zh', '懒汉不干活，冬天里借口天冷，夏天里借口天热。');
INSERT INTO quotes (id, book_id) VALUES (135, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (135, 'zh', '只要防卫行动是当场作出的，在受攻击和防卫之间没有间隔，而且确实是为防卫而不是为报复，你这话肯定正确。');
INSERT INTO quotes (id, book_id) VALUES (136, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (136, 'zh', '圣格列高利说：‘好好想过自己错误和罪过之多，会觉得痛苦和磨难减轻一些；越感到自己罪孽深重，就越觉得痛苦不太厉害而易于忍受。’');
INSERT INTO quotes (id, book_id) VALUES (137, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (137, 'zh', '梅利比答道：“人家恶意伤害我，而我不报复，就是在通知和邀请伤害者和其他人再来害我。');
INSERT INTO quotes (id, book_id) VALUES (138, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (138, 'zh', '所罗门说：‘若找到蜂蜜，吃起来要适量；过量会呕吐。’结果仍是饥饿。');
INSERT INTO quotes (id, book_id) VALUES (139, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (139, 'zh', '《教令集》上说：‘除非付出极大努力，难得会有起因坏而结果好的事。’');
INSERT INTO quotes (id, book_id) VALUES (140, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (140, 'zh', '利乌斯说：‘长久的准备换来迅速的胜利。’');
INSERT INTO quotes (id, book_id) VALUES (141, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (141, 'zh', '要知道：有钱人保卫自身或财产的最强大力量，在于下人和邻人对他的敬爱和友爱。');
INSERT INTO quotes (id, book_id) VALUES (142, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (142, 'zh', '作恶的反面不是作恶，报复的反面不是报复，伤害的反面不是伤害，那都是一路的。');
INSERT INTO quotes (id, book_id) VALUES (143, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (143, 'zh', '按我这办法检验意见后，你找出较好、较有利并得到很多聪明人和老人赞同的意见，再考虑是否有能力贯彻并获得满意结果。');
INSERT INTO quotes (id, book_id) VALUES (144, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (144, 'zh', '凡是你仆人和对你毕恭毕敬的人，对他们的意见特别要保持距离；因为他们的话恐怕出于惧怕而非敬爱。');
INSERT INTO quotes (id, book_id) VALUES (145, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (145, 'zh', '对朋友甜言蜜语的人，在他脚前安置了诱捕的罗网。');
INSERT INTO quotes (id, book_id) VALUES (146, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (146, 'zh', '《圣经》上说：‘傻瓜的特点是轻易相信每个人都很坏，又轻易相信自己具有一切优点。’');
INSERT INTO quotes (id, book_id) VALUES (147, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (147, 'zh', '你得永远牢记：帮你出主意的人需具备我讲过的三个条件，就是忠实、明智、富于经验。');
INSERT INTO quotes (id, book_id) VALUES (148, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (148, 'zh', '自己都藏不住想法，怎能要别人为你守秘密呢？');
INSERT INTO quotes (id, book_id) VALUES (149, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (149, 'zh', '一、满腔怒火的人总以为自己能做他做不了的事。二、怒气冲冲的人不能很好判断；/不能很好判断就不能很好听取意见。三、塞内加说，‘怒冲冲的人只会出口伤人，’伤人的话又会惹人家生气。');
INSERT INTO quotes (id, book_id) VALUES (150, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (150, 'zh', '他还说：‘心中忧伤置很多人于死地。’所罗门说：‘像羊毛里的蛀虫蛀坏衣服，像树上的蛀虫蛀空树干，忧伤会蛀蚀人心。’');
INSERT INTO quotes (id, book_id) VALUES (151, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (151, 'zh', '塞内加说过：‘明智者不该为子女死亡而过于伤心，应该有耐心忍受这事实，就像等待自己的死亡。’”/');
INSERT INTO quotes (id, book_id) VALUES (152, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (152, 'zh', '所以你们听到，我虽然已死亡 还在唱，而我在开始唱的时候， 似乎她把麦粒放上了我舌头。 直到我舌头上的麦粒被拿去。');
INSERT INTO quotes (id, book_id) VALUES (153, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (153, 'zh', '如果我食言，愿上帝给我报应， 就像他严惩法国那个加涅隆。');
INSERT INTO quotes (id, book_id) VALUES (154, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (154, 'zh', '夜里睡觉，睡上五小时就足够， 除非，是那些身体衰弱的老头， 他们像结了婚的人，不爱起床—— 就像被狗群追过的野兔那样， 累坏了身子，只能趴倒在窝里。');
INSERT INTO quotes (id, book_id) VALUES (155, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (155, 'zh', '但是我的故事里没什么哲理、 也没有高深古怪的法律名词—— 我的肚子里没有什么拉丁字。');
INSERT INTO quotes (id, book_id) VALUES (156, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (156, 'zh', '卢坎曾极力描绘恺撒的凯旋，￼ 但是我相信，恺撒的那支部队 若在这欢天喜地的人群旁边， 就绝对没有如此奇妙而壮美。');
INSERT INTO quotes (id, book_id) VALUES (157, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (157, 'zh', '塞内加他们痛惜时光的流逝，￼ 认为失去黄金也难比这损失。 他说，‘失去财物还能够补救， 但失去时间，我们将一无所有。’');
INSERT INTO quotes (id, book_id) VALUES (158, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (158, 'zh', '像林中的金翅雀那样快活， 短小精悍，褐色的皮肤像浆果。 他黑黑的头发，梳得美观整齐， 舞也跳得好，跳得欢天又喜地， 所以，都叫他寻欢作乐的帕金。');
INSERT INTO quotes (id, book_id) VALUES (159, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (159, 'zh', '咱眼中草屑，他看得清清楚楚， 但他看不见自己眼中的梁木。');
INSERT INTO quotes (id, book_id) VALUES (160, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (160, 'zh', '除非咱命运变得像是欧楂果——￼ 这果实越长越糟，直到掉落， 最后腐烂在垃圾或者枯草里。');
INSERT INTO quotes (id, book_id) VALUES (161, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (161, 'zh', '可见，谁若满载着荣誉断了气，他的亲友该为他去世而欣喜，因为等他令名因年龄而枯槁，那时他的能耐已完全被忘掉。所以如果有人要留个好名誉，那么最好在声名最隆时死去。');
INSERT INTO quotes (id, book_id) VALUES (162, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (162, 'zh', '所以我认为明智的做法就是：要自愿地去做非做不可的事，要甘心接受不可避免的情形，特别是我们必然遭遇的命运。');
INSERT INTO quotes (id, book_id) VALUES (163, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (163, 'zh', '国王同随从一样，也不免死去：只是有人死床上，有人死荒郊，有人死深海；这种事人人知道；毫无办法，人人都得走这条路——这条路可说适用于世上万物。');
INSERT INTO quotes (id, book_id) VALUES (164, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (164, 'zh', '因为凭借了这爱的美好锁链，他就可以在一定的范围里面，束缚住空气水火土，不使脱逃。');
INSERT INTO quotes (id, book_id) VALUES (165, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (165, 'zh', '这世界只是条大路，充满哀伤，我们是路上的过客，来来往往；而死亡把人世的痛苦全了结。​”');
INSERT INTO quotes (id, book_id) VALUES (166, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (166, 'zh', '从被称为自然功能的机体里，那种叫作肉体功能的排除力已没有力量把毒消除或排空。');
INSERT INTO quotes (id, book_id) VALUES (167, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (167, 'zh', '讲到这句话，他开始讲不下去，因为，有股死亡的寒气从脚跟升到他胸口，弥漫到他的周身；');
INSERT INTO quotes (id, book_id) VALUES (168, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (168, 'zh', '他威风的脸上长着黑色胡子； 他那双眼睛的瞳仁好生奇怪， 竟然闪现出又黄又红的光彩； 环顾四周时他像鹰头狮身兽， 两道剑眉上，浓密黑发长满头；');
INSERT INTO quotes (id, book_id) VALUES (169, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (169, 'zh', '他眼睛色如柠檬，鼻子挺又高， 他的嘴唇很丰满，脸上血色好； 一些雀斑零星地散布在脸上， 雀斑颜色是黝黑之中带点黄。');
INSERT INTO quotes (id, book_id) VALUES (170, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (170, 'zh', '这女神高高骑在一头公鹿上， 一些小小的猎犬都在她脚旁； 她脚下有个月亮渐渐在变圆，￼ 但随后变缺也不用多少时间；');
INSERT INTO quotes (id, book_id) VALUES (171, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (171, 'zh', '床上发生的大逆不道的谋杀； 带着血淋淋伤口的公开征伐； 搏斗中血染的刀剑咄咄逼人； 那悲惨之地充满了尖厉之声。 在那里我还看见有的人自杀， 他的心头血浸泡着他的头发； 钉子在夜里钉进人的头颅里； 冰冷的死者张着嘴仰卧在地。');
INSERT INTO quotes (id, book_id) VALUES (172, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (172, 'zh', '那是爱神之仆生活中的苦情： 不得安宁的睡眠，哀哀的叹息， 一往情深的流泪，苦苦的哭泣， 像火焰一样猛烈的阵阵情思；');
INSERT INTO quotes (id, book_id) VALUES (173, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (173, 'zh', '我之所以会死完全是因为你。 如果我能做任何事让你高兴， 那么我心头上任何其他事情 只像是一些野草，不值得注意。');
INSERT INTO quotes (id, book_id) VALUES (174, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (174, 'zh', '因为相思者常有这种怪心理： 有时在树巅，有时落到荆棘地， 忽上忽下，像井里的吊桶一般。');
INSERT INTO quotes (id, book_id) VALUES (175, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (175, 'zh', '“五月里百花怒放，绿叶猛长； 我要欢迎你，美好清新的五月， 因为我想要一些绿色的枝叶。”');
INSERT INTO quotes (id, book_id) VALUES (176, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (176, 'zh', '云雀为白天来临而忙碌报信， 它唱着歌儿迎接灰蒙蒙黎明， 接着火样的太阳亮堂堂升起， 那光明使整个东方露出笑意；');
INSERT INTO quotes (id, book_id) VALUES (177, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (177, 'zh', '他咽不下水和饭菜，睡不着觉， 人变得枯槁精瘦，瘦得像长矛； 他眼窝深陷，害得人人都怕看， 脸色蜡黄又憔悴，像死灰一般； 他形单影只，经常是孤孤零零， 晚上独自哀诉时，整夜哭不停； 他听到人家唱歌或弹奏乐器， 忍不住就会没完没了地哭泣。');
INSERT INTO quotes (id, book_id) VALUES (178, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (178, 'zh', '夏天过去后，夜变得越来越长， 一位相思者、一位囚徒的悲伤 都与夜俱增，使他俩加倍痛苦——');
INSERT INTO quotes (id, book_id) VALUES (179, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (179, 'zh', '我们变得像醉汉，醉得像老鼠。 但还有个家，这一点醉汉清楚， 但他不知道，怎样才能走回家， 而对于醉汉，每条道路都很滑。');
INSERT INTO quotes (id, book_id) VALUES (180, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (180, 'zh', '他从《福音书》引来这个训条，￼ 黄金若锈掉，铁还有什么办法？ 因为我们信赖的教士若腐败， 那么无知者的腐化不足为怪；');
INSERT INTO quotes (id, book_id) VALUES (181, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (181, 'zh', '在这整个世界上没有一个人 能在内科外科上同他比一比， 因为他有占星学方面的根底。');
INSERT INTO quotes (id, book_id) VALUES (182, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (182, 'zh', '黄金作为药既然能当强心剂，￼ 他特别钟爱黄金自然有道理。');
INSERT INTO quotes (id, book_id) VALUES (183, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (183, 'zh', '看他的性格气质属于多血质');
INSERT INTO quotes (id, book_id) VALUES (184, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (184, 'zh', '因为肯向贫苦的教士团施舍， 表明那人已悔罪，该得到宽赦；');
INSERT INTO quotes (id, book_id) VALUES (185, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (185, 'zh', '他的双眼在眼眶里忽闪忽闪， 正像星星在一个霜冻的夜晚。');
INSERT INTO quotes (id, book_id) VALUES (186, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (186, 'zh', '因为据他自己说，他当忏悔师 要比教区里的教士更加适宜， 因为他得到批准，有这种权利。￼');
INSERT INTO quotes (id, book_id) VALUES (187, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (187, 'zh', '这高级教士确实非常地体面； 他绝不苍白，决非消瘦的饿鬼。 烤熟的肥天鹅最合他的口味。');
INSERT INTO quotes (id, book_id) VALUES (188, 6);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (188, 'zh', '他认为这种话不值一个牡蛎， 认为那条文不值拔光毛的鸡。');

-- 新建作者 pick #4 · 陀思妥耶夫斯基
INSERT INTO authors (id, emoji) VALUES (7, '🇷🇺');
INSERT INTO author_translations (author_id, language_code, name) VALUES (7, 'zh', '陀思妥耶夫斯基'), (7, 'en', 'Fyodor Dostoevsky');
-- pick #4 · weread bookId=3300154232 · 地下室手记（经典译本无删减） · 122 条划线
INSERT INTO books (id, author_id, emoji) VALUES (7, 7, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (7, 'zh', '地下室手记（经典译本无删减）'), (7, 'en', 'Notes from Underground');

INSERT INTO quotes (id, book_id) VALUES (189, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (189, 'zh', '一个人对自我意识和自我感知的体悟愈发深切，其出于对人类的挚爱而献身并牺牲整个人格时所体会到的快慰就愈发强烈。');
INSERT INTO quotes (id, book_id) VALUES (190, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (190, 'zh', '在他看来，真正的精神解放不在于物质的丰足，而在于超越自我的局限，在无私奉献中找到生命的真正意义。');
INSERT INTO quotes (id, book_id) VALUES (191, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (191, 'zh', '这种近乎偏执的自我中心，实质上是对真实生活的本能畏惧，是灵魂深处的恐惧在现实中的投射￼。');
INSERT INTO quotes (id, book_id) VALUES (192, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (192, 'zh', '因此，这位主人公所具有的双重身份就显得意味深长：“他既是时代的控诉者，又是被时代和历史所控诉的对象。”');
INSERT INTO quotes (id, book_id) VALUES (193, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (193, 'zh', '我为首次塑造了一个真正代表俄罗斯大多数人的形象而自豪，更为首次揭示了这一形象畸形而悲剧性的内在世界而骄傲');
INSERT INTO quotes (id, book_id) VALUES (194, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (194, 'zh', '我只不过是将那些你们连碰都不敢碰的事物推至极致罢了');
INSERT INTO quotes (id, book_id) VALUES (195, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (195, 'zh', '究竟什么更好——那廉价而易得的幸福，还是让灵魂升华的崇高痛苦？来啊，到底是什么更好？');
INSERT INTO quotes (id, book_id) VALUES (196, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (196, 'zh', '因为对女人来说，爱本身就包含着一切重生的可能，是对所有毁灭的救赎，是重获新生的唯一之路，也只能以这种方式显现。');
INSERT INTO quotes (id, book_id) VALUES (197, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (197, 'zh', '所谓的爱，不过是被爱者主动交出的一纸暴政许可。');
INSERT INTO quotes (id, book_id) VALUES (198, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (198, 'zh', '我正在写着这令人作呕的真相，它们从我的笔尖流淌而出，如同腐烂的脓液');
INSERT INTO quotes (id, book_id) VALUES (199, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (199, 'zh', '她轻轻俯身靠近我，将我拥入怀中，仿佛在这个不期然的拥抱中，时光凝固成了永恒的刹那。');
INSERT INTO quotes (id, book_id) VALUES (200, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (200, 'zh', '我的虚荣心重得像是被人活活剥了皮，连呼吸都让我感到钻心的疼痛。');
INSERT INTO quotes (id, book_id) VALUES (201, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (201, 'zh', '她的面色瞬间惨白如纸，欲言又止，嘴唇痛苦地扭曲着；随即，仿佛被无形的斧刃砍倒，她重重地瘫坐在椅子上。此后，她便这般听着，张着嘴，睁大着眼，全身因极度的恐惧而颤抖不已。');
INSERT INTO quotes (id, book_id) VALUES (202, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (202, 'zh', '“拯救！”我从椅子上猛然跃起，像只困兽般在她面前来回踱步。内心的烈焰在胸膛中燃烧，喷薄欲出。');
INSERT INTO quotes (id, book_id) VALUES (203, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (203, 'zh', '为了报复她，我在心底暗自发誓：从这一刻起，再不与她说一言半语。“一切过错都源于她。”我在心中冷笑着想道。');
INSERT INTO quotes (id, book_id) VALUES (204, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (204, 'zh', '我双手交叉胸前，刻意摆出拿破仑式的威严姿态，在他面前一动不动地伫立了足足三分钟。');
INSERT INTO quotes (id, book_id) VALUES (205, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (205, 'zh', '我的声音因急切而颤抖，语速快得几近耳语，同时将那几枚一直紧攥在手心、已被体温焐热的卢布扔在他面前。');
INSERT INTO quotes (id, book_id) VALUES (206, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (206, 'zh', '我猛然抬眼，霎时间羞愧得浑身血液冻结，仿佛被雷击中般踉跄着冲进了自己那间逼仄的斗室。');
INSERT INTO quotes (id, book_id) VALUES (207, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (207, 'zh', '我的声音里既有威胁，又带着一丝难以察觉的哀求。');
INSERT INTO quotes (id, book_id) VALUES (208, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (208, 'zh', '当我仍不肯醒悟，执意抗争时，他就会突然叹息。他凝视着我，长长地、深深地叹息，仿佛要用这一声叹息来丈量我道德沦丧的全部深渊');
INSERT INTO quotes (id, book_id) VALUES (209, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (209, 'zh', '他用那目光注视着我，已不仅仅是严厉，而是充满了刺骨的轻蔑。');
INSERT INTO quotes (id, book_id) VALUES (210, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (210, 'zh', '因他之故，我想必能得上苍宽恕诸多过错。');
INSERT INTO quotes (id, book_id) VALUES (211, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (211, 'zh', '他就是我的心头之疮，是上天派来惩罚我的鞭子。');
INSERT INTO quotes (id, book_id) VALUES (212, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (212, 'zh', '终于有一天，她满面羞红，美得动人心魄，浑身颤抖、泪如雨下，扑倒在我脚边，说我是她的救赎者，说她爱我胜过世间万物。我露出惊讶的神情，可是……');
INSERT INTO quotes (id, book_id) VALUES (213, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (213, 'zh', '然而每当这个念头浮现，一股难以遏制的恶意就在我心中翻腾，似乎要是这个“该死的”丽莎此刻恰巧出现在我面前，我就会将她碾得粉碎，要羞辱她，朝她吐唾沫，将她轰出去，对她拳脚相加！');
INSERT INTO quotes (id, book_id) VALUES (214, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (214, 'zh', '然而，“不过，丽莎说不定真的会来访”——这个念头如同魔咒般萦绕在我心头，成了我当时所有思绪的终点，犹如一首永无休止的歌谣中反复出现的副歌。');
INSERT INTO quotes (id, book_id) VALUES (215, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (215, 'zh', '然而，不管我如何说服自己，内心始终无法平静下来，就像夜晚的河水，表面平静，暗流却在深处涌动。');
INSERT INTO quotes (id, book_id) VALUES (216, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (216, 'zh', '年少气盛时的过失，不过是人生长河中激起的一朵浪花罢了。');
INSERT INTO quotes (id, book_id) VALUES (217, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (217, 'zh', '这种笔调胜过千言万语的辩解，瞬间就让他们明白，对于“昨日那些不堪回首的往事”，我持一种超然物外的态度。我绝非如诸位所想象的那般被打击得魂飞魄散，相反，我以一个懂得自重的绅士所应有的从容与淡定来看待此事。');
INSERT INTO quotes (id, book_id) VALUES (218, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (218, 'zh', '每一个字都像是精心雕琢过的，却又显得那样自然随意。');
INSERT INTO quotes (id, book_id) VALUES (219, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (219, 'zh', '那是一双充满生命力的眼睛，仿佛能将世间所有的情感都容纳其中——既能映照出最温柔的爱意，又能折射出最深沉的憎恨。');
INSERT INTO quotes (id, book_id) VALUES (220, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (220, 'zh', '现在的她目光中盈满祈求与柔情，同时又闪烁着信任的光芒，既亲切又羞怯，像是春日里怯生生绽放的花朵。');
INSERT INTO quotes (id, book_id) VALUES (221, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (221, 'zh', '她跑开时的模样让我难以忘怀：整张脸庞红得像是晚霞，眼睛如同晨星般闪亮，嘴角挂着一丝若有似无的笑意——这究竟意味着什么？');
INSERT INTO quotes (id, book_id) VALUES (222, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (222, 'zh', '突然间，一抹红晕如潮水般漫上她的面颊，全身轻轻颤抖，就像秋日里被风拂过的落叶');
INSERT INTO quotes (id, book_id) VALUES (223, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (223, 'zh', '他们连为你多骂几句都嫌浪费唇舌。胡乱撒上几锹湿漉漉的蓝色黏土，就急不可耐地奔向酒馆，仿佛要尽快洗去死亡的气息……');
INSERT INTO quotes (id, book_id) VALUES (224, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (224, 'zh', '事情就是如此无可奈何，我冷笑着想，一旦将灵魂典当，又背负着债务，连一声叹息都要噤若寒蝉。');
INSERT INTO quotes (id, book_id) VALUES (225, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (225, 'zh', '她声音里颤动着某种全然不同的情绪，不再是方才那般尖锐、粗野而倔强，而是流露出几分柔软与羞怯。');
INSERT INTO quotes (id, book_id) VALUES (226, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (226, 'zh', '“您怎么……”她突然开口，声音却又戛然而止，仿佛蜷缩回自己的蚌壳。');
INSERT INTO quotes (id, book_id) VALUES (227, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (227, 'zh', '人应当先学会如何活出生命的真谛，然后才有资格去评判他人啊！”');
INSERT INTO quotes (id, book_id) VALUES (228, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (228, 'zh', '纵使你百年之后，他们一生都会继承你的心性与胸襟，因为这些都是从你灵魂深处流淌而出的馈赠，他们会成为你精神的延续，你品格的映照。');
INSERT INTO quotes (id, book_id) VALUES (229, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (229, 'zh', '既然有过情深义重，既然因爱结缘，这爱意又何须消散？难道就不能好生维系吗？');
INSERT INTO quotes (id, book_id) VALUES (230, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (230, 'zh', '爱情乃是上苍赐予的奥秘，不论发生什么，都该对外人的眼睛遮掩几分。如此方显得愈发神圣，愈发珍贵。彼此更生敬重之心，而这敬重之情又是诸多美德的根基。”');
INSERT INTO quotes (id, book_id) VALUES (231, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (231, 'zh', '这正是问题所在——你不肯思考。趁还来得及，快快醒悟吧。时光未晚。你正值青春，容貌姣好，大可以去追寻爱情，步入婚姻，获得幸福……');
INSERT INTO quotes (id, book_id) VALUES (232, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (232, 'zh', '她的声音细若游丝，几不可闻，身子又轻轻动了动，像一片被风吹落的枯叶。');
INSERT INTO quotes (id, book_id) VALUES (233, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (233, 'zh', '屋内陷入一片死寂，只有烛火微弱的跳动在墙上投下摇曳的影子。');
INSERT INTO quotes (id, book_id) VALUES (234, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (234, 'zh', '一个阴暗的念头在我脑海中萌生，随即如同爬入阴冷潮湿的地下室般的感觉游走全身。');
INSERT INTO quotes (id, book_id) VALUES (235, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (235, 'zh', '突然间，我察觉到身旁有一双眼睛正睁得浑圆，带着一种近乎病态的好奇与执着凝视着我。那目光冷漠而疏离，阴郁深沉，宛如来自另一个世界的注视，令我感到一阵难以言喻的压抑。');
INSERT INTO quotes (id, book_id) VALUES (236, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (236, 'zh', '这间屋子狭窄、逼仄、低矮，一只巨大的衣柜占据了大半空间，使之更显局促。');
INSERT INTO quotes (id, book_id) VALUES (237, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (237, 'zh', '“今天的天气……这雪……糟糕透了！”我喃喃自语，烦闷地将手枕在脑后，目光涣散地望着天花板。她依旧沉默。整个场景显得如此荒诞而丑陋。');
INSERT INTO quotes (id, book_id) VALUES (238, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (238, 'zh', '那张脸上有种天然的善良与纯真，却又笼罩着一层异乎寻常的严肃。');
INSERT INTO quotes (id, book_id) VALUES (239, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (239, 'zh', '映入眼帘的是一张年轻而清新的面容，略显苍白，却带着一对浓黑的直眉，眼神严肃中透着几分不解，仿佛在困惑地打量着这个陌生的世界。');
INSERT INTO quotes (id, book_id) VALUES (240, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (240, 'zh', '在茫茫雪雾中，零落的路灯阴郁地闪烁着微光，恍若送葬队伍中的丧烛。');
INSERT INTO quotes (id, book_id) VALUES (241, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (241, 'zh', '难耐的焦躁令我情不自禁地用拳头捶打着车夫的后颈。');
INSERT INTO quotes (id, book_id) VALUES (242, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (242, 'zh', '尽管如此，他还是挥动马鞭抽打起那匹瘦骨嶙峋的马，惹得它开始用后蹄暴躁地乱踢。');
INSERT INTO quotes (id, book_id) VALUES (243, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (243, 'zh', '我在杂乱的房间里孑然而立。眼前一片狼藉：残羹冷炙散落各处，地上是碎裂的酒杯，斑斑酒渍如泪，烟蒂横陈；脑中酒意翻涌，思绪纷乱如麻；心中的痛楚几近将我吞噬。');
INSERT INTO quotes (id, book_id) VALUES (244, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (244, 'zh', '我独自伫立原地，仿佛浑身都沾满了他们的唾沫');
INSERT INTO quotes (id, book_id) VALUES (245, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (245, 'zh', '高烧侵袭着我的身体，汗湿的头发如同枯萎的野草，凌乱地黏在额头和太阳穴上，映衬着我内心的荒芜。');
INSERT INTO quotes (id, book_id) VALUES (246, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (246, 'zh', '我倏然转向兹韦尔科夫，浑身颤抖。此时的我早已精疲力竭，痛不欲生，就像一个即将沉没的人抓住最后一根稻草。');
INSERT INTO quotes (id, book_id) VALUES (247, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (247, 'zh', '在这漫长的三个小时里，我整整三次汗湿衣衫，又三次汗渍干透');
INSERT INTO quotes (id, book_id) VALUES (248, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (248, 'zh', '那个清晨，我猛然从床上惊醒，激动得一跃而起，仿佛一切就要在此刻轰轰烈烈地展开。');
INSERT INTO quotes (id, book_id) VALUES (249, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (249, 'zh', '我立即开始憎恨他们，把自己封闭在一种怯懦的、伤痕累累的、无以复加的骄傲之中。');
INSERT INTO quotes (id, book_id) VALUES (250, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (250, 'zh', '这本不足为奇：整个夜晚，学生时代那些如同苦役般的记忆一直在啃噬着我的心魂，我无法挣脱。');
INSERT INTO quotes (id, book_id) VALUES (251, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (251, 'zh', '一个卑鄙、傲慢的小丑，虽在外表上极其敏感好面子，骨子里却是个十足的懦夫。');
INSERT INTO quotes (id, book_id) VALUES (252, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (252, 'zh', '看得出来，到了而立之年，他就会完全变得臃肿不堪，像个皮囊充气的木偶');
INSERT INTO quotes (id, book_id) VALUES (253, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (253, 'zh', '我痛恨他那张英俊却愚蠢的脸庞（说实话，我倒很乐意用我这张聪明的脸跟他交换）');
INSERT INTO quotes (id, book_id) VALUES (254, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (254, 'zh', '显然，在他们眼中，我不过是一只最寻常不过的苍蝇，可以任意忽视的存在。');
INSERT INTO quotes (id, book_id) VALUES (255, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (255, 'zh', '让那所学校见鬼去吧，让那些可怕的、宛如苦役般的岁月统统下地狱！');
INSERT INTO quotes (id, book_id) VALUES (256, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (256, 'zh', '那些屋子一间比一间矮小，处处散发着那种典型的小官吏般的节俭气息，连墙壁都泛着萎黄。');
INSERT INTO quotes (id, book_id) VALUES (257, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (257, 'zh', '当我的幻想抵达某种极乐的境地，以致内心深处涌起一种必须立即拥抱众生、亲近全人类的渴望时。为了满足这种渴望，总得有那么一个实实在在、血肉之躯的人才行。');
INSERT INTO quotes (id, book_id) VALUES (258, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (258, 'zh', '这佐料由矛盾与痛苦调制而成，由那无休止的自我剖析熬煮而就');
INSERT INTO quotes (id, book_id) VALUES (259, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (259, 'zh', '那段日子我总是辗转难眠，昏昏发热，心脏时而莫名地停滞，仿佛坠入深渊，时而又突然狂跳不止，怦怦作响，犹如困兽，一声声敲击着我的胸膛！……');
INSERT INTO quotes (id, book_id) VALUES (260, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (260, 'zh', '这个狂妄的念头一经萌生，便如附骨之疽，日日夜夜噬咬着我的心神，令我辗转难眠。');
INSERT INTO quotes (id, book_id) VALUES (261, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (261, 'zh', '是的，我也许比所有人都聪明睿智，都富有教养，都心怀高尚——这一点是毋庸置疑的——可我却注定要永远做那个退让的苍蝇，永远被众人轻蔑和羞辱的苍蝇');
INSERT INTO quotes (id, book_id) VALUES (262, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (262, 'zh', '每当意识到自己那一身寒酸￼的衣着，想到自己那个瘦小猥琐、躲闪游移的身影是何等可笑，我都能感到心脏一阵抽搐般的剧痛，脊背泛起一阵阵灼热。');
INSERT INTO quotes (id, book_id) VALUES (263, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (263, 'zh', '我像一条卑微的泥鳅，以最狼狈不堪的姿态在人群中穿行，不停地给形形色色的人让路');
INSERT INTO quotes (id, book_id) VALUES (264, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (264, 'zh', '第二天，我又继续着我那可怜的放荡生活，比从前更加畏缩、更加卑微、更加忧郁，仿佛眼角总噙着一滴将落未落的泪水—');
INSERT INTO quotes (id, book_id) VALUES (265, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (265, 'zh', '但我转念一想，最终选择了……带着满腔难以平复的怨毒，悄然隐入黑暗之中。');
INSERT INTO quotes (id, book_id) VALUES (266, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (266, 'zh', '他们虽然为了理想连一根手指都懒得动弹，虽然是十足的强盗和无赖，却仍然会为自己最初的理想感动得潸然泪下，而且在灵魂深处依然保持着异乎寻常的诚挚。');
INSERT INTO quotes (id, book_id) VALUES (267, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (267, 'zh', '啊！这种令人叹为观止的多面性！这种足以令人惊异的本领，在他们身上展现得淋漓尽致！对最相悖的感受都能包容备至，游刃有余！');
INSERT INTO quotes (id, book_id) VALUES (268, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (268, 'zh', '顺便还要把自己保护得妥帖无比，就像珠宝商呵护稀世珍品一般，哪怕声称这也是为了守护那“美好与崇高”的圣洁理想。');
INSERT INTO quotes (id, book_id) VALUES (269, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (269, 'zh', '我的心绪总是在两个极端间摇摆：有时我厌恶至极，不愿与任何人说上一句话；可有时又会完全相反，不仅会与他们谈笑风生，甚至会萌生与他们结交的念头。');
INSERT INTO quotes (id, book_id) VALUES (270, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (270, 'zh', '而他们，那些可敬可叹的同僚们，却都愚钝不堪，活像羊群中那些茫然无知、千人一面的绵羊。');
INSERT INTO quotes (id, book_id) VALUES (271, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (271, 'zh', '可我确凿而痛苦地知道，我的面容永远无法呈现出这些完美的特质，就像一个不得不终身背负着自己影子的囚徒。');
INSERT INTO quotes (id, book_id) VALUES (272, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (272, 'zh', '此时回望往事，我才恍然大悟：正是由于我那无边无际的虚荣心，以及由此而生的对自己近乎病态的苛责，我总是以一种疯狂的不满注视着自己，甚至堕入深深的自我厌恶之中。');
INSERT INTO quotes (id, book_id) VALUES (273, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (273, 'zh', '生命的晨光尚未褪去，我的生活却已经阴郁得不见天日，混乱不堪，孤独得近乎野兽。');
INSERT INTO quotes (id, book_id) VALUES (274, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (274, 'zh', '这样的回忆，我积攒了数百个；可总有那么一个会在某个时刻从这些纷杂的记忆中脱颖而出，像梦魇般紧紧攫住我。');
INSERT INTO quotes (id, book_id) VALUES (275, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (275, 'zh', '又或许，我是在有意识地想象着有读者在场，好让自己在落笔时不至于过分放纵，能够维持几分体面。');
INSERT INTO quotes (id, book_id) VALUES (276, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (276, 'zh', '有时候，仅仅出于虚荣心的驱使，人反倒会给自己添加一些莫须有的罪责，我甚至完全理解这种特殊虚荣心的本质——那是一种以自我贬损为幌子的隐秘骄傲。');
INSERT INTO quotes (id, book_id) VALUES (277, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (277, 'zh', '你似乎有话要说，却又因为内心的怯懦将最后的话语咽回，你没有说出真相的勇气，只剩下懦夫的傲慢与自大。');
INSERT INTO quotes (id, book_id) VALUES (278, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (278, 'zh', '你的言辞是多么刺耳，多么狂妄自大，却又在字里行间处处流露出懦弱的颤栗！你在倾吐着荒诞不经的言语，还沾沾自喜；你吐露着狂悖不逊的话语，又畏畏缩缩地乞求原谅。');
INSERT INTO quotes (id, book_id) VALUES (279, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (279, 'zh', '但与此同时，不知为何，我又本能地感觉、隐隐地怀疑，我不过是在绞尽脑汁地编织谎言罢了，活像个见钱眼开的鞋匠。');
INSERT INTO quotes (id, book_id) VALUES (280, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (280, 'zh', '尽管我承认我羡慕常人羡慕得心肝俱裂，可若要我像他们那样活着，以我所见他们那机械般的生存状态，我却又不愿做这样的人');
INSERT INTO quotes (id, book_id) VALUES (281, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (281, 'zh', '他纵然能在地下室的幽暗深处默默蛰伏整整四十年之久，可一旦重见天日，一经开口，就如决堤的洪水，汹涌而出，永无止境……');
INSERT INTO quotes (id, book_id) VALUES (282, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (282, 'zh', '说来奇怪，假如真能有这样一座建筑，能让我从此心悦诚服，再不愿流露出丝毫的讥诮之意，我倒愿意怀着无尽的感激，让人把我的舌头彻底割去。');
INSERT INTO quotes (id, book_id) VALUES (283, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (283, 'zh', '也许它真的只是我由于愚昧，或是由于我们这一代人固守着某些不合时宜、不够理性的旧梦，而在脑海中臆想出来的空中楼阁。');
INSERT INTO quotes (id, book_id) VALUES (284, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (284, 'zh', '你们看吧：假如眼前矗立的不是什么宏伟宫殿，而是一间破旧的鸡舍，倘若天降大雨，我兴许会躲进去避一避。');
INSERT INTO quotes (id, book_id) VALUES (285, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (285, 'zh', '痛苦啊——这才是意识诞生的唯一源泉。');
INSERT INTO quotes (id, book_id) VALUES (286, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (286, 'zh', '我这里并非在为苦难辩护，更不是在颂扬安适。我所坚持的是……我的任性，是在我需要任性时，这份任性必须得到充分的保障。就像我深知那些轻歌曼舞的场合里不容许有苦难一般。');
INSERT INTO quotes (id, book_id) VALUES (287, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (287, 'zh', '他深爱追求的过程，可一旦真正达到目标，那份愉悦反倒消失殆尽，徒留尴尬与困顿——这当然显得极其可笑。');
INSERT INTO quotes (id, book_id) VALUES (288, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (288, 'zh', '无论好坏，有时将什么东西打个粉碎，也会带来一种难以言说的快意。');
INSERT INTO quotes (id, book_id) VALUES (289, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (289, 'zh', '说到底，人有时会深深地热爱苦难，热爱到近乎疯狂的地步，这是千真万确的事实。');
INSERT INTO quotes (id, book_id) VALUES (290, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (290, 'zh', '因为他在内心深处明白，一旦寻得答案，生命就将失去继续探寻的意义。');
INSERT INTO quotes (id, book_id) VALUES (291, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (291, 'zh', '或许人类在尘世间孜孜以求的全部目的，恰恰就蕴藏在这永无止境的追寻过程中，换言之，就存在于生命本身，而非那个确切的目标。');
INSERT INTO quotes (id, book_id) VALUES (292, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (292, 'zh', '会刻意做出些离经叛道的事情来，纯粹是出于那点刻骨铭心的忘恩负义之心；就是为了固执己见，坚持自己那微不足道却弥足珍贵的个性。');
INSERT INTO quotes (id, book_id) VALUES (293, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (293, 'zh', '众所周知，这些沉溺于意识的人，不论早晚，到了生命的尽头总会背叛自己的信念，制造出某种逸闻趣事，有时甚至是最不堪入目的那种。');
INSERT INTO quotes (id, book_id) VALUES (294, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (294, 'zh', '即便你们将人世间一切福祉都倾注给他，让他在幸福的海洋中浸润得连头顶都没入水面，只剩幸福的气泡如沸水般欢快地冒出；');
INSERT INTO quotes (id, book_id) VALUES (295, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (295, 'zh', '我甚至以为，对人最贴切的定义莫过于：一个双足而行的忘恩负义的动物。');
INSERT INTO quotes (id, book_id) VALUES (296, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (296, 'zh', '这唯一的情况就是：为了捍卫追求最愚蠢之事的权利，为了挣脱只能追求所谓明智之事的枷锁。');
INSERT INTO quotes (id, book_id) VALUES (297, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (297, 'zh', '不仅如此，人必将立即从一个有血有肉的生命，蜕变成八音盒里的一枚小齿轮，或者类似的什么机械零件。');
INSERT INTO quotes (id, book_id) VALUES (298, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (298, 'zh', '更为糟糕的是（这话我不得不说），到那时候说不定人们反而会对这刺痛生出欢喜来。');
INSERT INTO quotes (id, book_id) VALUES (299, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (299, 'zh', '即便文明没有让人变得更加嗜血，却无疑使人的嗜血变得更加阴险，更加可憎。');
INSERT INTO quotes (id, book_id) VALUES (300, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (300, 'zh', '啊，倘若我虚度光阴只是出于懒惰该多么美妙！');
INSERT INTO quotes (id, book_id) VALUES (301, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (301, 'zh', '这呻吟还表达了另一种意识：你找不到一个可以归罪的对象，然而疼痛却真实存在。');
INSERT INTO quotes (id, book_id) VALUES (302, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (302, 'zh', '了临终的病榻上，它依然在回味着这一切，连同这些年积累的精神利息一起，像在清点一生的耻辱资产……');
INSERT INTO quotes (id, book_id) VALUES (303, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (303, 'zh', '然而这还不够，每一次回忆，它都要像着了魔似的添油加醋，编织出愈发耻辱的细节，用自己的想象力残忍地挑逗自己，折磨自己，仿佛在进行一场永无止境的精神自虐。');
INSERT INTO quotes (id, book_id) VALUES (304, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (304, 'zh', '更有甚者，我之所以有罪，是因为即便我天生就有宽宏大量的美德，也只会因意识到它的全然无用而徒增我的痛苦，如同赐予垂死之人一剂珍贵的良药。');
INSERT INTO quotes (id, book_id) VALUES (305, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (305, 'zh', '有时候——你相信吗——我甚至为这种傲慢的想法感到一阵刺骨的羞愧，如同冬日的寒风穿透衣衫。');
INSERT INTO quotes (id, book_id) VALUES (306, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (306, 'zh', '然而说来荒诞，有些时候，若是有人当众赏我一记清脆的耳光，我或许反倒会在内心深处泛起一丝隐秘的欢喜，如同黑暗中绽放的昙花。');
INSERT INTO quotes (id, book_id) VALUES (307, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (307, 'zh', '以我本人为例来说，我这个人生来就有着一种近乎病态的自尊心，像是灵魂深处永不愈合的伤口。');
INSERT INTO quotes (id, book_id) VALUES (308, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (308, 'zh', '于是在内心深处，我开始暗自啃噬自己，日日夜夜地折磨自己，无休无止地责备自己，直到这般苦楚竟渐渐化作一种可耻的、诅咒般的甘美，最终成为真正的、不容置疑的快感！');
INSERT INTO quotes (id, book_id) VALUES (309, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (309, 'zh', '可是，诸位，又有谁会拿自己的病痛来夸耀，更遑论将之作为卖弄的资本？');
INSERT INTO quotes (id, book_id) VALUES (310, 7);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (310, 'zh', '我愈是体察善良和这一切“美好与崇高”的事物，我就愈发深陷于自己的污泥之中，愈发无可救药地在其中沉沦。');

-- 新建作者 pick #5 · 亨利克·显克维奇
INSERT INTO authors (id, emoji) VALUES (8, '🇵🇱');
INSERT INTO author_translations (author_id, language_code, name) VALUES (8, 'zh', '亨利克·显克维奇'), (8, 'en', 'Henryk Sienkiewicz');
-- pick #5 · weread bookId=32880022 · 你往何处去 · 79 条划线
INSERT INTO books (id, author_id, emoji) VALUES (8, 8, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (8, 'zh', '你往何处去'), (8, 'en', 'Quo Vadis');

INSERT INTO quotes (id, book_id) VALUES (311, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (311, 'zh', '我要和她生活在一起，直到我的头发变得像寒冬腊月的索拉克特山峰那样苍白。');
INSERT INTO quotes (id, book_id) VALUES (312, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (312, 'zh', '她那双泪水浸湿的眼睛、披散在脑后的金发，和她那表露着畏怯和祈求的面孔显得格外地动人，再者她又是那么乞求地望着他，使得裴特罗纽斯这个崇尚爱情威力的哲学家和敬重一切美好事物的审美家也对她产生了同情。');
INSERT INTO quotes (id, book_id) VALUES (313, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (313, 'zh', '维尼茨尤斯听到她这些话，就像当头挨了一棒似的跳了起来，不对，她恨他。');
INSERT INTO quotes (id, book_id) VALUES (314, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (314, 'zh', '维尼茨尤斯忧郁地问道。');
INSERT INTO quotes (id, book_id) VALUES (315, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (315, 'zh', '他的情绪越来越激动，到后来已经失去了常态，连阿克台也看得出他在信口开河，嘴里说的实际上做不到，是愤怒和痛苦使得他这么胡言乱语。');
INSERT INTO quotes (id, book_id) VALUES (316, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (316, 'zh', '但她的话并没有消除维尼茨尤斯的怒火。在维尼茨尤斯看来，莉吉亚既然是皇帝赐给他的，他就不用去细问她的出身了。他就是下到地狱里去，也要把她找回来，只要找回了她，他爱怎么处置都可以。');
INSERT INTO quotes (id, book_id) VALUES (317, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (317, 'zh', '维尼茨尤斯总算松了一口气，他觉得那最可怕的威胁对他来说已经不存在了');
INSERT INTO quotes (id, book_id) VALUES (318, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (318, 'zh', '维尼茨尤斯突然怒火中烧。');
INSERT INTO quotes (id, book_id) VALUES (319, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (319, 'zh', '维尼茨尤斯本来想平心静气地向她问个明白，但他忍受不了自己的痛苦和愤怒，因此又双手抱着脑袋，把脸绷得紧紧的，不停地说');
INSERT INTO quotes (id, book_id) VALUES (320, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (320, 'zh', '维尼茨尤斯抓住阿克台的手，把她拉到客厅中间，对她叫唤道');
INSERT INTO quotes (id, book_id) VALUES (321, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (321, 'zh', '她宁愿以流浪为生，忍受贫困和耻辱，不管明天怎么样，甚至悲惨地死去，也不愿住在豪华的府邸里，接受爱她的人的宴请，这算什么爱情呢？');
INSERT INTO quotes (id, book_id) VALUES (322, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (322, 'zh', '他的一双眼睛冒出了火花，嘴里乱七八糟地抛出了一个又一个的问题。妒忌和愤怒像狂风暴雨似的对他进行着轮番的扫荡。');
INSERT INTO quotes (id, book_id) VALUES (323, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (323, 'zh', '裴特罗纽斯从来没有到过这里，在他的想象中，这个严厉的家庭一定是充满了悲戚的。可是他环顾四周，这个客厅给他的印象却是很不错的，这不仅使他感到奇怪，而且使他感到有点失望。');
INSERT INTO quotes (id, book_id) VALUES (324, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (324, 'zh', '当我看见朝霞的微光照在她的身上的时候，我以为只要太阳一升起，她就会和朝露一起消失在阳光里。');
INSERT INTO quotes (id, book_id) VALUES (325, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (325, 'zh', '我对罗马并不熟悉，既不了解这里的生活，也不知道什么叫爱情。');
INSERT INTO quotes (id, book_id) VALUES (326, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (326, 'zh', '太阳向奥斯提亚的方向更加倾斜过去了，变得又红又大，因此在西边的天空里闪出了万道红光。');
INSERT INTO quotes (id, book_id) VALUES (327, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (327, 'zh', '可是他现在知道了，在远方把生命的结束想象为安乐的沉睡是一回事，亲眼看着一个比自己的生命更加宝贵的灵魂被残害致死，就完全是另一回事了。');
INSERT INTO quotes (id, book_id) VALUES (328, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (328, 'zh', '他们都以为自己进入了永恒的世界。他们叙说着永恒的爱情，叙说着将来在坟墓那一边如何相爱和生活在一起。如果他们有时候也转而想到了现实的话，那他们就和那些正要出门作长途旅行的人一样，只知道谈论出发前如何做好准备的事。');
INSERT INTO quotes (id, book_id) VALUES (329, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (329, 'zh', '就狮子和老虎在撕碎人体上谁胜过谁的问题还发生了争论，甚至形成了两派对立的观点。许多地方都有一些人在互相打赌。有的还谈到了在基督徒出场之前会有一些角斗士来进行比武，对这种比武的看法又分成了好几派，有的欣赏萨姆尼特人的比武，有的爱看高卢人的表演，有的喜欢密尔密隆人、特拉克人和撒网角斗士。');
INSERT INTO quotes (id, book_id) VALUES (330, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (330, 'zh', '裴特罗纽斯料定，帕拉丁宫里不会有人知道他们的住处，维尼茨尤斯一定能在禁卫军来到之前赶到那里，把他们救出来。此外他还想到了另外一种可能出现的情况：蒂盖里努斯想一举抓获尽量多的基督徒，他一定会把禁卫军分成许多小队去各处活动，在全罗马城布下天罗地网。但他们如果只派了十来个士兵来抓她，那个莉吉亚人就算一个人也会把他们的骨头全都打断，更不用说还有维尼茨尤斯相助了。');
INSERT INTO quotes (id, book_id) VALUES (331, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (331, 'zh', '他讨厌这座城市，也仇恨城里的百姓。他只爱他的诗歌。当他终于看见一场和他正要描写的内容差不多的悲剧已经发生的时候，他再也压制不住心中的狂喜了。这个蹩脚的诗人终于感受到了他所期盼的幸福，这个朗诵家终于产生了伟大的激情，这个孜孜不倦的探索者在他见到的这幅凶险可怕的图景中也终于找到了灵感。');
INSERT INTO quotes (id, book_id) VALUES (332, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (332, 'zh', '我知道，要攀登那个奥林匹斯的世界，就非得做出一番前人没有做过的事业不可。无论是行善还是作恶，都要做得比那些凡夫俗辈更加出色。我知道我这么做，一定会被人看成是发了疯，可是我并没有疯，我一直在寻找，如果我真的发了疯，那不过是因为我找不到我要寻找的东西而感到心焦和烦闷的一种表现。');
INSERT INTO quotes (id, book_id) VALUES (333, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (333, 'zh', '这样的诗如果是维吉尔或者奥维修斯写的，或者甚至荷马写的，都算得上他们的上乘之作，可是它和陛下就不相称了，陛下不会写这样的劣等诗。在这首诗中，既没有把大火描写成熊熊烈焰，也没有把猛烈的火势写出来。你可不要听信琉康的吹捧，他要是写出了这样的诗，我承认他是天才，但陛下就不一样了。你知道这是为什么吗？因为陛下是个伟大的人物。诸神赐予陛下伟大的才华，对陛下也就要求更高了。可是陛下你写诗却不很努力，你吃过饭后要躺下来休息，而不愿坐在桌旁尽心地思考，真正下一番功夫。陛下本来可以写出世上从来没有过的伟大作品，所以我才敢冒犯天颜，直言相劝：快点写出杰作来吧！”');
INSERT INTO quotes (id, book_id) VALUES (334, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (334, 'zh', '我当时就想，波贝亚为了尼禄抛弃了两个丈夫，还有卡尔维亚·克雷斯披尼娜，还有尼吉蒂亚以及我认识的所有的女人，除了蓬波尼亚之外，几乎都把忠贞不渝和海誓山盟当成商品。');
INSERT INTO quotes (id, book_id) VALUES (335, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (335, 'zh', '在尼禄时代，人不过是一只蝴蝶，靠尼禄恩惠的阳光而活着，只要刮起一阵冷风，他就会死掉……不管他愿不愿意。');
INSERT INTO quotes (id, book_id) VALUES (336, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (336, 'zh', '他越是走进这座疯狂、野蛮和淫秽的森林里，就越是觉得莉吉亚从来没有像现在这样珍贵，这样纯洁和可爱。刚才他还想要开怀畅饮欢乐的美酒，参与那些纵欲无耻的活动，现在他对这一切又感到憎恶了');
INSERT INTO quotes (id, book_id) VALUES (337, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (337, 'zh', '喷泉');
INSERT INTO quotes (id, book_id) VALUES (338, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (338, 'zh', '她们玫瑰色的肉体在蔚蓝色的天空和湖水的衬托下，在金色乐器的映照下，仿佛把这些色调和反光全都吸进了她们的体内，化作鲜花万朵，争奇斗艳。');
INSERT INTO quotes (id, book_id) VALUES (339, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (339, 'zh', '还要说，你一直卧病在家，因为不能去那不勒斯听陛下演唱，感到很不安，这又加重了你的病情，后来因为有了能再听到陛下唱歌的希望，你才逐渐恢复了健康，');
INSERT INTO quotes (id, book_id) VALUES (340, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (340, 'zh', '你参观过那些金碧辉煌的希腊神庙吗？你像我那样，花了两年时间，换了一个又一个的导游人，把那些神庙全都看完了吗？你朝拜过科罗斯的神像 [4]吗？你到帕诺波和佛西达去看过普罗米修斯用来造人的黏土吗？或者去斯巴达见过勒达 [5]生的蛋吗？你去雅典见过用马蹄做的著名的萨尔马斯铠甲吗？或者去埃乌贝岛上见过阿伽门农的舰船吗？你见过照海伦左乳房的模样制造的杯子吗？你到过亚历山大港和孟菲斯吗？你见过金字塔吗？你见过伊西斯为了哀悼奥西里斯 [6]从她自己头上拔下来的头发吗？你听到过门农 [7]的呻吟吗？世界是那么辽阔，第伯河的对岸不能包括一切。');
INSERT INTO quotes (id, book_id) VALUES (341, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (341, 'zh', '但对这种差别，我和你的看法也是不同的：爱情只改变了你的嗅觉，从爱马鞭草变为爱紫罗兰，可是我呢？它把我的灵魂都改变了。');
INSERT INTO quotes (id, book_id) VALUES (342, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (342, 'zh', '他便恳求格劳库斯带他去找彼得，并且答应给贫穷的教区以丰厚的赠礼。他认为只要莉吉亚爱他，就消除了所有的障碍，每时每刻他都准备皈依基督。');
INSERT INTO quotes (id, book_id) VALUES (343, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (343, 'zh', '你在读我这封信时如果感到惊讶，那也不足为怪，因为我自己在写这封信的时候，就是很惊讶的，但我写的都是真情实话');
INSERT INTO quotes (id, book_id) VALUES (344, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (344, 'zh', '她是背着我逃走的，可是她逃走时，却给我留下了一个她亲手用黄杨树枝编织成的十字架。我醒来后，发现它就在我的床边。我现在把它供在神龛上，我自己也不明白，为什么我每次走到它的近旁，都觉得它上面有一种神圣的东西，便不由自主地对它产生了敬畏之情。我喜欢这个十字架，因为它是莉吉亚亲手做的，我又憎恨它，它把我们俩分开了。');
INSERT INTO quotes (id, book_id) VALUES (345, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (345, 'zh', '你知道，我是多么爱莉吉亚；你也知道，为了她，我没有什么事情做不出来。但即便是她的要求，我也没法把索拉克特山或者维苏威山扛在我的肩上，或者把特拉哲门湖置于我的掌心，我更不能把我的黑眼睛变成莉吉亚人的蓝眼睛。她要是那么要求我，我当然愿意那么去做，可是那超出了我的能力范围之外，我心有余而力不足啊！');
INSERT INTO quotes (id, book_id) VALUES (346, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (346, 'zh', '他还觉得他心灵中的那些把他和生活一直联系在一起的琴弦全都断了，又没有接上新的琴弦');
INSERT INTO quotes (id, book_id) VALUES (347, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (347, 'zh', '除了健康，我就没有别的祝愿了。我向波卢克斯起誓：我确实不知道，我还有什么要祝愿你的。');
INSERT INTO quotes (id, book_id) VALUES (348, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (348, 'zh', '在维尼茨尤斯看来，莉吉亚和他们不一样，她永远比她周围的人高贵一百倍，但他现在也开始注意观察这些社会下层贫穷的老百姓了，这是他一生中从来没有过的事情。在他们的身上，他还发现了各种值得注意的特点，要是过去，他根本就不会想到这些。');
INSERT INTO quotes (id, book_id) VALUES (349, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (349, 'zh', '维尼茨尤斯说着便用手捂住了他苍白的额头，闭上了眼睛，他的性情使他不论在发怒时，还是在恋爱时，都不知道有什么克制。他说话是那么激动不已，就像一个失去了自制的人，丝毫也不考虑语言和情感的分寸。');
INSERT INTO quotes (id, book_id) VALUES (350, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (350, 'zh', '他望着她的侧影，望着她往下垂着的睫毛和放在膝盖上的双手，在他那异教徒的脑子里经过一番艰苦的思想斗争，终于产生了一个新的概念：除了希腊和罗马引以为自豪和自信的那种形体美之外，世界上还有另外一种全新高洁的灵魂美。');
INSERT INTO quotes (id, book_id) VALUES (351, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (351, 'zh', '宙斯把她变成夜莺，使她永远为亲手杀死的儿子而啼泣');
INSERT INTO quotes (id, book_id) VALUES (352, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (352, 'zh', '因此当莉吉亚又来给他喂水时，他本来要握握她的手，现在也不敢了。就是这个维尼茨尤斯，他在皇帝举行的御宴上是那么蛮横无理地吻她，在她逃走后又发誓要揪住她的头发，把她拖进卧室里，下令鞭打她，可现在却什么都害怕了。');
INSERT INTO quotes (id, book_id) VALUES (353, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (353, 'zh', '这个渔夫最初给他的印象，本来是一个很普通的人，而现在却是那么可怕，就好像是一位神秘莫测的命运之神，毫不留情地判给了他悲剧的命运。');
INSERT INTO quotes (id, book_id) VALUES (354, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (354, 'zh', '而这位老人却认为美德和善良是永生不灭的。这种不灭不是埋在地下的那种可怜的不灭，不是寂寞和空虚的不灭，它是一种壮丽无比的不灭，可以和永生不灭的神媲美。');
INSERT INTO quotes (id, book_id) VALUES (355, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (355, 'zh', '这是维尼茨尤斯今天无论在哪个国家，在哪一种仪式上或者哪一个神庙中都没见到过的。');
INSERT INTO quotes (id, book_id) VALUES (356, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (356, 'zh', '要小心，像我这样的哲学家，只要向老百姓证明没有你这个神，他们就再也不会给你上供了。跟哲学家搞好关系，对你是有好处的。”');
INSERT INTO quotes (id, book_id) VALUES (357, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (357, 'zh', '这些基督徒是多么善良啊！可是人们却把他们说得那么坏。诸位神明在上！这个世界到底还有没有正义呢？就以基督教不允许杀人来说，我是很爱这种教义的。既然不许杀人，那当然也不许盗窃，不许欺骗，不许做假证明，要做到这些，也确实不容易。');
INSERT INTO quotes (id, book_id) VALUES (358, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (358, 'zh', '他似乎感到她在经历了一次长途旅行之后就要回到家里来了。他还要把奴隶们召集起来，叫他们用花环把房子装饰一下。此时此刻，他也不再怨恨乌尔苏斯了，他要宽恕所有的人，原谅所有的事情。基隆过去给他效过许多劳，但他一直很讨厌他。现在，他终于感到这个人很有趣，很不平常。他觉得自己家也变得更加明亮了，他的眼睛和面孔也亮起来了。他变得年轻了，重新感受到了生活的乐趣。过去那种阴森森的折磨人的痛苦使他无法知道他对莉吉亚到底爱到了什么程度。');
INSERT INTO quotes (id, book_id) VALUES (359, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (359, 'zh', '但愿你的头上晴空万里，如果有云的话，就让它显现出玫瑰色，散发出玫瑰的芳香。祝你健康，再见！……');
INSERT INTO quotes (id, book_id) VALUES (360, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (360, 'zh', '你信不信，像我这样的人，本来还有一点理智和判断力，也陶醉在这种幻想中。');
INSERT INTO quotes (id, book_id) VALUES (361, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (361, 'zh', '可是现在，他却深信他脚下的这块土地还是和原来一样没有改变，也没有神明来报复他，因此他就装腔作势，要以悲剧命运的表演来打动人。有时他在夜里突然跳起来，把我们全都叫醒，说什么复仇女神正在追踪他。他老是望着背后，装出一个喜剧演员扮演奥列斯特 [3]的姿势，但他只够得上一个蹩脚的喜剧演员。');
INSERT INTO quotes (id, book_id) VALUES (362, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (362, 'zh', '我最亲爱的 [1]！维纳斯把你的思想全都搞乱了。她夺走了你的理智和记忆力，让你整天除了想你的爱情之外，别的什么也不知道。过些时候，你再读读你给我的回信吧！你会知道你的心中除了莉吉亚外，对别的一切都是非常冷淡的。');
INSERT INTO quotes (id, book_id) VALUES (363, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (363, 'zh', '老爷，我身穿破旧的衣裳，是个犬儒派；我能忍受贫困，是个斯多噶派。我没有轿子，只能徒步从一家酒店走到另一家酒店，路上如果有人给我买一壶酒，我就教他本事，所以我又是个逍遥派。');
INSERT INTO quotes (id, book_id) VALUES (364, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (364, 'zh', '他还不老，在他脏乱的胡须和拳曲的头发中，只不过稀稀疏疏地现出了几根斑白的发丝。他的肚子瘪下去了，肩膀有些弯曲，乍一看像个驼背。驼背上竖着一个硕大的脑袋，脑袋上长着一副像猴子又像狐狸的面孔和一双咄咄逼人的眼睛。他的面孔呈现黄疸色，上面长着斑斑点点的丘疹，还有那布满鼻梁的红疹表明他酗酒。此人也不讲究衣着，身穿一件黑羊毛衫和一件满是窟窿的外套，说明他不是真穷就是装穷。');
INSERT INTO quotes (id, book_id) VALUES (365, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (365, 'zh', '皇宫里的院子和走廊上挤满了人，他们一个个都显露出了忐忑不安的神色。在宫里的奴仆中间，还混杂着一些武士和元老院的元老，他们到这里来，也是想要知道小公主的健康状况，这些人在宫中露面，尤其是在奴仆们中露面，的确显示了他们一片关切的热忱。“小女神”染病的消息很快就传出去了。因此宫门外不断地有人前来探望，而且越来越多，不一会儿，通过拱门向外望去，已经是人山人海了');
INSERT INTO quotes (id, book_id) VALUES (366, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (366, 'zh', '他就像一个溺水的人，一瞬间便想起了自己的整个一生。莉吉亚的身影在他的眼前慢慢地移过，他看见了她，听到了她说的每一句话。他看见她在喷泉旁，在普劳茨尤斯的家里，在那次宴会上。他觉得她又回到了他的身边，他已经闻到了她头发的香气，感觉到了她身体的温暖，而且重又享受到了他在宴会上使劲亲吻她那天真无瑕的嘴唇时享受过的快乐。');
INSERT INTO quotes (id, book_id) VALUES (367, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (367, 'zh', '觉得莉吉亚是一个奇迹，是神明显圣，是诸神掌上的明珠，她比御花园中的百花，比皇宫中的精雕都要美丽千百倍。阿克台对她并没有妒忌的心思，相反的是，她一想到这个姑娘会遇到许多凶险，就特别怜悯她，由此也激起了她对姑娘的母亲似的怜爱。');
INSERT INTO quotes (id, book_id) VALUES (368, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (368, 'zh', '但过了一会儿，她的脑子里又产生了另外一个印象：这个孩子，她宁愿逃走也不做维尼茨尤斯的情妇，她宁愿一贫如洗也不愿蒙受耻辱，宁愿漂流四方也不愿享受她在卡雷纳街上的豪华的住宅和那些漂亮的衣着、首饰、上等的筵宴以及诗琴和芦笛的美妙的音乐。 “这是为什么？”');
INSERT INTO quotes (id, book_id) VALUES (369, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (369, 'zh', '克台觉得她深深爱着的这个皇帝虽然过去一直被她看成是一个半神半人的人物，现在也和一个普通奴隶一样，粪土不如。这座用努米提亚大理石圆柱支撑起来的皇宫比一堆乱石也好不了多少。');
INSERT INTO quotes (id, book_id) VALUES (370, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (370, 'zh', '克台却不理解她。把所有的一切，把家庭、财产、城市、花园、神庙、圆柱走廊全都抛弃，把所有美丽的东西，把阳光普照的国土和自己的亲人全都抛弃，这究竟是为了什么？难道只是为了逃避一个年轻漂亮的军官的爱情');
INSERT INTO quotes (id, book_id) VALUES (371, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (371, 'zh', '维尼茨尤斯的醉意不浅，因此他心中除了情欲的冲动之外，还想寻衅闹事，他每次喝醉了酒都是这样。他那黑油油的脸庞也变白了，说起话来颠三倒四，随后他便以命令的口气大声地叫了起来。');
INSERT INTO quotes (id, book_id) VALUES (372, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (372, 'zh', '可是现在，我就像一盏油灯放置在太阳光下，已经暗淡无光了。');
INSERT INTO quotes (id, book_id) VALUES (373, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (373, 'zh', '至于歌词中的诗句，我倒希望写得比这差一点为好，那样我就可以找到适当的言辞来加以赞美了。”');
INSERT INTO quotes (id, book_id) VALUES (374, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (374, 'zh', '可是琉康又以艺术和人类的名义向他再一次地提出了请求。大家知道，这位神传天赋的诗人和歌手已经写成了一首《维纳斯颂》，和这首伟大的《维纳斯颂》相比，就连卢克莱修 [8]的颂歌也会变得像狼崽嚎叫一样难听。让这次宴会成为一次名副其实的盛会吧！好心的君王是不会叫他的臣民失望的：“陛下，可别狠心啊！');
INSERT INTO quotes (id, book_id) VALUES (375, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (375, 'zh', '的脸色顿时变得苍白，他的鼻孔在不停地翕动，就像一匹东方的骏马那样。他的心在急剧地跳动着，这从他那件上下起伏着的紫红色的衬衣下面可以看得出来。他的呼吸十分短促，说起话来上气不接下气，他和她靠得这么近还是第一次。');
INSERT INTO quotes (id, book_id) VALUES (376, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (376, 'zh', '这时对亲爱的蓬波尼亚·格列齐娜和普劳茨尤斯的宁静祥和的家庭骤然产生了一种无法表达的深切思念，她终于想到只有那里才是一个爱和没有暴虐的世界。');
INSERT INTO quotes (id, book_id) VALUES (377, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (377, 'zh', '她自己也说不清，促使她做出这个决定的，到底有几成是想见到维尼茨尤斯和裴特罗纽斯的愿望，有几成是女人的好奇心，想在一生中能够见到一次这样盛大的宴会，见到宴会上的皇帝，见到宫殿、闻名于世的波贝亚和其他的天姿国色，还有那闻所未闻的在罗马被称为神奇的奢侈和豪华。');
INSERT INTO quotes (id, book_id) VALUES (378, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (378, 'zh', '你当然可以坚持你的信仰，但是你也不要轻易地毁了自己，不要为了一点小事去冲撞这位人间残酷的上帝。”');
INSERT INTO quotes (id, book_id) VALUES (379, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (379, 'zh', '他整天唉声叹气，把他的家里都要变成一座蒸气浴池了');
INSERT INTO quotes (id, book_id) VALUES (380, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (380, 'zh', '过去在战场上，不列颠军队只要看见他的眉头这么一皱，就会吓得丧魂落魄，现在，作为钦差的哈斯塔的脸上也露出了害怕的神色。');
INSERT INTO quotes (id, book_id) VALUES (381, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (381, 'zh', '她使我想起了春天！这不是我们意大利的春天，在我们的意大利，只有稀稀落落几株开着花的苹果树，橄榄树还是以前那种灰暗的颜色');
INSERT INTO quotes (id, book_id) VALUES (382, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (382, 'zh', '是一种光明，一种恬静，一种在他们生活中直接表露出来的从容不迫。');
INSERT INTO quotes (id, book_id) VALUES (383, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (383, 'zh', '他们身上的白衣在夕阳余晖的映照下，闪耀着金色的光辉。天空中的红霞逐渐染上了一层紫色或堇色，最后变成了一块白色的宝石，整个天空都呈现出了百合花的颜色。柏树黑色的姿体比白天显得更加清晰可见，在人和树之间，在整个花园里都充满了黄昏的宁静。');
INSERT INTO quotes (id, book_id) VALUES (384, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (384, 'zh', '现在树叶还没有脱落，晴朗的天空在对罗马表示友好的微笑，不可失去这个美好的时机。一旦葡萄叶儿变得枯黄，阿尔班山上降下了大雪，诸神在坎帕尼亚平原上刮起了刺骨的寒风，到那时候，谁知道，他的全家也许就得搬到乡下那座寂寞的庄园里去了。');
INSERT INTO quotes (id, book_id) VALUES (385, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (385, 'zh', '福波斯');
INSERT INTO quotes (id, book_id) VALUES (386, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (386, 'zh', '太阳早已越过了第伯河，渐渐沉落在雅尼库尔的山陵上，在一动不动的柏树上撒下了万道霞光，使整个天空都变得红通通的了');
INSERT INTO quotes (id, book_id) VALUES (387, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (387, 'zh', '富人有凌驾于他的更加富豪的人，显赫者在显赫于他的人面前会变得渺小，强权也会被强权征服的');
INSERT INTO quotes (id, book_id) VALUES (388, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (388, 'zh', '觉得他说出了以前就在她的心上可她却不知道如何表达出来的东西，而且他也唤醒了她身上一直沉睡着的东西。因此就在这个时刻，她的朦胧的梦境变得愈来愈清晰，愈来愈令人心醉了');
INSERT INTO quotes (id, book_id) VALUES (389, 8);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (389, 'zh', '看，维泰留斯要清洗他的肠胃，就把象牙筷子插在自己的喉咙里。有的人用火烈鸟羽毛沾上一点橄榄油或者百里香汁，放到嘴里后，也能把吃的东西全吐出来。我呢？我只要朗读一下尼禄的诗，就会产生同样的效果。因此我要感谢他，要对他的诗歌大加赞美一番，这种感谢虽然不是出自我纯洁的良心，但至少是出自干净的肠胃。”');

-- 新建作者 pick #7 · 丹·西蒙斯
INSERT INTO authors (id, emoji) VALUES (9, '🇺🇸');
INSERT INTO author_translations (author_id, language_code, name) VALUES (9, 'zh', '丹·西蒙斯'), (9, 'en', 'Dan Simmons');
-- pick #7 · weread bookId=926346 · 海伯利安四部曲 · 189 条划线
INSERT INTO books (id, author_id, emoji) VALUES (9, 9, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (9, 'zh', '海伯利安四部曲'), (9, 'en', 'Hyperion Cantos');

INSERT INTO quotes (id, book_id) VALUES (390, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (390, 'zh', '那样的生命又多么残酷……在无足轻重的琐事中，我们消磨完了那永不会再来的宝贵时光。');
INSERT INTO quotes (id, book_id) VALUES (391, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (391, 'zh', '我注意到，在这段悬崖夹道的河流两侧，草木生长得更为繁茂——常蓝植物、矮小的红杉——低斜的落日将高处的枝条涂上了鲜艳的颜色。');
INSERT INTO quotes (id, book_id) VALUES (392, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (392, 'zh', '她转身朝我微笑，自然而又明快，带着一种容光焕发的活力。');
INSERT INTO quotes (id, book_id) VALUES (393, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (393, 'zh', '“流水别墅，”她说，“在宾夕法尼亚西部的熊溪河畔。”');
INSERT INTO quotes (id, book_id) VALUES (394, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (394, 'zh', '这颗星球表面，不是不连续的陆地和海洋，而是一整块单一的大陆，上面镶嵌着数千狭长的咸水湖——“湖湾”，一道道犹如在台球桌的绿色绒布上留下的条条爪印。');
INSERT INTO quotes (id, book_id) VALUES (395, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (395, 'zh', '没有什么是写就的，所有一切都没有定数。我眼中的一切都像流沙，像美丽的沙画，瞬间就会被风吹散……”');
INSERT INTO quotes (id, book_id) VALUES (396, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (396, 'zh', '几分钟之前，我曾站在楼上俯瞰下面纵横交错的街道，瞥见落日的余晖染红了一座尖塔的侧面，但现在石塔成了暗灰色，只有天上的一缕卷云还闪着光彩。');
INSERT INTO quotes (id, book_id) VALUES (397, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (397, 'zh', '时空的构架和精美的梵蒂冈挂毯非常相像，尼弥斯想到，如果她扯松一根线，就是在冒极大的风险，可能会眼睁睁看着整张挂毯被拆散。');
INSERT INTO quotes (id, book_id) VALUES (398, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (398, 'zh', '屠宰完成之后，尼弥斯回到慢时间，那三头幻灵砰然倒在冰面上，如同三大口袋泔水。');
INSERT INTO quotes (id, book_id) VALUES (399, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (399, 'zh', '从地表上刮来一股冷风，咻咻卷入地下两百米的冰川深处，那声音听起来就像是冰冻的星球正在尖叫。');
INSERT INTO quotes (id, book_id) VALUES (400, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (400, 'zh', '但我母亲告诉我，只要有朋友，有吃的，有交流，那就不存在惩罚或痛苦了。');
INSERT INTO quotes (id, book_id) VALUES (401, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (401, 'zh', '他那补丁织缀的法衣，要是穿在别的缺少高贵气质的人身上，便会充满滑稽的意味');
INSERT INTO quotes (id, book_id) VALUES (402, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (402, 'zh', '洪亮的低音从那庞大的躯体中发出，轰隆咆哮，犹似从地底涌来。');
INSERT INTO quotes (id, book_id) VALUES (403, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (403, 'zh', '卢杜萨美身材臃肿，身上覆着红色丝绸、白色亚麻、深红色天鹅绒，整个人活似一座地质山丘，一层层下巴上顶着巨大的头颅，上面长着小嘴、精明的小眼睛、几乎秃顶的脑瓜，还戴了顶深红的无檐便帽。');
INSERT INTO quotes (id, book_id) VALUES (404, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (404, 'zh', '我知道，我的反应就跟一截冻住的木头差不多，感知力也好不过那些在我三角形视野中移动的冰钟乳，我的意识就跟它们一样，底部被提灯的光芒照亮，顶端却迷失在黑暗和迷雾中。');
INSERT INTO quotes (id, book_id) VALUES (405, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (405, 'zh', '意识微弱得如同一条细线，将我连到一丝光明之中，寒风吹过我的身体，意识也在其中飘摇。');
INSERT INTO quotes (id, book_id) VALUES (406, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (406, 'zh', '那共享温暖的记忆，第一次完全地分享生命力，总会让我冷静，平稳地度过人类恐惧的暴风雨。');
INSERT INTO quotes (id, book_id) VALUES (407, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (407, 'zh', '这里的冰寒俨然具有同样的力度，犹如某种缓慢燃烧的火苗，在将我的血肉切作碎片。');
INSERT INTO quotes (id, book_id) VALUES (408, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (408, 'zh', '冰墙之下一片漆黑，并且冷得找不到合适的词语来形容。');
INSERT INTO quotes (id, book_id) VALUES (409, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (409, 'zh', '保暖毯优雅地披在她身上，在提灯和立方体的光芒照射下，皮肤微微发亮，看起来像是从画里走下来的年轻圣母。');
INSERT INTO quotes (id, book_id) VALUES (410, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (410, 'zh', '迷雾从漆黑的水面升起，在冰窟凹凸不平的顶部萦绕不散，犹如溺毙者不祥的阴魂。');
INSERT INTO quotes (id, book_id) VALUES (411, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (411, 'zh', '窗外，落日已经西沉，但山峦依旧闪耀着白日里储藏的光芒。这种薄暮反应是这颗星球上的岩石所特有的，我觉得永远也看不厌。');
INSERT INTO quotes (id, book_id) VALUES (412, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (412, 'zh', '承认自己唯一能感觉到的，只有疼痛和高热，思维如同水银一般——在我抓住它们，或是将其凝聚出形状之前，它们就已经统统溜走。');
INSERT INTO quotes (id, book_id) VALUES (413, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (413, 'zh', '海水变得越来越温暖，似乎我的血液让它上升到了舒适的温度，引诱着我闭上双眼，向温暖的更深处游去，每过一分钟，诱惑就变得更加强烈一分。');
INSERT INTO quotes (id, book_id) VALUES (414, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (414, 'zh', '那人一身户外装束：法兰绒格子衬衫、帆布裤、帆布马甲——和我身上的差不了多少——腰带上挂有一把刮鳞刀。');
INSERT INTO quotes (id, book_id) VALUES (415, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (415, 'zh', '但我感觉到黑暗犹如一条越来越窄的隧道，逐渐包围住我的视野，虽然我不想失去武器，但太迟了——我感觉到它掉入了深海。');
INSERT INTO quotes (id, book_id) VALUES (416, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (416, 'zh', '他觉得自己像古老故事里讲的，一只瞎猫被派来抓耗子，既看不见，也没有能力同时提防两百个老鼠洞');
INSERT INTO quotes (id, book_id) VALUES (417, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (417, 'zh', '在做这些事的时候，我老感觉有人已暗中发现了我，禁不住有些背脊发麻。');
INSERT INTO quotes (id, book_id) VALUES (418, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (418, 'zh', '伊妮娅大笑。我得说，我当时爱极了伊妮娅的笑声，现在想起来，也让我心里暖意融融。那种轻柔的笑声，陶醉，毫不做作，十分悦耳。我怀念极了。');
INSERT INTO quotes (id, book_id) VALUES (419, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (419, 'zh', '跟旅行指南上的描述一样，大海是一片令人不安的紫罗兰色，整齐地冒着深蓝色的浪尖，那颜色深得发黑，其中偶尔夹杂着黄藻床或者更加深紫的泡沫。');
INSERT INTO quotes (id, book_id) VALUES (420, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (420, 'zh', '天空的颜色逐渐变亮，先是深蓝色，然后是钴蓝色，两颗明晃晃的太阳和一颗橙色的月亮填满了身后的天空。');
INSERT INTO quotes (id, book_id) VALUES (421, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (421, 'zh', '父亲认为，相比我们对大自然的回应，人类之间真正的友谊是更高的阶段，但我们可以达到的最高阶段是爱');
INSERT INTO quotes (id, book_id) VALUES (422, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (422, 'zh', '那颗惊世骇俗的月亮还在缓缓升起，升入惊世骇俗的灿烂星空。');
INSERT INTO quotes (id, book_id) VALUES (423, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (423, 'zh', '的第一反应是以一个个否定句来衡量周遭的环境：这不是那颗丛林星球；我们不在河流上——而是一片海洋，夜空下，无边无际的大海向四周伸展着；这里不再是白天；我们没有沉没。');
INSERT INTO quotes (id, book_id) VALUES (424, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (424, 'zh', '这一晚，我们听见了雷声——隆隆巨响，就仿佛有人在岩石台阶上滚着庞大的铁桶，正往下朝我们奔来。');
INSERT INTO quotes (id, book_id) VALUES (425, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (425, 'zh', '太阳就在我们身后，几乎已经下山，有几分钟，河水红灿灿的，就像是滚滚的熔岩，河流两侧，裸子树木的下部被反射的光线照亮，似乎也在熊熊燃烧。天色逐渐变暗，最后变黑，我们还没看到一眼夜空，云层就从东面涌来，一如昨夜。');
INSERT INTO quotes (id, book_id) VALUES (426, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (426, 'zh', '第二天天一亮，我们便开始行动，我还记得那天早上，各种感受混杂交集，骨头酸痛，眼睛周围全是沙子，脸上的胡茬越发欣欣向荣，背部疼痛，心底里却非常喜悦——野营旅行的第一个晚上，我一般都是这个感受。');
INSERT INTO quotes (id, book_id) VALUES (427, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (427, 'zh', '那晚上深深烙刻在我记忆中的，除了飞速蔓延的妄想症和极端的疲倦外，就是眼前沉睡的伊妮娅，她褐中带金的长发披散在红色的睡袋边缘，拳头举到脸颊旁，就好像一个婴孩正想要吸吮大拇指。');
INSERT INTO quotes (id, book_id) VALUES (428, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (428, 'zh', '“为什么？​”飞船问道，​“那东西和你们的旅途并无关系，为什么要去调查？​”伊妮娅凑过来，抬起我的手腕。​“因为我们是人类。​”她说。');
INSERT INTO quotes (id, book_id) VALUES (429, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (429, 'zh', '但丛林已经派出了藤蔓和青苔的小分队，占领了这庞然大物的顶部和两侧。');
INSERT INTO quotes (id, book_id) VALUES (430, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (430, 'zh', '抛下贝提克一个人做搬运的重活，我心里有点愧疚，但我们必须知道下一个远距传送门离我们有多远，这看上去比较明智，我打心底里不想让女孩一个人飞去干侦察任务。');
INSERT INTO quotes (id, book_id) VALUES (431, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (431, 'zh', '我们走到河边，坐在水里冒出的一截树桩上，望着太空船。这可怜的东西看上去就像是旧地野生动物全息像中的大鲸鱼，一头搁浅了的大鲸鱼。');
INSERT INTO quotes (id, book_id) VALUES (432, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (432, 'zh', '我永远也无法描述那一时刻震撼我内心的那种激动——纵使经历了可怕的坠落，纵使是面临着巨大的困境，纵使一切的一切——我是在审视一个新世界！');
INSERT INTO quotes (id, book_id) VALUES (433, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (433, 'zh', '到那时，我们的白骨就会掉落在飞船的内部船体上，发出喀啦喀啦散架的声音，就像无形的算命师用于占卜的根根骨头。');
INSERT INTO quotes (id, book_id) VALUES (434, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (434, 'zh', '我手臂大张，右腿半弯在身后，摆着一副奔跑的姿势，嘴巴也张着，似乎在无声尖叫，我也没法眨眼。起初有一股强烈的窒息感，令人恐惧——那坠落场就罩在我大张的嘴巴里——但我很快就意识到，我的鼻子和喉咙正在呼吸着氧气。');
INSERT INTO quotes (id, book_id) VALUES (435, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (435, 'zh', '透过它，我能看到对面的城市灯光……不，现在，它似乎正微微闪光，就仿佛有一道水帘从金属拱门上落了下来。');
INSERT INTO quotes (id, book_id) VALUES (436, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (436, 'zh', '接着，外世界刮起了一场逆转录酶病毒的风暴，它就像一柄镰刀，沿着聚集地的牧场区一路收割，十二岁的马利亚也生病了。');
INSERT INTO quotes (id, book_id) VALUES (437, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (437, 'zh', '但是这么多年来我碰到的小孩子，没有哪个像伊妮娅这般喜欢倾听。');
INSERT INTO quotes (id, book_id) VALUES (438, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (438, 'zh', '我的中耳连连抗议，试图找到真正的地平线。但哪儿都不是。');
INSERT INTO quotes (id, book_id) VALUES (439, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (439, 'zh', '高重力星球的人都很矮很强壮，大多数皮肤惨白，一头黑发；这个小孩虽然还小，但是身高有一倍重力星球的普通水准，那一头褐发还夹带着金色的发丝，而且，她太瘦了。');
INSERT INTO quotes (id, book_id) VALUES (440, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (440, 'zh', '但是对霸主几十亿公民的绝大多数人来说，生活肯定就像是沉浸在无止境的视听、印刷信息的刺激模拟中。');
INSERT INTO quotes (id, book_id) VALUES (441, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (441, 'zh', '也许是因为旅途能使感知更加敏锐，也许是新环境往往会让感官做出相应的调整，抑或是熟悉新环境后，对周遭事物不再那么热衷，但是我的经验是，来到一个陌生之地、遇见陌生人的头几天，总能给旅途的余下时间定下基调。');
INSERT INTO quotes (id, book_id) VALUES (442, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (442, 'zh', '德索亚想要告诉他们，经历几次之后，就会变得容易应付了，但是他自己的身体和头脑却不住地摇晃，这宽心的话语也只能变成了谎言。');
INSERT INTO quotes (id, book_id) VALUES (443, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (443, 'zh', '我很顽固，有很多像我一样的人在年轻的时候离它远远的——我们都想永生，对不对？然后，当年纪不饶人的时候，他们就皈依了。​”');
INSERT INTO quotes (id, book_id) VALUES (444, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (444, 'zh', '在她思考的时候，嘴唇微微上翘，露出一丝笑容；在她认真说话的时候，她额头会出现细微的颦蹙；她的声音极其绵柔。');
INSERT INTO quotes (id, book_id) VALUES (445, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (445, 'zh', '“是六天九小时二十七分。​”飞船修正道。');
INSERT INTO quotes (id, book_id) VALUES (446, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (446, 'zh', '“也许我们该进去了。​”我说，从口中发出的每一个词音都独自悬荡在空气中，就像是树枝上的冰凌。');
INSERT INTO quotes (id, book_id) VALUES (447, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (447, 'zh', '我是说一种极其强烈的虚无，它导致的眩晕几乎马上让我作呕起来，并猛烈拷打着我的身体系统，那烈度堪比几秒钟前肠子被瞬间扯出来的感觉。');
INSERT INTO quotes (id, book_id) VALUES (448, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (448, 'zh', '直到那一刻，我终于发现自己对任何恐惧症都相当敏感。');
INSERT INTO quotes (id, book_id) VALUES (449, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (449, 'zh', '死亡和重生不可儿戏。在德索亚长大成人的过程中，这一戒律反复出现在他的基本信仰中，也阐明了他的观点。虽然圣礼真的存在，且授予给了信徒，但这并不意味着我们能胡乱、毫无节制地使用它。');
INSERT INTO quotes (id, book_id) VALUES (450, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (450, 'zh', '身体内的每一个细胞因为重生而剧烈疼痛，但是这疼痛是健康的疼痛，与伤口的可怕痛楚不一样。​“你');
INSERT INTO quotes (id, book_id) VALUES (451, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (451, 'zh', '孩子朝我莞尔一笑。​“你也得冲个澡。在来日的某天，我俩会一起洗，但现在，我觉得你得用沉眠舱的那个。​”');
INSERT INTO quotes (id, book_id) VALUES (452, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (452, 'zh', '我也没有屈服于内心的冲动，没有将记忆一下子跳跃到近几年的时光，虽然我心中充满了恐惧，我怕我的故事将随时被发出嘶嘶声的薛定谔毒气打断。我会写下所能写的一切，命运将会决定故事的终点。');
INSERT INTO quotes (id, book_id) VALUES (453, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (453, 'zh', '我曾担心，由于占据记忆的全是最近几年的事情，最近几年的景象，那早年的记忆会变得遥不可及');
INSERT INTO quotes (id, book_id) VALUES (454, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (454, 'zh', '德索亚命令道。他感觉自己像是在走入一条又长又黑的隧道。不管要说什么，他一定得马上说出来。​“听');
INSERT INTO quotes (id, book_id) VALUES (455, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (455, 'zh', '黑点在视线外围舞动，一团团，越来越多。');
INSERT INTO quotes (id, book_id) VALUES (456, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (456, 'zh', '“少尉，给我闭嘴，马上派中士过来，违命者死……不……违命者将被逐出教会。​”');
INSERT INTO quotes (id, book_id) VALUES (457, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (457, 'zh', '具备抗击、抗能性能的全聚合战斗装甲支离破碎地垂在那儿，就像廉价轮胎上的破烂橡胶。');
INSERT INTO quotes (id, book_id) VALUES (458, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (458, 'zh', '一架圣甲虫战斗装甲车卸下了伪装护盾，正歪歪斜斜地蹲坐在一块巨石之上。左侧导轨已经没了，后部急射小机枪的枪管也融化掉了，就像是扔进火中的蜡块。');
INSERT INTO quotes (id, book_id) VALUES (459, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (459, 'zh', '德索亚神父舰长的身体如沐春风，他的意识充满了愉悦。他泪流满面。');
INSERT INTO quotes (id, book_id) VALUES (460, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (460, 'zh', '德索亚脑中闪过往昔的记忆，当他还是个小男孩的时候，他站在故星齐胸的海水中，面对着凶狠的海浪，而潮水和回潮想方设法地要将他拉进满怀敌意的大海中。');
INSERT INTO quotes (id, book_id) VALUES (461, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (461, 'zh', '。暴风在怒号，神父舰长必须依靠红外线才能看清一切，但就算他拉下并封住护目镜，细小的沙粒依旧勇往直前，进入装甲战衣，钻进他的嘴巴。');
INSERT INTO quotes (id, book_id) VALUES (462, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (462, 'zh', '整个东部地平线闪耀着电光，噼啪直响，球状闪电在一棵棵百米高的特斯拉树之间跳跃，链状闪电缠绕在特斯拉和爆裂的普罗米修斯树间，凤凰木和偶然冒起的地火在上千个地方熊熊燃烧。');
INSERT INTO quotes (id, book_id) VALUES (463, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (463, 'zh', '他深吸一口气，默默发誓在至少十分钟内不再去看时间，然后走进了狮身人面像那阴森耸现的阴影中。');
INSERT INTO quotes (id, book_id) VALUES (464, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (464, 'zh', '一阵微风轻轻刮擦着附近茶马树梢上的枝叶。');
INSERT INTO quotes (id, book_id) VALUES (465, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (465, 'zh', '马丁·塞利纳斯的全息像清清嗓子，似乎准备要吐口水。“不是一块，”他咕哝道，“而是那块霍鹰飞毯。”');
INSERT INTO quotes (id, book_id) VALUES (466, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (466, 'zh', '凭其中一力，便能说服众多信徒，让他们抛下上帝的光明教义，遗弃灵魂的超度，转而侍奉魔王。');
INSERT INTO quotes (id, book_id) VALUES (467, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (467, 'zh', '他衷心感谢黑夜，因为它们遮掩了泪水；他知道，必须在会议中克制好自己。');
INSERT INTO quotes (id, book_id) VALUES (468, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (468, 'zh', '自杀的人会被立即逐出教会，因为在品尝了死亡的苦灰之后，他们会产生一种越来越强烈的激情感觉，就好像离上帝本尊越来越近了。如果对于自杀的惩罚没有那么严厉的话，重生会很容易上瘾。');
INSERT INTO quotes (id, book_id) VALUES (469, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (469, 'zh', '壮丽的小号音符突然鸣响，如金色的刀刃刺穿这片宁静，合唱队在欢快的乐声中高唱，渐高的管风琴音符回荡在巨大的空间中，然后一系列璀璨的光芒突然照射而下，照亮了慢慢出场准备举行弥撒的教皇和他的扈从。');
INSERT INTO quotes (id, book_id) VALUES (470, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (470, 'zh', '“敬愚蠢之事，”他说，“敬超凡之疯狂。敬荒唐之任务。敬沙漠中哭泣之弥赛亚。敬暴君之死。敬我们敌人之毁灭。”');
INSERT INTO quotes (id, book_id) VALUES (471, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (471, 'zh', '在你挚爱的海伯利安上，还没发生太大的变化，是不是，劳尔·安迪密恩？');
INSERT INTO quotes (id, book_id) VALUES (472, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (472, 'zh', '我所说的英雄，是指那些胆识过人、慷慨仁慈、成为传奇佳话的人，他们甚至因此被尊奉成神灵。我所说的英雄是文学意义上的，我们的主人公惯于采取一些强大而有效的行动，他的悲剧性缺陷将带他走向毁灭之路。');
INSERT INTO quotes (id, book_id) VALUES (473, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (473, 'zh', '窘迫地大出一口气，双手放在桌布上。手指似乎又迟钝又笨拙，不知道该怎么摆在精美的亚麻布上。');
INSERT INTO quotes (id, book_id) VALUES (474, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (474, 'zh', '“你想成为一名英雄，”他重复道，“你想成为那些创造历史的非凡人物之一，而不仅仅是注视着历史在你身边擦身而过，就像河水流过一块岩石。”');
INSERT INTO quotes (id, book_id) VALUES (475, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (475, 'zh', '我静静地在那儿坐了片刻，最后说道：“数十亿人尽可以做他们想做的，但我的生命对我来说很重要。我只是想让它……属于我自己。”');
INSERT INTO quotes (id, book_id) VALUES (476, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (476, 'zh', '我该如何解释，在经历几代的流亡、受排挤、动荡的土著生活之后，我们游牧部落脑中滋生出的疑病呢？我该怎么解释像我外婆和母亲这些人的激烈独立观呢？我该怎么解释通过教育和抚养带给我的遗产——那些贤明的严格要求和天生的怀疑态度呢？');
INSERT INTO quotes (id, book_id) VALUES (477, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (477, 'zh', '湿润的水汽扑向我的脸颊和眼睛。我回想起依姿在野鸭接近空旷的水域时殷切的表情，那已经恍如隔世。');
INSERT INTO quotes (id, book_id) VALUES (478, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (478, 'zh', '几分钟的时间内，我们没有交谈，四下里仅有服侍的机器人脚踏石板的轻柔响声、火盆中火苗的噼啪声、头顶上偶尔吹过的一丝夜风，还有我们咀嚼的声音。');
INSERT INTO quotes (id, book_id) VALUES (479, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (479, 'zh', '现在，他已经从一个肤如羊皮纸、双眼凹陷的木乃伊转变成餐桌上另一个老人——双眼放射出一种如饥似渴的眼神。');
INSERT INTO quotes (id, book_id) VALUES (480, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (480, 'zh', '我走到窗前等着，夕阳越发变得光辉灿烂，越发向地平线坠去，影子蹑手蹑脚地从大学顶上的山上爬了下来。');
INSERT INTO quotes (id, book_id) VALUES (481, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (481, 'zh', '日光涂抹在它流线型的侧面上，仿佛新月般的朝日正在一颗美丽的星球上冉冉升起，接着，德索亚毅然决然地扭头离去。');
INSERT INTO quotes (id, book_id) VALUES (482, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (482, 'zh', '“尽管意识不会记得死亡，但细胞会，它们会记住曾经经历的死亡。”');
INSERT INTO quotes (id, book_id) VALUES (483, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (483, 'zh', '我曾在一本书中读到过，许许多多个世界上的小孩画房子的时候，依旧是先画一个方盒，然后在顶上画个三角锥，一个长方形的烟囱，再描上一点盘旋的烟');
INSERT INTO quotes (id, book_id) VALUES (484, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (484, 'zh', '这是一艘太空飞船，它填满了塔楼的内部空间，就像一颗子弹被塞进了老式左轮枪的枪膛。');
INSERT INTO quotes (id, book_id) VALUES (485, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (485, 'zh', '我等着风慢慢平息，蹲起身，飞身跳起。在那晕眩的一秒内，我弯曲的手指在崩溃的石头和粉尘上扒寻，指甲弄破，却没有找到任何支撑点。但紧接着，它们碰到了旧窗台腐朽的边角，紧紧抓住。');
INSERT INTO quotes (id, book_id) VALUES (486, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (486, 'zh', '我回想着外婆背诵的那首史诗——回忆起在北部山丘照看羊群的那几个夜晚，几辆电池驱动的大篷车挤在一起，围成一个保护圈，好让我们过夜，淡淡的篝火丝毫也不能减弱天顶上群星和流星雨的光辉');
INSERT INTO quotes (id, book_id) VALUES (487, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (487, 'zh', '这么多事发生得实在是太快，在审判和死刑前短暂的时光里我强加给自己的平静已经从我这索取了太多东西了。');
INSERT INTO quotes (id, book_id) VALUES (488, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (488, 'zh', '一艘现代的火炬舰船上，船员仅仅包括十几名军官，加上另外五六个其他人员。');
INSERT INTO quotes (id, book_id) VALUES (489, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (489, 'zh', '索亚是名矮个男子，按标准算，年纪差不多有三十五六岁，圆圆的脸蛋，黑黑的皮肤，几年来，朋友们都注意到他那双眼睛反射出的更多是司铎似的慈悲，而非军人的冷酷无情。现在，它们则充满了困惑。');
INSERT INTO quotes (id, book_id) VALUES (490, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (490, 'zh', '他们能看见光束，仅仅是因为现在纷乱的胶体微粒已经灌满了整个空间，就像是陈旧阁楼中扬起的灰尘');
INSERT INTO quotes (id, book_id) VALUES (491, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (491, 'zh', '意思就是说，如果内部的密蔽场突然失效片刻，那么，船员就会跟甲板上的一层树莓酱毫无二致。');
INSERT INTO quotes (id, book_id) VALUES (492, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (492, 'zh', '秋风拂面，我畅快地呼吸着，却又不禁莞尔：不管前面有着什么不可思议的事情在等待着我，只要能活下来，那还有什么不愉快的呢。');
INSERT INTO quotes (id, book_id) VALUES (493, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (493, 'zh', '古老怪物朝我低声细语时，嘴里呼出的气就像是从敞开的墓冢中盘旋而出的干风——没有什么气味，但是极为古老，不知何故还带着那些被遗忘世纪的芬芳');
INSERT INTO quotes (id, book_id) VALUES (494, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (494, 'zh', '此时，故事又中断了片刻，就好像这老头是台机器，偶尔会停掉，需要把内部的发条重新拧一下，才能再次开动。');
INSERT INTO quotes (id, book_id) VALUES (495, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (495, 'zh', '老人发出一阵干巴巴、飒飒的响声，似乎气管被梗住了，不过过了一会儿我才意识到，那其实是吃吃的笑声。');
INSERT INTO quotes (id, book_id) VALUES (496, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (496, 'zh', '黑色的眼睛审视着我，那眼神一如专业的猎手在审视小狗崽，判断它们能不能成为上佳的猎犬。');
INSERT INTO quotes (id, book_id) VALUES (497, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (497, 'zh', '那张脸又露出了笑意，但是眼神却和墙上的岩石一样亘古不变。');
INSERT INTO quotes (id, book_id) VALUES (498, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (498, 'zh', '声音听上去如同一把钝剑在刮擦羊皮纸。老人的嘴嚅动着，就像是海龟的唇缘。');
INSERT INTO quotes (id, book_id) VALUES (499, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (499, 'zh', '这老人的姿势让我想到一只皱巴巴、没有羽毛的雏鸟，却从鸟窝中掉了出来。');
INSERT INTO quotes (id, book_id) VALUES (500, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (500, 'zh', '午后的日光从红黄相间的彩色玻璃窗涌入。至少有一扇窗户开着，风从山谷中升涌而起，从遥远的下方传来树叶华盖发出的飒飒声。');
INSERT INTO quotes (id, book_id) VALUES (501, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (501, 'zh', '放眼望去，黄色的茶马和盘根错节的低矮堰木在山岭上织出一顶实心树梢华盖，一直延绵到地平线外。');
INSERT INTO quotes (id, book_id) VALUES (502, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (502, 'zh', '这房间的形状就像个圆形的馅饼，四周是涂着白水泥的弧形石墙，天花板上则刷着厚厚的灰泥。');
INSERT INTO quotes (id, book_id) VALUES (503, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (503, 'zh', '我躺在那儿，呆呆地望着阳光徐徐爬过粗糙的灰泥天花板，过了一分多钟，一丝急切的想法让我猛然清醒过来。');
INSERT INTO quotes (id, book_id) VALUES (504, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (504, 'zh', '那些经死亡之杖行刑后又重生的人通常都不愿谈及个中感觉，但是牢房中有传闻说，那痛苦得就像是堕入了十八层地狱——就仿佛大脑里所有的回路都爆炸了。');
INSERT INTO quotes (id, book_id) VALUES (505, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (505, 'zh', '我一生的主题曲就像是那同样冥顽不灵的倔强，而正是那倔强，让我拒绝了重生的机会。');
INSERT INTO quotes (id, book_id) VALUES (506, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (506, 'zh', '“我不需要十字形的寄生虫寄生在我体内，让我成为永世不得超脱的奴隶。”');
INSERT INTO quotes (id, book_id) VALUES (507, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (507, 'zh', '。对于坚决遵照圣典的再生基督徒而言，不能强迫他们四个中的任何一个在吐真剂或任何化学、电子查证方式的作用下作证。');
INSERT INTO quotes (id, book_id) VALUES (508, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (508, 'zh', '。我依旧抓着她的项圈，她的身体依旧匍在我身上，前爪仍旧在我胸膛上颤抖。被干净利落一切两段的脖子喷涌出一泉血水，泻在我的身上。我滚到一边，将还在痉挛的无头狗的尸身推开。血还是温热的，有一股铜的味道');
INSERT INTO quotes (id, book_id) VALUES (509, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (509, 'zh', '我看见依姿兴奋的双眼中闪过一丝异样的眼神，转瞬即逝。');
INSERT INTO quotes (id, book_id) VALUES (510, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (510, 'zh', '能量光束紧紧跟在它屁股后面肆意挥砍，如无声的镰刀割过树叶和枝丫');
INSERT INTO quotes (id, book_id) VALUES (511, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (511, 'zh', '第二只收起翅膀，一头栽倒，所有的优雅和美丽都被轰出了它的身躯。');
INSERT INTO quotes (id, book_id) VALUES (512, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (512, 'zh', '泥滩边，昆虫奏起的交响乐和两栖蟛的呱呱叫声逐渐淡去，取而代之的是清晨的鸟鸣声和雀鳝偶尔涨起战斗毒囊时发出的咕隆声。东方的天空正慢慢转深，幻化成白日的湛青色。');
INSERT INTO quotes (id, book_id) VALUES (513, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (513, 'zh', '依姿依旧坐在我叫她候命的地方，但从她紧绷的肌肉和闪光的眼神来看，她内心正如一条小狗狗般雀跃。');
INSERT INTO quotes (id, book_id) VALUES (514, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (514, 'zh', '让我得以看见他脖子上挂着的一条金光闪闪的圣神双交十字架，胸部靠上位置还有一条真实十字形的红色条痕。赫瑞格先生是名重生基督徒。');
INSERT INTO quotes (id, book_id) VALUES (515, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (515, 'zh', '沼泽地和湛江支流之间，有一片大拇指般狭长的页岩和烂泥地，上面坐落着一座被遗弃的纤维塑料庄园，我们总共有四个人在庄园外工作。');
INSERT INTO quotes (id, book_id) VALUES (516, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (516, 'zh', '唯有在明了我的余生几乎不会有什么伟大的奇迹发生之时，我才感到安心。');
INSERT INTO quotes (id, book_id) VALUES (517, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (517, 'zh', '那天，我的生命永远改变、故事真正开场的时候，我二十七岁，作为一个海伯利安人，个子还算高，除了手上厚厚的老茧，以及脑子里稀奇古怪的想法，就再没一点能令人注意的地方。');
INSERT INTO quotes (id, book_id) VALUES (518, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (518, 'zh', '亨特坐在西班牙广场上的这个小型前室的床头边，听着济慈在那儿胡言乱语。时间从拂晓转到上午，从上午跑向正午。');
INSERT INTO quotes (id, book_id) VALUES (519, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (519, 'zh', '他们的脸让我想起那些视觉谜题，你盯着它们，它们会变化形状；有时候，贝蒂的脸看上去无可置疑是张女性的脸，十秒之后，那性别的感觉竟无处可寻了，我再次把她（他？）当成了贝塔。');
INSERT INTO quotes (id, book_id) VALUES (520, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (520, 'zh', '我对着他们播放他们说过的话，他们只是笑笑，回到他们的小屋，在那儿一坐就是几小时，什么都不做，什么都');
INSERT INTO quotes (id, book_id) VALUES (521, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (521, 'zh', '我询问他们，用上巧妙的技巧，又小心，又慎重，还带着训练有素的人种学者的专业式冷静。我询问了最简单、最实际的问题，确信通信志工作正常。它的确工作正常。但是得到的全部回答让我几乎和二十多个小时前一样懵懂无知。');
INSERT INTO quotes (id, book_id) VALUES (522, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (522, 'zh', '他们身上缠着编织得极为粗陋的黑袍子，把他们从脖到脚裹了起来。这群人移动时，就像现在这样，看上去像是在崎岖不平的地上滑行，如同鬼魅一般。从远处看，他们的容貌让我想到新梵蒂冈孤立领土内一群缩小版的耶稣会士，真是太像了。');
INSERT INTO quotes (id, book_id) VALUES (523, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (523, 'zh', '那儿约有十几栋小屋，都是些粗制滥造的茅舍，由茶马叶、石头和海绵草皮建造而成，但它们肯定是由人类建造的，绝不会错。');
INSERT INTO quotes (id, book_id) VALUES (524, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (524, 'zh', '在当地是一百二十天，每天二十六小时。');
INSERT INTO quotes (id, book_id) VALUES (525, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (525, 'zh', '看不见的瀑布在底下的河流里翻腾，薄雾升腾而起，幕帘变换，从中激迸出的浪花将落日幻化成好几个紫罗兰色的球体，许许多多彩虹也一分为二。');
INSERT INTO quotes (id, book_id) VALUES (526, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (526, 'zh', '我穿上热力夹克');
INSERT INTO quotes (id, book_id) VALUES (527, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (527, 'zh', '昨天中午，我和塔克从火焰林的东北角走了出来，那边已经烧成一片灰烬。我们来到一条小溪边，在那儿迅速搭好帐篷，然后呼呼地睡了十八个小时；我们已经三晚没睡，而两个白天则是在火与灰的梦魇中不停赶路，完全没有休息过，现在，得好好补一下了。我们向陡峭的山脊接近，那是森林的终点。');
INSERT INTO quotes (id, book_id) VALUES (528, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (528, 'zh', '在特斯拉树的暴能猛烈发作的最初十秒钟内，至少释放出了一百条弯曲的闪电。离我们不足三十米处有棵普罗米修斯树，突然炸裂开来，燃烧着的木块散落在五十米开外的森林地被上。避电杆咝咝尖叫，荧荧发光，反射出我们小营地周围一条接着一条、弯弯曲曲的蓝白色死亡场景。');
INSERT INTO quotes (id, book_id) VALUES (529, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (529, 'zh', '浪漫港是一堆乱七八糟的黄色堰木建筑，堆砌在脚手架和厚木板的迷魂阵中，延伸至远处湛江江口的泥滩上。');
INSERT INTO quotes (id, book_id) VALUES (530, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (530, 'zh', '特斯拉树耸立在那儿，我们离它们尚有半公里。那棵树至少有一百米高，虽然和最高的普罗米修斯树比起来，特斯拉树的高度只有它的一半。在树冠处，它凸出一个显眼的洋葱形圆穹，那就是它的蓄电之瘿。树瘿上部辐射状的树枝蔓延开来，呈现出条条灵蔓，在明亮的绿蓝天空的映衬下，每一条都似银似金，闪闪发亮。这一切让我想到新麦加[插图]的某个雅致的至上穆斯林的清真寺，却被谁大不敬地戴上了金属丝花环。');
INSERT INTO quotes (id, book_id) VALUES (531, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (531, 'zh', '神父的故事：为上帝痛哭的人');
INSERT INTO quotes (id, book_id) VALUES (532, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (532, 'zh', '等到他铲光泥土，墓穴的表面还是微微下凹，就好像那尸体太微不足道了，连个小土垛都堆不起来');
INSERT INTO quotes (id, book_id) VALUES (533, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (533, 'zh', '杜雷正和谁并肩走着。空气凉飕飕的，天空是令人心碎的蓝色。');
INSERT INTO quotes (id, book_id) VALUES (534, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (534, 'zh', '索尔用去了一生的时间，希望无法返回的东西能够返回。他记起那天他突然看见萨莱在折叠瑞秋刚学会走路时的衣服，把它们放在阁楼的箱子里，他回想起她的泪水和他自己对女儿的失落感觉。');
INSERT INTO quotes (id, book_id) VALUES (535, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (535, 'zh', '这个女人缓缓踱步，在极小重力下优雅地迈步，唯有生在太空的人才有这种本事。');
INSERT INTO quotes (id, book_id) VALUES (536, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (536, 'zh', '我们不是化身，不是什么神之子或是圣子。我们只是我们，独自涂鸦我们自己的狂妄自大，独自阅读，独自死亡。');
INSERT INTO quotes (id, book_id) VALUES (537, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (537, 'zh', '芬妮啊，在上帝广袤的领土内，还有什么其他生物会携有你的记忆？拂去九百年的蒙尘？让它将他吃得一干二净？');
INSERT INTO quotes (id, book_id) VALUES (538, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (538, 'zh', '我们注定生来就要忍受自己的痛苦，把它紧紧地拥在肚子上，就像年轻的斯巴达窃贼将小狼崽藏在身上￼，让它吞噬了自己的内脏。');
INSERT INTO quotes (id, book_id) VALUES (539, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (539, 'zh', '在临死时总是保持不了自己的好脾气，我这一生都过得慷慨大方……为什么，在我遭受痛苦时，在我将两肺的粗糙残余都咳进污迹斑斑的手帕时，我还要继续这一慷慨角色的命运呢？');
INSERT INTO quotes (id, book_id) VALUES (540, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (540, 'zh', '杜雷盯着这男人那硕长、瘦削、微微有点亚洲人风格的面貌，他意识到，眼前的这张脸上蚀刻着震惊。震惊，难以置信。');
INSERT INTO quotes (id, book_id) VALUES (541, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (541, 'zh', '这次不会有。永远也不会有。 “答应他，爸爸。” 一只手触到了索尔的手，他惊得跳了起来。他的女儿瑞秋，正站在他的身旁');
INSERT INTO quotes (id, book_id) VALUES (542, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (542, 'zh', '亨特被这一切弄得六神无主；被这，被这可怕的脱瘾症状（他正遭受着脱离数据网的痛苦）。我能想象他的痛苦。一个人生长在信息唾手可得的世界上，随时随地能与人交流，想去什么地方只要迈进远距传输器就行，但忽然间，生活退化了，退回到我们的祖先的世界，就像突然醒来，发现自己变得又瞎又跛了一样。');
INSERT INTO quotes (id, book_id) VALUES (543, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (543, 'zh', '每得到一秒钟的残喘时间，他都由衷地心怀感激。为什么？他内心有一部分问道。你已经厌倦了活在世上。乐于一死。');
INSERT INTO quotes (id, book_id) VALUES (544, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (544, 'zh', '而是对所有这些受难者，他们孤独，甚至没有被赋予最薄弱的信仰，他们不得不面对这黑夜中的恐怖，而这一切是那怪物具体的体现。');
INSERT INTO quotes (id, book_id) VALUES (545, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (545, 'zh', '三位一体中的基督实体穿越时间，走过某个四维的客西马尼花园，争取几小时……或者几年的……时间，以便进行思考。');
INSERT INTO quotes (id, book_id) VALUES (546, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (546, 'zh', '低矮的小床，粗糙的毯子，木制的跪凳，一个极其朴素的梳洗台，里面有只灌满水的罐壶，还有一只普通的水盆；没有窗，没有媒体墙，没有全息显像井，没有数据接入平台。我怀疑这间房间甚至不是人机互动的。');
INSERT INTO quotes (id, book_id) VALUES (547, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (547, 'zh', '他们脚底下的“手掌”颤动着，朝下坠落五米，几乎将他们颠进空中，然后再次颤动起来。耳畔传来一阵隆隆声，好似巨型建筑倒塌，又好似山坡发生了雪崩。 布劳恩很明显地感觉到，云门是在笑。');
INSERT INTO quotes (id, book_id) VALUES (548, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (548, 'zh', '这种复杂性，让她感觉自己先前对万方网的匆匆一瞥就像是乡巴佬将剧场衣帽间当成了大教堂，在那儿满口胡言。');
INSERT INTO quotes (id, book_id) VALUES (549, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (549, 'zh', '他仅仅是想要完成它，亲自得知结局，将每一节、每一行、每一个字尽可能写成最完美、最透彻、最美丽的形式。');
INSERT INTO quotes (id, book_id) VALUES (550, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (550, 'zh', '她以前从未来过这里，刻意地不来这里，而现在她来了，她绝望地想要得到什么感触，想听到什么，譬如警告，或是神秘直觉，或者仅仅是哀悼的情感，但这些东西都躲得离她远远的。');
INSERT INTO quotes (id, book_id) VALUES (551, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (551, 'zh', '落日引燃了星球真正的屋顶，犹如一片树冠之海沐浴在阳光之下，每一张叶片都迎着微风闪耀，将雨水与湿木的气味向悦石送来，朝露和晨雨的水滴闪烁着，她所在的高台下半公里的世界安然沉睡在黑暗中。');
INSERT INTO quotes (id, book_id) VALUES (552, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (552, 'zh', '希莉的声音随着年龄增长越发地富有魅力，它拥有充实和平静的质地，只有从那些自知将不久于人世的人口中，才能听到这种声音。');
INSERT INTO quotes (id, book_id) VALUES (553, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (553, 'zh', '我凝视着她骨瘦如柴的肋骨和胸骨轮廓，想起了十六岁的她，那时她还带着点婴儿肥，拥有着温暖的丝绒一般的皮肤。在摇曳的冷光下，我看着希莉松弛的肌肤，想起了月光下蓓蕾般的乳房。不知怎么的，很奇怪，难以名状，我面前站着的变成记忆中那个希莉了。');
INSERT INTO quotes (id, book_id) VALUES (554, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (554, 'zh', '她对我生活中那些远离她的部分一无所知。她会问起这些，但有时候，我觉得她也许根本不在意答案是什么。我花上好几个小时向她解释我们神行舰背后蕴含的美丽物理法则，但她似乎从来都没有听懂过。');
INSERT INTO quotes (id, book_id) VALUES (555, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (555, 'zh', '这里地处这颗酷热星球的赤道附近，但是在这个八面迎风的绝壁，风声呼号，我的牙齿不住打战。西天浓暗的卷云中间，落日只是一个红色迹点');
INSERT INTO quotes (id, book_id) VALUES (556, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (556, 'zh', '火炬的焰光在她的发丝上映出深赤褐色的光泽。她双颊绯红，面若桃花，尽管隔着人头攒动的广场，我还是见到了她碧绿眼珠的惊鸿一瞥，与她面容和秀发上夏日的热情交相辉映。');
INSERT INTO quotes (id, book_id) VALUES (557, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (557, 'zh', '现在，黑暗真的沉淀下来了。屋内有灯，但是乔尼没有把它们点上，而我，也挺喜欢这种朦胧的意境。');
INSERT INTO quotes (id, book_id) VALUES (558, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (558, 'zh', '“我喜欢待在这个地方，爸爸，但是我们明天回家好吗？”');
INSERT INTO quotes (id, book_id) VALUES (559, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (559, 'zh', '每天早晨，索尔都会坐在女儿的床前等着她醒来。头几分钟里，爱女的困惑总是让他非常痛苦，但是他坚持要确保每天早上瑞秋醒来第一眼见到的是自己。他抱着她，回答她问的每一个问题。');
INSERT INTO quotes (id, book_id) VALUES (560, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (560, 'zh', '她总是觉得人类经历的精髓不只是在于那些巅峰时刻，譬如婚礼的日子或者成功的到来，它们在记忆中耀眼突出，像是老日历中用红笔圈出的日子；相反，那精髓更在于不经意间走过的平凡琐事——周末下午，家中的每个成员都专注于自己追求的东西，他们在各自的工作中偶然相遇、联络，简短的对话也不会在记忆中长时间存留，但是这样的时间累加起来的增效作用却是极为重要和永恒的。');
INSERT INTO quotes (id, book_id) VALUES (561, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (561, 'zh', '尽管他们心里都很喜欢旅行，但在实际经历中总会遇到奇怪的食物、不同的重力。陌生太阳发出的光芒很快就暗淡');
INSERT INTO quotes (id, book_id) VALUES (562, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (562, 'zh', '长长的金发，柔软得仿佛不是真物，肤色如同刚摘下的桃子，纯洁得让人不敢有触摸的奢想，美得让人不敢相信：正是那种连最胆小的男子也梦想玷污的尤物。');
INSERT INTO quotes (id, book_id) VALUES (563, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (563, 'zh', '但是我发现，只要这任务是既繁重又反复的，我的头脑就会无拘无束地漫步在更富想象力的区域里，不仅如此，它还会飞也似的逃向更高的层面。 因此，在天国之门，我在织女主星的红色凝视下，在污水四溅的运河里疏浚河底的浮渣；或者，在迷宫般的肺道中，手脚并用，缓缓地爬行在重吸菌组成的钟乳石和石笋中，就在此时，我变成了诗人。 我所缺乏的，仅仅是词语。');
INSERT INTO quotes (id, book_id) VALUES (564, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (564, 'zh', '我记得，她坐在温室里，倒上一杯咖啡，光线投下，投影出缎带装饰，夹杂着灰尘，她那纤纤细手的手背上，露出无数脆弱的蓝色静脉；她的头发卷成贵妇人风格的一个圆髻，烛光牵绊在她头发的蛛丝光辉中，就像一只金色的苍蝇羁绊在那儿。有时，我会梦到自己记起了她的声音，那轻快的音调，带着在子宫里打转的意味，但是当我旋即醒来，发觉那仅仅是风儿吹过蕾丝窗帘的声音，或是什么不知名的海洋在拍打礁石。');
INSERT INTO quotes (id, book_id) VALUES (565, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (565, 'zh', '巨大的榆树。棉白杨、柏树、红杉，还有盆景。榕树垂下新生的树干，就像是以天作顶的神庙中光滑的支柱。柳树整齐地列于运河两侧，列于偶然冒出的溪涧之畔，垂下的枝条迎着风儿，吟起远古的挽歌。');
INSERT INTO quotes (id, book_id) VALUES (566, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (566, 'zh', '太阳落下，给河流上带来了一种感官上的宁静，不久之后，虫儿聒噪，夜鸟啼啭，组成了一首大合唱，打破了宁静。');
INSERT INTO quotes (id, book_id) VALUES (567, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (567, 'zh', '树枝变幻，模糊，然后重新现形，仿佛是拙劣的全息录像。');
INSERT INTO quotes (id, book_id) VALUES (568, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (568, 'zh', '他转念一想，这种虎头蛇尾的事情真是宇宙对他的自命不凡和好勇斗狠的最好裁决：');
INSERT INTO quotes (id, book_id) VALUES (569, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (569, 'zh', '的温唇述说着话语，声音就在卡萨德耳朵的门槛边徘徊。');
INSERT INTO quotes (id, book_id) VALUES (570, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (570, 'zh', '这名二十三岁的身经百战者觉得他从没有体会到什么叫作无法形容，什么叫作难以言喻。然而他错了，接下去几分钟的感受是永远无法准确地向别人表达出来的，他都用不着尝试。');
INSERT INTO quotes (id, book_id) VALUES (571, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (571, 'zh', '卡萨德觉得她也许是自己见过的最美的女人：骨架看起来是那么完美，使她的脸型让人觉得增一分则长，减一分则短，大眼睛里闪烁着智慧的光芒和生命的活力，文雅的小嘴拥有一片温润的下唇。');
INSERT INTO quotes (id, book_id) VALUES (572, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (572, 'zh', '这群人默默吃着，显然，与平常的神游后饥饿、疲劳和抑郁相比，他们正承受着更多的痛苦。');
INSERT INTO quotes (id, book_id) VALUES (573, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (573, 'zh', '别人可能会把毕库拉的圆脸描绘成天真无邪的天使脸庞，然而在近距离观察之后，可爱的印象会渐渐消失，被另外一种诠释所替代——平和的白痴。');
INSERT INTO quotes (id, book_id) VALUES (574, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (574, 'zh', '早上，烟尘和薄雾变换所组成的幕帘争先恐后地遮蔽了天空。唯有固若金汤的比斯托，高原巅峰的岩石土壤，以及东北方连绵的陡峭山脊，它们就像穿着装甲的椎骨，挡住了特斯拉树的去路。');
INSERT INTO quotes (id, book_id) VALUES (575, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (575, 'zh', '在阿马加斯特，你和我完全知晓这种死亡，那儿血红的太阳照射到的只有尘埃和死神。');
INSERT INTO quotes (id, book_id) VALUES (576, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (576, 'zh', '我在圣器收藏室的黑暗中闲荡。尘埃和石膏粉屑像熏香一般飘荡在空中，两束阳光被勾勒出来，从高处狭窄的窗口泻下。');
INSERT INTO quotes (id, book_id) VALUES (577, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (577, 'zh', '我游过一格一格的影子，荡过倒塌的大楼，最后进入教堂正殿。');
INSERT INTO quotes (id, book_id) VALUES (578, 9);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (578, 'zh', '巨树之舰“伊戈德拉希尔”转了个方向，树干遮蔽了阳光，其下的就餐台和弯曲树叶形成的天篷陷入了一片漆黑，取而代之的是点缀在苍穹中的数千星辰，就仿佛是在星球表面上看星空一般。慢慢地，头顶、身旁、桌子底下万光闪耀。海伯利安变成了一个清晰的球体，它就像一颗致命的导弹，向他们急速飞来。');

-- 新建作者 pick #8 · 亨利·戴维·梭罗
INSERT INTO authors (id, emoji) VALUES (10, '🇺🇸');
INSERT INTO author_translations (author_id, language_code, name) VALUES (10, 'zh', '亨利·戴维·梭罗'), (10, 'en', 'Henry David Thoreau');
-- pick #8 · weread bookId=3300044710 · 瓦尔登湖 · 70 条划线
INSERT INTO books (id, author_id, emoji) VALUES (10, 10, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (10, 'zh', '瓦尔登湖'), (10, 'en', 'Walden');

INSERT INTO quotes (id, book_id) VALUES (579, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (579, 'zh', '每天早晨，这个画廊的经理都会拿出几幅新的画作，色彩更加明艳或者更加和谐，用以代替墙上的旧作。');
INSERT INTO quotes (id, book_id) VALUES (580, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (580, 'zh', '同样地，屠夫从草原上割走了野牛的舌头￼，对那受伤垂危的生灵完全无动于衷。');
INSERT INTO quotes (id, book_id) VALUES (581, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (581, 'zh', '他们只会满不在乎地用蒲式耳和美元来衡量蔓越莓的价值，把这些从草原劫掠而来的贼赃卖到波士顿和纽约；');
INSERT INTO quotes (id, book_id) VALUES (582, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (582, 'zh', '但我认为我们在喂饱身体的同时，也应该喂饱精神');
INSERT INTO quotes (id, book_id) VALUES (583, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (583, 'zh', '大自然并不惮于将其自身呈现给他们。');
INSERT INTO quotes (id, book_id) VALUES (584, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (584, 'zh', '立法机构也很少关心瓦尔登湖，主要是规定湖里顶多能放进多少个鱼钩[插图]');
INSERT INTO quotes (id, book_id) VALUES (585, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (585, 'zh', '但如今情况正在发生变化，倒不是由于人口有所增加，而是由于猎物迅速减少，因为现在喜欢打猎的人也许反倒成为被猎取的禽兽最好的朋友，');
INSERT INTO quotes (id, book_id) VALUES (586, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (586, 'zh', '那道彩虹填充了大气的最底层，给周围的青草和树叶染上了颜色，又照得我心驰目眩，仿佛我正在看着的是五彩的水晶。');
INSERT INTO quotes (id, book_id) VALUES (587, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (587, 'zh', '让我们的湖泊拥有真正的名字吧，至少像伊卡洛斯海￼那样，“那里的沙滩依旧回荡着一次勇敢的尝试”￼。');
INSERT INTO quotes (id, book_id) VALUES (588, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (588, 'zh', '湖水仍是我年轻时看到的模样；反倒是我改变了很多。它有那么多的涟漪，却没有长出永久的皱纹。');
INSERT INTO quotes (id, book_id) VALUES (589, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (589, 'zh', '因为我当时很富裕，虽然没有金钱，但拥有许多阳光灿烂的时辰和盛夏的日子，');
INSERT INTO quotes (id, book_id) VALUES (590, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (590, 'zh', '那些日子里，无所事事是最具吸引力和最有收获的事业。');
INSERT INTO quotes (id, book_id) VALUES (591, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (591, 'zh', '它是石头不能将其击破的镜子，它的水银永远不会消褪，它的花纹会得到大自然不断的修补；它的表面永远是光亮的，风暴和灰尘不能使其变得黯淡；任何不洁之物落到这面镜子上都会沉没，或者被太阳的刷子——这是光的擦拭布——掸走；');
INSERT INTO quotes (id, book_id) VALUES (592, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (592, 'zh', '瓦尔登湖的风景并非顶级，虽然非常漂亮，但谈不上惊艳，也不足以让那些很少来或者不住在湖边的人着迷；然而其湖水既深邃又纯净，值得大书特书。');
INSERT INTO quotes (id, book_id) VALUES (593, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (593, 'zh', '感觉非常怪异，尤其是在漆黑的夜里，你本来神游天外，却突然感觉到这微弱的扯动，它打断了你的梦境，让你再次和大自然紧密相连。');
INSERT INTO quotes (id, book_id) VALUES (594, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (594, 'zh', '高尚者的品行像风，普通人的品行像草；风吹过时，草自然会伏低。');
INSERT INTO quotes (id, book_id) VALUES (595, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (595, 'zh', 'Nec bella fuerunt,Faginus astabat dum scyphus ante dapes.[插图]如果人们的榉木碗都有饭吃，大家又何必费事去打仗。');
INSERT INTO quotes (id, book_id) VALUES (596, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (596, 'zh', '换句话说，只有到了失去这个世界之后，我们才能开始找到我们自己[插图]，才能发现我们所处的位置，以及我们与万事万物的联系是多么紧密。');
INSERT INTO quotes (id, book_id) VALUES (597, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (597, 'zh', '直到必须抬手开门才回过神来，完全不知道自己是怎么走回家的；我想即使被其主人抛弃，我的肉体也是能走回家的，就像手无需任何帮助便能找到嘴那样。');
INSERT INTO quotes (id, book_id) VALUES (598, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (598, 'zh', '这些人通常到户外打听风里的消息。他们是最粗糙的磨坊，先把各种八卦新闻粗略地消化或者碾碎，再将其倾倒进屋内更为精细的料斗。');
INSERT INTO quotes (id, book_id) VALUES (599, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (599, 'zh', '而非苦艾￼、披碱草￼、粟草￼来表达它的夏日感想');
INSERT INTO quotes (id, book_id) VALUES (600, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (600, 'zh', '他有时候会大声说：“我好喜欢聊天啊！天啊，我可以聊一整天！”');
INSERT INTO quotes (id, book_id) VALUES (601, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (601, 'zh', '有时候，在休息的日子里，他会整天带着手枪在森林里晃荡，每走一段路就朝天开枪向自己致敬。');
INSERT INTO quotes (id, book_id) VALUES (602, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (602, 'zh', '我离镇区的距离倒是能够帮我筛选朋友呢。我在孤寂的大海中已经航行了很远，应酬的江河虽然汇入这片汪洋，但能够在我身边积聚的，基本上都是最优秀的沉淀物，这是很符合我个人的需要的。');
INSERT INTO quotes (id, book_id) VALUES (603, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (603, 'zh', '衡量孤寂的标准，并不是一个人和其同类之间隔了多少英里。真正勤奋的学生，哪怕身处剑桥学院人满为患的教室中，也必定如沙漠里的托钵僧般孤寂。');
INSERT INTO quotes (id, book_id) VALUES (604, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (604, 'zh', '我只知道我自己是一个单独的人，或者说是各种思维和情感登场的舞台，并且察觉到我多少具有双重人格，因为我能够站在远处观察我自己，就像观察别人那样。');
INSERT INTO quotes (id, book_id) VALUES (605, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (605, 'zh', '我已经发现，两个人的腿再怎么走，也无法让两颗心靠得更近。');
INSERT INTO quotes (id, book_id) VALUES (606, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (606, 'zh', '我们寄居的这个地球无非是太空中的一点。和浩茫无际、连我们的仪器都测量不出其直径有多大的宇宙相比，在这个星球上居住的两个人，哪怕隔得再远，又能有多远呢？');
INSERT INTO quotes (id, book_id) VALUES (607, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (607, 'zh', '尽管天已全黑，风依然在森林间吹拂和呼啸着，水波依然拍打着湖岸，而有些动物则开始用它们的歌曲哄其他动物入睡。');
INSERT INTO quotes (id, book_id) VALUES (608, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (608, 'zh', '酩酊的醉意非但淹没不了往日的记忆，反倒让它们感到肚子里装满了苦水。');
INSERT INTO quotes (id, book_id) VALUES (609, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (609, 'zh', '我发现写到“咯咯”时，我自己居然情不自禁地模仿起雕鸮的叫声。能够发出这样的声音，说明它们的精神陷入了一种黏稠发霉的状态，所有健康和勇敢的想法都已被消灭干净。');
INSERT INTO quotes (id, book_id) VALUES (610, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (610, 'zh', '最沉重的墓园之歌，是自杀的恋人在冥界森林回忆起生前相爱的种种苦痛与欢愉时的相互安慰');
INSERT INTO quotes (id, book_id) VALUES (611, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (611, 'zh', '这种回声其实多少也算是原声，并且自有其神奇与迷人之处。它重复的不仅仅是那值得重复的钟声，还包括了部分森林的声响；森林女神所吟唱的，也无非就是这种依稀可闻的歌词和曲调。');
INSERT INTO quotes (id, book_id) VALUES (612, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (612, 'zh', '若是传到距离足够远的森林上空，这声音就转换成某种颤动的低鸣，仿佛触目所及的松针都变成被它轻拂而过的琴弦。');
INSERT INTO quotes (id, book_id) VALUES (613, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (613, 'zh', '再过不久就要将漫天的晚霞当作列车的披风；');
INSERT INTO quotes (id, book_id) VALUES (614, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (614, 'zh', '于是棉花越来越多，粗布越来越少；丝绸越来越多，羊毛越来越少；书籍越来越多，写书的聪明人越来越少。');
INSERT INTO quotes (id, book_id) VALUES (615, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (615, 'zh', '实际上，我们的村庄已经变成标靶 飞快的铁路如长矛般疾刺而来，在 我们这个和谐￼的地方奏响了不和谐 的音调。');
INSERT INTO quotes (id, book_id) VALUES (616, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (616, 'zh', '由于它们长得太过恣肆，脆弱的关节承受不住，我听到一根翠绿的柔枝“啪”地突然断了，宛如扇子般掉到地上，而当时并没有风，它纯粹是被自身的重量压垮的。');
INSERT INTO quotes (id, book_id) VALUES (617, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (617, 'zh', '我的房屋在山坡上，紧挨着大片的森林，周围全是青翠的松树和山核桃，离瓦尔登湖只有六七杆地￼的距离，有条小径通往山下。屋前的花园生长着草莓、黑莓、长生花、金丝桃￼、秋麒麟草￼、矮栎、沙樱桃、蓝莓￼和地豆￼。');
INSERT INTO quotes (id, book_id) VALUES (618, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (618, 'zh', '和这些人相比，我的生活方式有个很大的优点，那就是我的生活本身就是一种娱乐活动，永远充满了新奇。');
INSERT INTO quotes (id, book_id) VALUES (619, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (619, 'zh', '当前难以言说的道理，我们或许会发现其他地方已经有人说过了。这些让我们感到困扰、惶惑和迷惘的问题，所有的智者也都曾遇到；他们一个不漏地遇到了，而且已经根据各自的能力，用他们的文字与人生对每个问题做出了解答。');
INSERT INTO quotes (id, book_id) VALUES (620, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (620, 'zh', '这种外形漂亮然而索然无味的姜饼每天都从许许多多的炉子上被烘烤出来，和营养丰富的全麦面包或者燕麦面包相比，它显得更加可口诱人，在市场上的销量也更大。');
INSERT INTO quotes (id, book_id) VALUES (621, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (621, 'zh', '到时他将会发现自己在文化上有所欠缺，所有的财富不过是过眼云烟，并不能让他感到满足；假设他是个聪明人，他将会费尽心机让他的孩子获取他梦寐以求的知识文化；如此一来，他将会变成某个名门望族的奠基人。');
INSERT INTO quotes (id, book_id) VALUES (622, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (622, 'zh', '如果说那些作品因为年代久远而不值得阅读，那我们连大自然都不用研究了，因为大自然存在的时间也很久。好的阅读就是以真正的精神去读真正的书，这是一种高贵的活动，和如今备受世俗推崇的各种活动相比，它需要读者耗费更多的心血。');
INSERT INTO quotes (id, book_id) VALUES (623, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (623, 'zh', '大人没能过上有价值的生活，却自认为更加聪明，因为他们有经验，可惜他们的经验其实就是失败。');
INSERT INTO quotes (id, book_id) VALUES (624, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (624, 'zh', '我们必须学会再次苏醒，并保持清醒的状态，但要借助的不是某些生硬的措施，而是对黎明的无限期待，');
INSERT INTO quotes (id, book_id) VALUES (625, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (625, 'zh', '早晨无关乎时间，无关乎人们的态度和劳动。只要我清醒着，心中有光明，那就是早晨。');
INSERT INTO quotes (id, book_id) VALUES (626, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (626, 'zh', '要是能够把它买下来，然后别去管它，它将会生长出如画般的优美景色，而那才是我想要的收获。');
INSERT INTO quotes (id, book_id) VALUES (627, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (627, 'zh', '因为一个人能抛下的东西越多，他就越是富裕。');
INSERT INTO quotes (id, book_id) VALUES (628, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (628, 'zh', '如果你要给钱，最好是亲自用掉，而不是单纯地把钱给他们。');
INSERT INTO quotes (id, book_id) VALUES (629, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (629, 'zh', '说到做好事，从事这门职业的人已经足够多。再说我也曾努力地尝试去做，说起来倒是奇怪，我发现做好事不投合我的性情，反而感到很高兴。');
INSERT INTO quotes (id, book_id) VALUES (630, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (630, 'zh', '有些人假使得到比现在更多的闲暇时间，将会不知道该做些什么，我建议他们加倍努力地工作——直到他们为自己赎了身，拿到自由的文件￼。');
INSERT INTO quotes (id, book_id) VALUES (631, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (631, 'zh', '独行的人今天就可以上路，而有同伴的旅客则必须等别人做好准备，可能需要很长时间才能出发。');
INSERT INTO quotes (id, book_id) VALUES (632, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (632, 'zh', '我倒也愿意给自己盖一座比康科德镇大街上任何建筑都要豪华气派的房子，不过前提是它能让我住得同样高兴，而且造价也不比目前这座木屋高。');
INSERT INTO quotes (id, book_id) VALUES (633, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (633, 'zh', '你会发现他背负着所有这些东西，竭尽全力地前进。我想这个人就是陷入了死局，');
INSERT INTO quotes (id, book_id) VALUES (634, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (634, 'zh', '但是没有带走那只猫。她跑进树林里，变成野猫了，后来我听说她落进捕捉土拨鼠的陷阱，终于就这样变成了死猫');
INSERT INTO quotes (id, book_id) VALUES (635, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (635, 'zh', '但大部分时间是晴天，当我沿着铁路￼走回家￼，');
INSERT INTO quotes (id, book_id) VALUES (636, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (636, 'zh', '大家要是都不穿衣服了，能在多大程度上保留相对的等级地位呢？这是个很有意思的问题。假如在这种情况下，就算身边都是文明人，你能有把握地分辨出哪些人属于更受尊敬的阶级吗？');
INSERT INTO quotes (id, book_id) VALUES (637, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (637, 'zh', '即使衣服破了没有修补，所显露出来的缺点也无非是这人不修边幅而已。');
INSERT INTO quotes (id, book_id) VALUES (638, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (638, 'zh', '我们的衣服每天都变得更加贴合我们的身体，渐渐烙上了穿衣者的性格，乃至经过缝缝补补、穿了又穿，最终到了要将其抛弃的时候，我们会感到恋恋不舍，有些人甚至还会觉得很难过，就好像要丢弃的是我们的身体。');
INSERT INTO quotes (id, book_id) VALUES (639, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (639, 'zh', '到衣服，我们在购买它时，考虑得更多的往往是款式是否新潮，别人会怎么看，而不是其真正的用途');
INSERT INTO quotes (id, book_id) VALUES (640, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (640, 'zh', '他们积聚了钱财，却不知道如何使用它，或者说如何摆脱它，因而给自己打造了黄金或者白银的镣铐。');
INSERT INTO quotes (id, book_id) VALUES (641, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (641, 'zh', '我想要开列的生活指南，并不是给坚强勇敢者看的，那些人不管在天堂还是地狱，都能把自己照顾得很好；和最富裕的人比起来，他们盖的楼房可能更华丽，花起钱来可能更豪爽，又不会把自己弄得很穷，而且还不知道他们——假如真有这种人的话——过着的是人们向来梦寐以求的生活；也不是给那些在当前的境况中找到他们的勇气和灵感的人看的，他们怀着恋人般的怜爱和热情，珍惜着此时此刻的生活——从某种程度上来讲，我觉得我也属于这类人；我想说的话，并不是说给那些无论处境如何都能过得很好的人听的，他们知道自己是否过得好；我的话是说给一类为数众多的人听的，那些人满腹牢骚，总是徒劳地抱怨他们的命运或者时代很艰难，其实他们原本是可以去予以改善的。');
INSERT INTO quotes (id, book_id) VALUES (642, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (642, 'zh', '无论在中国、印度、波斯还是希腊，古代的哲学家都是身外财物比谁都少、内心财富比谁都多的人。');
INSERT INTO quotes (id, book_id) VALUES (643, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (643, 'zh', '总是抱怨这是个寒冷的世界；我们把大部分疾病，无论是身体的还是社会的，都归咎于寒冷。在某些地区，夏天让人能够过上快乐的生活。');
INSERT INTO quotes (id, book_id) VALUES (644, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (644, 'zh', '白天时提心吊胆，到了晚上不情不愿地祷告，丝毫没有坚定的信念。');
INSERT INTO quotes (id, book_id) VALUES (645, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (645, 'zh', '别伤心，我的孩子，因为有些事情如果你自己不去做，谁又会来替你完成呢？”');
INSERT INTO quotes (id, book_id) VALUES (646, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (646, 'zh', '今天每个人宣称或默认为万世不移的真理，到明天也许就会被证明是谬误，只是黑色的烟雾，而非有些人曾经以为的雨云，将会普降甘霖滋润他们的田地。');
INSERT INTO quotes (id, book_id) VALUES (647, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (647, 'zh', '人只有想起自己的无知才能有长进，但他如此忙于使用已有的知识，又如何能想得起来呢？');
INSERT INTO quotes (id, book_id) VALUES (648, 10);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (648, 'zh', '赫拉克勒斯￼的十二大苦役和我的邻居所从事的苦役比起来简直微不足道；因为它们只有十二件，毕竟有结束的时候；但我从不曾看见这些人杀死或捕获任何怪兽，或者完成过任何劳役。他们没有伊奥劳斯￼这样的朋友来用火红的铁块去烙海德拉￼的脖子，每当砍掉一个头，会有两个新的头生出来。');

-- 复用已有作者 id=1 · 石黑一雄
-- pick #12 · weread bookId=32219280 · 长日将尽（译文经典） · 137 条划线
INSERT INTO books (id, author_id, emoji) VALUES (11, 1, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (11, 'zh', '长日将尽（译文经典）'), (11, 'en', 'The Remains of the Day');

INSERT INTO quotes (id, book_id) VALUES (649, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (649, 'zh', '‘尊严’云云，其至关紧要的一点即在于一位管家无论何时何地都能坚守其职业生命的能力”​；​“伟大的管家之所以伟大，是由于他们能够化入他们的职业角色，并且是全身心地化入”​。身');
INSERT INTO quotes (id, book_id) VALUES (650, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (650, 'zh', '日裔英国作家石黑一雄（Kazuo Ishiguro，1954年12月8日— ）因“以其巨大的情感力量，发掘了隐藏在我们与世界的虚幻联系之下的深渊”而荣获二〇一七年度诺贝尔文学奖，瑞典文学院并进而明确指出石黑一雄的文学创作的三个关键词是“时间、记忆与自我欺骗”​。想');
INSERT INTO quotes (id, book_id) VALUES (651, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (651, 'zh', '你得学会享受你的人生。傍晚是一天当中最美好的时光。你已经做完了一天的工作。该是你搁起脚来好好享受一下的时候了。我就是这么看的。随便找个人问问，他们也都会这么说的。傍晚是一天当中最美好的时光。​”');
INSERT INTO quotes (id, book_id) VALUES (652, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (652, 'zh', '哎呀，朋友。我说，要不要块手绢儿？我应该揣着一条来着。找到了。还挺干净的。今天早上只拿它来擤了一次鼻子，仅此而已。你拿去用吧，朋友。​”');
INSERT INTO quotes (id, book_id) VALUES (653, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (653, 'zh', '主要的我是想告诉他，在筹备和监管我们过去经常举办的那些盛大活动时，需要掌握哪些—用他的话来说—“窍门儿”​。的');
INSERT INTO quotes (id, book_id) VALUES (654, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (654, 'zh', '还有不少天光尚存—海面上的天空已经变为浅红色—不过看来过去半个钟头之内聚集在码头上的人群都希望夜色快点降临。');
INSERT INTO quotes (id, book_id) VALUES (655, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (655, 'zh', '我走出候车亭招手示意停车，肯顿小姐站起身来到候车亭边。直到汽车停了下来，我才又偷觑了肯顿小姐一眼，结果发现她眼里盈满了泪水。');
INSERT INTO quotes (id, book_id) VALUES (656, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (656, 'zh', '“不过，当然了，这也并不意味着偶尔就不会有这种的时候—在极其孤独的时刻—你会想要对自己说：‘我的人生中犯了个多么可怕的错误。’而且你会开始想象一种不同的生活，一种你原本可能拥有的更好的生活。');
INSERT INTO quotes (id, book_id) VALUES (657, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (657, 'zh', '可是一年一年地就这么过去了，爆发了战争，凯瑟琳也渐渐长大了，有一天我猛然惊觉我是爱我丈夫的。你跟某个人一起生活了这么长时间，你发现你已经习惯跟他在一起了。');
INSERT INTO quotes (id, book_id) VALUES (658, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (658, 'zh', '多年前我在离开达林顿府的时候，我其实并没有真切地意识到我的的确确是离开了它。我想我只不过是把它当作了又一种激怒你的伎俩，史蒂文斯先生。');
INSERT INTO quotes (id, book_id) VALUES (659, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (659, 'zh', '肯顿小姐在候车的长椅上坐下，我则一直在看得见公共汽车驶来的地方站着。公路的对面，目光所及也只有更多的农田；一排电线杆将我的视线一直引向遥远的天边。');
INSERT INTO quotes (id, book_id) VALUES (660, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (660, 'zh', '当然了，我也知道，这种事情我本是无缘置喙的，而且我也应该澄清一下，若不是出于非常重要的工作方面的考虑，您也许还记得，我是做梦也不会想去打探这方面的私事的');
INSERT INTO quotes (id, book_id) VALUES (661, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (661, 'zh', '不过，与其说是我们交谈的内容，倒不如说是她讲完一段话后的浅浅一笑，她不时流露出来的淡淡的反讽口吻，她肩膀和双手的习惯性姿态，开始明白无误地让我们渐渐重拾起多年前我们交谈时的节奏和习惯。');
INSERT INTO quotes (id, book_id) VALUES (662, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (662, 'zh', '当然，她是有些显老了，不过起码在我看来，她老得还是非常优雅的。她的身材仍旧很苗条，她的身姿也一如既往地挺拔。她仍旧保持着跟过去一样的姿态，把头高高地仰起，几乎带一点挑衅的神气。当然了，由于惨淡的日光正落在她的脸上，我也不由得注意到那到处出现的皱纹。');
INSERT INTO quotes (id, book_id) VALUES (663, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (663, 'zh', '在灰蒙蒙的天光中肯顿小姐和我就这样谈了两个小时左右的时间，在此期间雨仍旧毫不停歇地落在外面的广场上。');
INSERT INTO quotes (id, book_id) VALUES (664, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (664, 'zh', '这座海边小镇是多年来我一直都很想来看看的地方。我已经听很多人谈起曾在这里度过了多么愉快的假期，而西蒙斯太太也在《英格兰奇景》中称其为“连续多日都能让游客游兴不减的小镇”​。事');
INSERT INTO quotes (id, book_id) VALUES (665, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (665, 'zh', '毕竟，我刚刚经历了一个极端煎熬的夜晚，而在此期间我竭尽所能，始终都保持了一种“与我的职位相称的高尚尊严”—不仅如此，我还是以一种就连家父也会引以为傲的方式做到这一点的。');
INSERT INTO quotes (id, book_id) VALUES (666, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (666, 'zh', '当今的世界太过险恶，是容不得你那些善良高贵的本能的。');
INSERT INTO quotes (id, book_id) VALUES (667, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (667, 'zh', '“我真心希望你能坐下来，史蒂文斯。希望咱们能像朋友那样说说话，你站在那里端着那个该死的托盘就像是随时都打算走开似的。” “对不起，先生。”');
INSERT INTO quotes (id, book_id) VALUES (668, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (668, 'zh', '她仍旧原地未动，因此在跟我讲话时不得不稍稍提高了一下嗓门，结果在黑暗而又空寂如洞窟的厨房内造成了一种相当诡异的回声。');
INSERT INTO quotes (id, book_id) VALUES (669, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (669, 'zh', '事实是，具有全球性重要意义的事件此时就正在府内进行当中呢。”');
INSERT INTO quotes (id, book_id) VALUES (670, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (670, 'zh', '史蒂文斯先生，据我的理解，您是不是希望今天晚上我留下来当班？”');
INSERT INTO quotes (id, book_id) VALUES (671, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (671, 'zh', '“对此我非常感激，肯顿小姐。衷心祝您度过一个愉快的夜晚。我这就先告退了。”');
INSERT INTO quotes (id, book_id) VALUES (672, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (672, 'zh', '有一个回忆尤其已经在我的脑海中翻腾了整整一上午—或者应该说只是个记忆的片段，记忆中的那一刻出于某种原因在这些年间一直异常鲜明地印刻在我的脑海中。');
INSERT INTO quotes (id, book_id) VALUES (673, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (673, 'zh', '当然了，晨光赋予了村庄一种非常不同的面貌，但除此之外，那景色就跟昨天我在傍晚熹微的暮色中第一次看到它时相差无几，从这一点上我也可以猜想得出，我们距离我丢下福特车的地方已经非常近了。');
INSERT INTO quotes (id, book_id) VALUES (674, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (674, 'zh', '他们感觉他们应该对这对那拥有明确的态度，正如哈里敦促他们去做的那样。可是其实，他们跟任何地方的老百姓没什么两样。他们只想平平静静地过他们的日子。');
INSERT INTO quotes (id, book_id) VALUES (675, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (675, 'zh', '我很明白那是怎么回事。我的意思是说，你是那种一见之下就会给人深刻印象的样本。');
INSERT INTO quotes (id, book_id) VALUES (676, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (676, 'zh', '现在的莫斯科姆村沐浴在朝阳当中，其中心地带是一座由几家小店铺簇拥环绕的教堂，昨天傍晚的时候我曾经在山上看到过它的尖塔。');
INSERT INTO quotes (id, book_id) VALUES (677, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (677, 'zh', '在这之后，暴雨很快就倾盆而至，其势头之猛使得所有的客人一时间全都停止了用餐，惊讶地望着窗外的雨势。');
INSERT INTO quotes (id, book_id) VALUES (678, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (678, 'zh', '这家玫瑰花园旅店虽说称不上豪华，却绝对算得上家常而又舒适，住在这里即使有些额外的花销你也会乐于承担的。');
INSERT INTO quotes (id, book_id) VALUES (679, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (679, 'zh', '如果爵爷的一生及其事业在今天看来，已经至多被当作是一种可悲的浪费，那也实在并非是我的过错—如果我为此而感到任何的遗憾或是羞惭的话，那可就真是违情悖理的苛责了。');
INSERT INTO quotes (id, book_id) VALUES (680, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (680, 'zh', '：像你我这样的人是永远都不可能来到一个可以理解当今的世界大事的位置上的，最好的办法无一例外就是要完全信任我们已经认定为明智而又可敬的那位雇主');
INSERT INTO quotes (id, book_id) VALUES (681, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (681, 'zh', '的确，我倒是最不会主张将自己的忠诚轻率地奉献给任何一位碰巧暂时雇用了你的绅士或淑女的那种人。');
INSERT INTO quotes (id, book_id) VALUES (682, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (682, 'zh', '我本人至少就认识两位同行，原本都是颇有些能力的，却从一个雇主跳到另一个雇主，永远感到不满，从来无法在任何地方安顿下来，终于落得个四处漂泊、销声匿迹的结果。');
INSERT INTO quotes (id, book_id) VALUES (683, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (683, 'zh', '换言之，就是全心全意为那些真正掌握了文明命脉的伟大绅士们提供可能的范围内最好的服务。');
INSERT INTO quotes (id, book_id) VALUES (684, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (684, 'zh', '要是你的房子着了火，你是不会把全家都召集到会客厅里，花上一个钟头的时间来讨论各种逃生办法的，是也不是？');
INSERT INTO quotes (id, book_id) VALUES (685, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (685, 'zh', '短短几年的时间当中，生活的重压已经让爵爷付出了多么沉重的代价。他的体格原本就偏于纤瘦，如今已经瘦得让人有些心惊了，瘦得甚至都有些脱了形，他的头发已经过早地变白了，他的面容则显得紧张而又枯槁。');
INSERT INTO quotes (id, book_id) VALUES (686, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (686, 'zh', '这也正是为什么，先生，我投入这么多的时间和精力，就是确保我们的声音能够被上层听到。就算是我本人因此而有了改变，或者是提早把我送进了坟墓，我也在所不惜。”');
INSERT INTO quotes (id, book_id) VALUES (687, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (687, 'zh', '使您成为一位绅士的可不是您身上衣服的剪裁，甚至不是您谈吐的优雅方式，而是别的某一种特质。很难说得清楚，可是只要眼睛不瞎，一打眼就看得出来。”');
INSERT INTO quotes (id, book_id) VALUES (688, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (688, 'zh', '紧接着，泰勒太太就将一位身材魁梧、五十来岁的男人迎了进来，看他的穿着打扮，他这一天应该都在干农活儿。');
INSERT INTO quotes (id, book_id) VALUES (689, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (689, 'zh', '反而会觉得在我面前还有数不尽的日、月、年，可以在其中慢慢地理清我跟肯顿小姐关系当中的那些别扭和无常；将来还有无数的机会可以弥补这个或那个误会所造成的影响。');
INSERT INTO quotes (id, book_id) VALUES (690, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (690, 'zh', '我是认真的，肯顿小姐。事实上，已经有一段时间，我一直都在考虑是不是还要继续这样的碰面，既然它们平白又延长了我们本已经非常忙碌的日常工作。');
INSERT INTO quotes (id, book_id) VALUES (691, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (691, 'zh', '我在走廊里犹豫了一会儿，思量着我是否应该返回去敲开门，好好弥补一下我的疏漏。可是我接着又想，要是我真这么做的话，极有可能会打扰到她不欲公开流露的哀伤之情。');
INSERT INTO quotes (id, book_id) VALUES (692, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (692, 'zh', '我告退离开，可是直到我已经出来以后，这才想起我实际上并没有明确向她致以慰唁之意。');
INSERT INTO quotes (id, book_id) VALUES (693, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (693, 'zh', '人一旦凭借着后见之明，开始在自己的过去当中找寻类似的“转折点”，我想就常常会开始觉得它们无处不在了。');
INSERT INTO quotes (id, book_id) VALUES (694, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (694, 'zh', '在此我或许应该指出的一点是，这样的变化我几乎是不可能注意不到的，因为此前她在达林顿府里这么多年间本来是极少收到信件的。');
INSERT INTO quotes (id, book_id) VALUES (695, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (695, 'zh', '他一刻都不能被人看到自己一会儿将这个角色抛到一边，一会儿又披挂整齐，就仿佛那职位不过是哑剧演员的一件戏服而已。');
INSERT INTO quotes (id, book_id) VALUES (696, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (696, 'zh', '这时她已经站到了我面前，而突然间，气氛发生了奇怪的变化—就仿佛我们俩一下子一起被推到了另一个时空当中。恐怕我也很难把我的意思完全解释清楚。我所能说的只是，我们周围的一切突然间变得完全凝固了；在我的印象中，肯顿小姐的态度也发生了突然的变化；她的表情奇怪地严肃了起来，我猛然间感觉她几乎像是被吓到了。');
INSERT INTO quotes (id, book_id) VALUES (697, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (697, 'zh', '“说真的，史蒂文斯先生，这个房间活像个囚室。只需要在墙角摆上一张小床，就完全想象得出那死刑犯在这儿度过最后几个钟头时光的情景。​”');
INSERT INTO quotes (id, book_id) VALUES (698, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (698, 'zh', '管家的餐具室，至少在我看来，是个办公要地，是家务运营的心脏，在性质上并不亚于一场战役当中的司令部，所以，在这其中的大小物件，每一样都必须完完全全依照我的意愿摆放得井井有条—并且要维持原样—这是绝对不能含糊的。');
INSERT INTO quotes (id, book_id) VALUES (699, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (699, 'zh', '可是独立伫立在一个荒凉的山坡上，透过一扇栅栏门望着远处一个村庄的灯火，天光几乎已经完全褪尽，雾气越来越浓，那滋味实在不怎么好受。');
INSERT INTO quotes (id, book_id) VALUES (700, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (700, 'zh', '在我左手边，我能看到太阳落山的最后一缕霞光。天际线时不时会被不远处田野当中的谷仓以及农舍的轮廓打破，否则的话，我真像是已经被遗落在了荒无人烟的野地。');
INSERT INTO quotes (id, book_id) VALUES (701, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (701, 'zh', '可是话又说回来了，当我想到良好的组织才能和深谋远虑恰恰是干我们这一行最重要的职业素养之时，不管怎么说，我也就很难避免再次深为自己感到失望和沮丧了。');
INSERT INTO quotes (id, book_id) VALUES (702, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (702, 'zh', '可是不管我怎么做，肯顿小姐一直都显得心不在焉。“她日后肯定会后悔莫及的，​”她又说了一遍。​“太傻了。​”');
INSERT INTO quotes (id, book_id) VALUES (703, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (703, 'zh', '你有绝对充分的理由为她的忘恩负义感到失望，可是没有任何理由为她的错误感到自责。​”');
INSERT INTO quotes (id, book_id) VALUES (704, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (704, 'zh', '这封信虽然足足写了有三页纸，可是没有一个字对肯顿小姐给予她的无微不至的照顾表示感激，也没有任何因为让我们大家都感到失望了的歉意表示。');
INSERT INTO quotes (id, book_id) VALUES (705, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (705, 'zh', '她的态度简直是每日一新，就连她走路和执行任务的仪态—在刚开始的那几天里实在是懒散邋遢到了惨不忍睹的程度—居然也有了极为显著的改善。');
INSERT INTO quotes (id, book_id) VALUES (706, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (706, 'zh', '然而，令我吃惊的是，对这个姑娘的面试结束以后，肯顿小姐却开始坚持我们应该雇用她。​“我在这个姑娘身上看到了极大的潜力，​”面对我的反对她继续道。​“我会将她置于我的直接监管之下，我会负责让她证明她是能够干得好的。​”');
INSERT INTO quotes (id, book_id) VALUES (707, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (707, 'zh', '由于回忆两位犹太雇员遭到解雇的那一事件，连带地也让我想起另一件事，我想可以被称为是那整个事件的一个有些奇怪的必然结果：就是那个叫丽萨的女仆的到来。');
INSERT INTO quotes (id, book_id) VALUES (708, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (708, 'zh', '她没再说什么，离开前我回头看了她一眼。她再次怔怔地望着窗外的景色，但到了这个时候，凉亭里面已经差不多完全暗了下来，我能看到的，就只是暗淡和空茫的背景映衬下的她的侧影。');
INSERT INTO quotes (id, book_id) VALUES (709, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (709, 'zh', '你明知道我那两个姑娘被解雇的时候，我是多么五内俱焚。你有没有意识到那会对我有多大的帮助？为什么，史蒂文斯先生，为什么，为什么，为什么你总是要去假装呢？​”');
INSERT INTO quotes (id, book_id) VALUES (710, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (710, 'zh', '我转过身来面向她的时候，她继续道：​“我记得，你当时认为让鲁思和萨拉卷铺盖走人才是唯一正确而又正当的做法。对于这件事你当时根本就是兴高采烈的。​”');
INSERT INTO quotes (id, book_id) VALUES (711, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (711, 'zh', '“肯顿小姐，我还以为您这会儿应该已经递上辞呈来了呢，​”说完我轻轻一笑。我想，我当时是希望她的态度能够终于和缓下来，做出某种和解的回应之类的，如此一来，我们就能把这整件事彻底抛到一边去了。');
INSERT INTO quotes (id, book_id) VALUES (712, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (712, 'zh', '史蒂文斯先生，我非常气愤，你居然可以坐在那儿轻轻松松地说出刚才那番话，就仿佛你不过是在跟我讨论家用食品的订货似的。');
INSERT INTO quotes (id, book_id) VALUES (713, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (713, 'zh', '可是，我已经想到了法拉戴先生有可能是为了不让我感到难堪才佯装浑然不觉的，如果我这么偷偷摸摸地把餐叉换回去，恐怕会被主人误解为对于自己的疏失我非但不痛心疾首，反而自鸣得意—或者更糟，是试图予以遮掩了。');
INSERT INTO quotes (id, book_id) VALUES (714, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (714, 'zh', '请允许我特别澄清一下，我可从来就没有暗示过一个原本极有可能令我的雇主大为失望的夜晚，完全是因为银器擦得雪亮就变得无比成功了。');
INSERT INTO quotes (id, book_id) VALUES (715, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (715, 'zh', '我记得，很快也就有好几位管家异军突起，每一位都宣称自己发现了可以超过马歇尔先生的妙方—这种妙方他们又无不装模作样地当作独得之秘概不外传，就如同那些独守祖传食谱秘方的法国名厨一般。');
INSERT INTO quotes (id, book_id) VALUES (716, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (716, 'zh', '在很长一段时间里，吉芬的产品绝对是市面上最好的银器上光剂，一直到战前不久，市场上出现了新式化工替代品以后，对这一优质产品的需求才开始衰落。');
INSERT INTO quotes (id, book_id) VALUES (717, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (717, 'zh', '毕竟，我那句俏皮话很容易被理解为我是在暗示老板娘就像一只鸡—当时我可是绝无此意的。这个想法在我尽力入睡的过程中继续不断地折磨着我，我甚至都有些想在今天一早跟店老板正式道歉了。');
INSERT INTO quotes (id, book_id) VALUES (718, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (718, 'zh', '我真想踩着泥泞走上那么一圈。只有在想到这样一番探险可能导致的灾难性后果，想到这么一来我身上这套旅行服装就要毁于一旦了，我这才按捺住这一时的冲动，退而求其次地满足于坐在这条长凳上静静地欣赏。');
INSERT INTO quotes (id, book_id) VALUES (719, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (719, 'zh', '池塘周遭遍植树木，其密度恰好能为池畔提供宜人的荫蔽，这里那里一丛丛高高的芦苇和香蒲钻出水面，也打破了那静止不动的天光云影。');
INSERT INTO quotes (id, book_id) VALUES (720, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (720, 'zh', '即无论一位管家已在多大程度上具备了这样的素质，如果他未能成功地找到一个适当的通道来将他的成就发挥出来，他也很难期望同行们能够认可他的“伟大”。');
INSERT INTO quotes (id, book_id) VALUES (721, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (721, 'zh', '任何一位有雄心有抱负的管家只管竭尽全力往这架梯子顶上爬就是了，总的说来，爬得越高，其职业声望也就越大。');
INSERT INTO quotes (id, book_id) VALUES (722, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (722, 'zh', '对我们这代人而言，我们职业声望的高低最根本地取决于我们雇主道德价值的高下上，我感觉这不失为一种公允的说法。');
INSERT INTO quotes (id, book_id) VALUES (723, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (723, 'zh', '打个比方说，我们宁肯效力于像乔治·凯特里奇先生这样尽管出身卑微，却为大英帝国未来的福祉做出过无可争辩之卓越贡献的绅士，而不愿意侍奉那些虽有显赫的贵族出身，却只会把光阴虚掷在俱乐部和高尔夫球场上的老爷们。');
INSERT INTO quotes (id, book_id) VALUES (724, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (724, 'zh', '我这么说的意思并不是指我们一心瞩目于雇主的私人行为，我的意思是我们更加热切地希望效力于那些—可以这么说—其作为正在促进人类进步的绅士，这一追求在上一代看来想必是颇不寻常的。');
INSERT INTO quotes (id, book_id) VALUES (725, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (725, 'zh', '“伟大”的先决条件是“须服务于显赫门庭”这种说法本身也许确有其道理—只要对于“显赫”的理解比海斯协会的认识更加深入即可。');
INSERT INTO quotes (id, book_id) VALUES (726, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (726, 'zh', '围裙还在她身上，显然她一直就是拿它来擦眼泪的；结果弄得她脸上尽是一道道油渍，她那副模样简直就像是在参加一场假扮黑人的滑稽说唱秀。我原本以为房间里肯定会弥漫着死亡的气息，但是拜莫蒂默太太—或者是她的围裙所赐，房间里居然一股子烧烤味儿。');
INSERT INTO quotes (id, book_id) VALUES (727, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (727, 'zh', '“我的意思是说，你看看我们整天谈论的都是些什么。合约啦，疆界啦，赔款啦，占领啦。而大自然母亲却一直都以她美好的方式生生不息。这么想问题的话确实挺可笑的，你说是不是？​”');
INSERT INTO quotes (id, book_id) VALUES (728, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (728, 'zh', '我转过身，那装着波尔图葡萄酒的酒壶仍旧在我的托盘里，重又回到了吸烟室。在那个相对狭小的房间里，就像是出现了一片由黑色的晚宴礼服、灰白的头发和雪茄烟雾组成的森林');
INSERT INTO quotes (id, book_id) VALUES (729, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (729, 'zh', '她开始走上楼梯，但我又叫住她，跟她说：​“肯顿小姐，请别把我此刻不肯马上上楼去为家父送终看作不近人情之举。您知道，我相信家父也会希望我现在履行好自己的职责。​”');
INSERT INTO quotes (id, book_id) VALUES (730, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (730, 'zh', '我感觉有什么东西碰了一下我的胳膊肘，转身发现是达林顿勋爵。“史蒂文斯，你没事吧？​”“没事，先生。我很好。​”“你看起来好像哭了。​”我笑了笑，掏出手帕迅速了擦了擦脸。​“非常抱歉，先生。是劳累了一天，太紧张了。​”');
INSERT INTO quotes (id, book_id) VALUES (731, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (731, 'zh', '确实，家父的脸色已经变成了一种暗红色，我还从没见过哪个活人有过这样的面色。我听见肯顿小姐在我身后轻声说：​“他的脉搏非常弱了。​”我凝视了家父一会儿，轻轻摸了一下他的额头，然后就把手抽了回来。');
INSERT INTO quotes (id, book_id) VALUES (732, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (732, 'zh', '我相信我很清楚您所谓的‘专业精神’指的是什么。它指的无非是通过欺骗和操纵的手段来为所欲为。它指的无非是依照自己的贪欲和利益来排定轻重缓急，而绝非是为了看到善良与正义在世界上获得胜利。如果这就是您所谓的‘专业精神’，先生，我实在是有些嗤之以鼻，巴不得对它敬而远之呢。​”');
INSERT INTO quotes (id, book_id) VALUES (733, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (733, 'zh', '不过正是出于对您这种观点的尊重，刘易斯先生，我感觉就更不应该把它当作某个街头怪人的演说那样置之不理了。让我这么来说吧：您所谓的‘外行’，先生，我想在座的大多数人更愿意称之为‘荣誉’');
INSERT INTO quotes (id, book_id) VALUES (734, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (734, 'zh', '他是何等样人呢？他是位绅士。这一点我相信在座的没有任何人会反对的。一位典型的英国绅士。正派，诚实，用心良苦。可是这位爵爷却是个外行。​”他');
INSERT INTO quotes (id, book_id) VALUES (735, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (735, 'zh', '不过话又说回来了，当年餐桌上方悬挂的那两盏巨型的枝形吊灯还是以煤气为燃料的—整个大厅因此都笼罩在一片清浅而又柔和的光晕之中—不像电气化时代以后的灯光那样亮得刺眼。');
INSERT INTO quotes (id, book_id) VALUES (736, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (736, 'zh', '“真高兴您现在感觉好些了，”我又说了一遍，然后就告退了。');
INSERT INTO quotes (id, book_id) VALUES (737, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (737, 'zh', '“我为你感到骄傲。一个好儿子。希望我对你来说也是个好父亲。但我想我并不是。”');
INSERT INTO quotes (id, book_id) VALUES (738, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (738, 'zh', '正当我站在门口踌躇不决之际，肯顿小姐出现在了我身旁，并且说道：“史蒂文斯先生，在目前这种情况下，我比您还稍微多那么点空余时间。如果您愿意的话，我可以代您照顾一下令尊。');
INSERT INTO quotes (id, book_id) VALUES (739, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (739, 'zh', '至少据我的观察而言，杜邦先生并没有参与到讨论当中，从他那闷闷不乐的行为举止上也很难看出他到底是在认真倾听别人的发言呢，还是全神贯注在别的思绪当中。');
INSERT INTO quotes (id, book_id) VALUES (740, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (740, 'zh', '这一点即便是在当时普遍都心怀戒备的气氛下都显而易见，而这也似乎更加凸显了这样一种感觉，即杜邦先生果然是能够左右未来数日会议的最终成果的关键人物。');
INSERT INTO quotes (id, book_id) VALUES (741, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (741, 'zh', '抵达时他穿的是一身人们经常看到欧陆士绅们度假时穿的那种服饰，确实，他在整个逗留期间，都始终刻意地保持着一副他完全是出于游赏和交情才会来到达林顿府的架势。');
INSERT INTO quotes (id, book_id) VALUES (742, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (742, 'zh', '杜邦先生是位个头高挑、举止优雅的绅士，蓄着灰白的胡须，戴着单片眼镜。');
INSERT INTO quotes (id, book_id) VALUES (743, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (743, 'zh', '“您总是没完没了地提到我有‘多么缺乏经验’，史蒂文斯先生，然而您却显然无法指出我的工作中有任何疏失。否则，我确信您老早就不厌其烦地不吝赐教了。');
INSERT INTO quotes (id, book_id) VALUES (744, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (744, 'zh', '我还记得有好几次，某位大人物一句话说到一半就停下来，警惕地瞥上我一眼，而爵爷无一例外地都会保证说：​“哦，但说无妨。在史蒂文斯面前您什么话都可以讲，这一点我可以向您保证');
INSERT INTO quotes (id, book_id) VALUES (745, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (745, 'zh', '在有两个人一起用餐的情况下，就算其中一位是自己的主人，你也会发现最大的难题就在于很难做到既要全意殷勤又须完全不引起注意这一优质侍餐服务的核心要义；在这种情况下，你难免会有这样的怀疑，即你的在场是否妨碍了两位用餐者的谈话。');
INSERT INTO quotes (id, book_id) VALUES (746, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (746, 'zh', '如果它在某个人发展过程的关键阶段不期而至，必将会挑战并且拓展其个人能力的极限，所以自那以后，此人便会以全新的标准来检视和要求自己了。');
INSERT INTO quotes (id, book_id) VALUES (747, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (747, 'zh', '有人说我们庄稼人早就习惯了家畜伤亡了，才不是那么回事呢。我的小儿子一连哭了好几天。您肯为了内莉停车真是菩萨心肠，先生。既然您都已经下了车了，何不进屋喝杯茶呢？');
INSERT INTO quotes (id, book_id) VALUES (748, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (748, 'zh', '她从我身边走过去，一个突然袭击把那只母鸡抓住，她把它抱小孩一样抱在怀里，一边再次向我道歉。');
INSERT INTO quotes (id, book_id) VALUES (749, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (749, 'zh', '我相当仔细地规划过前往索尔兹伯里的这趟旅程，避开了几乎所有的主干道；在有些人看来这次行车路线像是在不必要地绕圈子，不过这样一来我就能欣赏到简·西蒙斯太太在其佳著中推荐的好多处美景了，我必须说，对此我是相当满意的。');
INSERT INTO quotes (id, book_id) VALUES (750, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (750, 'zh', '白杨树的树影占据了大半块草坪，不过落照仍旧照亮了远处通向凉亭的那段草坡。我们望见家父就站在那四级石头台阶前，陷入了沉思。一阵微风轻轻地拂乱了他的头发。');
INSERT INTO quotes (id, book_id) VALUES (751, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (751, 'zh', '但我想正如此前已经说过的那样，我仍生动地记得当时那最后的斜阳穿过每扇敞开的房门，一道道橘红色的光线投射到走廊上的情景。');
INSERT INTO quotes (id, book_id) VALUES (752, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (752, 'zh', '我上次摔倒纯粹是因为那几级石阶的缘故。都已经歪歪扭扭了。应该吩咐谢默斯赶快去把它们挪挪正，以免别的人也在那儿摔倒喽。');
INSERT INTO quotes (id, book_id) VALUES (753, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (753, 'zh', '我真不知道他的腰弯背驼在多大程度上是因为年老体衰，又在多大程度上应归咎于为了适应这个小阁楼那陡斜的天花板而养成的习惯。');
INSERT INTO quotes (id, book_id) VALUES (754, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (754, 'zh', '确实，我记得当时的印象是跨入了一间牢房，后来想来，这种感觉或许跟天刚破晓时那苍白的光线以及空间的局促或者四壁的萧然也不无关系。');
INSERT INTO quotes (id, book_id) VALUES (755, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (755, 'zh', '不过据我的回忆，他的头发已经完全灰白，他那瘦高的身形已经出现了在他的晚年变得异常显著的驼背的迹象。');
INSERT INTO quotes (id, book_id) VALUES (756, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (756, 'zh', '他本质上是个真正的好人，一个彻头彻尾的绅士，时至今日，我都为自己能将最好的年华奉献给为这样一个人服务上而深感自豪。');
INSERT INTO quotes (id, book_id) VALUES (757, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (757, 'zh', '达林顿勋爵一个惯用的策略就是在我从楼梯上下来的时候装作在这个书架前检索百科全书各卷的书脊，有时候为了增加偶遇的效果，他还会真的从书架上抽出某一卷来，在我走完最后几级楼梯的时候佯装专心致志埋头阅读的样子。');
INSERT INTO quotes (id, book_id) VALUES (758, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (758, 'zh', '“不管令尊曾有过怎样的辉煌，史蒂文斯先生，他现在的能力都已经严重衰退了。这就是您所谓的这些‘微不足道的疏失’所暗含的真正意义，而如果您对此掉以轻心，那么要不了多久，令尊就将铸成大错。”');
INSERT INTO quotes (id, book_id) VALUES (759, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (759, 'zh', '他端着它们走进餐厅的时候，他那两只手抖得实在令人心惊。他迟早肯定会失手将托盘砸到某位夫人或是士绅的大腿上，就只是个时间问题罢了。');
INSERT INTO quotes (id, book_id) VALUES (760, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (760, 'zh', '前天傍晚，我眼看着令尊端着托盘脚步非常迟缓地朝餐厅走去，恐怕我很清楚地看到他的鼻尖上拖着长长的一条鼻涕，就在那些汤碗上面摇摇欲坠。');
INSERT INTO quotes (id, book_id) VALUES (761, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (761, 'zh', '最后，我认定最好的办法就是出其不意地冲出门去，怒气冲冲地大踏步离开。我于是尽可能悄无声息地先来到一个最佳的位置，从那儿可以发动这样的一次急行军，我紧握自己的清洁工具，一鼓作气地冲出门去，还没等大吃一惊的肯顿小姐醒过神来，我已经沿着走廊迈出去好几步了。');
INSERT INTO quotes (id, book_id) VALUES (762, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (762, 'zh', '的确，那肯定是发生在她上文提到某个夏日的傍晚，我还清楚地记得爬到三楼的平台，但见一道道橘红色的夕照穿过每一扇半掩的卧室房门刺破了走廊上的昏沉。');
INSERT INTO quotes (id, book_id) VALUES (763, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (763, 'zh', '那景色是否一如往昔，别来无恙？夏日的傍晚，那景色中总带有某种神奇的魔力，现在我要向你坦白，想当初我不知浪费了多少宝贵的时间，就站在一扇窗前，直看得心醉神迷。”');
INSERT INTO quotes (id, book_id) VALUES (764, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (764, 'zh', '就在刚才我把窗帘拉开的时候，外面的光线仍旧非常暗淡，还有一层类似薄雾的东西影响了我的视线，就连街对面的面包店和药房都影影绰绰的。');
INSERT INTO quotes (id, book_id) VALUES (765, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (765, 'zh', '当然了，对此您也许会不以为然，就像当初开心惬意地围炉夜话时，每当我阐述这样的见解格雷厄姆先生都会进行反驳一样：就算是我所言非虚，你也只能在亲眼目睹他在严峻的考验下的所作所为之后才有定论。');
INSERT INTO quotes (id, book_id) VALUES (766, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (766, 'zh', '，那便是由宾朋们打铃把管家唤来，要他回答各种随机的提问，比如说某某年的德比马赛中是谁赢得了桂冠，那场景活像是在杂耍戏院里向表演节目的“记忆达人”连珠发问。');
INSERT INTO quotes (id, book_id) VALUES (767, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (767, 'zh', '天晓得，为了训练标准的口音和对语言的娴熟驾驭我们到底花费了多少时间和精力，我们花费了多少个钟头去学习各种百科全书以及各类知识测试，而这些时间原本应该花费在熟练地掌握本行业的基本原理之上的。');
INSERT INTO quotes (id, book_id) VALUES (768, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (768, 'zh', '对于雄辩的口才与广阔的知识的执迷似乎是在我们这一代才兴起的，也许就正是大力效仿马歇尔先生的结果，那些等而下之的同行在努力效仿他的伟大之时错将表面文章当作了精髓和本质。');
INSERT INTO quotes (id, book_id) VALUES (769, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (769, 'zh', '他所缺少的这些特质毫无例外的都是那些肤浅和装饰性的东西，虽然无疑都是很有魅力的特质，就像蛋糕上的糖霜一样，却又都是跟真正的本质并无实际的相关性的。');
INSERT INTO quotes (id, book_id) VALUES (770, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (770, 'zh', '格雷厄姆先生是一直都认为这个“尊严”是有点类似于女性之美的，因此试图去对它分而析之是无甚意义的。');
INSERT INTO quotes (id, book_id) VALUES (771, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (771, 'zh', '入会标准之首要条件是申请人须拥有与其职位相称之高尚尊严。');
INSERT INTO quotes (id, book_id) VALUES (772, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (772, 'zh', '个中的关键就在于那种静穆的优美，那种高贵的克制。就仿佛这片土地明知道自己的优美，知道自己的伟大，又感觉无须去彰显，去招摇。');
INSERT INTO quotes (id, book_id) VALUES (773, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (773, 'zh', '我们将这片土地称为我们的大不列颠，也许还有些人觉得这未免有些妄自尊大，但我却敢于冒昧地直言，唯有我们国家的风景才配得上使用这个崇高的形容词。');
INSERT INTO quotes (id, book_id) VALUES (774, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (774, 'zh', '英国那些最优美的风景—就像我今晨所见—拥有一种其他国家的风景所付之阙如的特质，尽管它们表面上看来或许更加具有戏剧性。');
INSERT INTO quotes (id, book_id) VALUES (775, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (775, 'zh', '确实，我在傍晚时分返回宾馆的途中，好几次扭头回顾，而每一次都会欣赏到灿烂的夕阳在那巍峨的尖顶后面逐渐西沉的景象。');
INSERT INTO quotes (id, book_id) VALUES (776, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (776, 'zh', '似那般站在那里感觉确是妙不可言，周遭夏日的天籁将你笼罩，和煦的微风轻拂你的面颊。');
INSERT INTO quotes (id, book_id) VALUES (777, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (777, 'zh', '倘若还没正式踏上旅途就已经见识到了最美的景色，那岂不是有些过于草率了吗？”');
INSERT INTO quotes (id, book_id) VALUES (778, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (778, 'zh', '我只能像往常一样以微笑来应答—至少借以表明我也在某种程度上以愉快的心情参与了他正在进行的打趣和调侃—一边等着看我的雇主是否会兑现有关我外出旅行的承诺。');
INSERT INTO quotes (id, book_id) VALUES (779, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (779, 'zh', '。打个比方说，我们本质上都是从同一块布料上剪下来的布头和布尾。可是现在的情况已经是大为不同了，就算难得碰到某位雇员陪侍主人到我们这儿来做客，他也更像是个完全的陌生人，');
INSERT INTO quotes (id, book_id) VALUES (780, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (780, 'zh', '“依我看，与其说是鸡打鸣，不如说是燕子叫，先生。从流浪迁徙的角度来看。”说完后我继之以恰如其分的谦恭的微笑，以便以毫无歧义的方式表明我说的是句俏皮话，因为我可不希望法拉戴先生出于不必要的故作尊重而强忍住自发的笑意。');
INSERT INTO quotes (id, book_id) VALUES (781, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (781, 'zh', '我还记得几年前，作为贴身男仆陪侍雷金纳德·梅维斯爵士前往美国旅行的雷恩先生曾经说过，纽约的出租车司机惯常跟乘客说话的方式要是在伦敦重复一遍的话，结果即便是这个家伙不会被反剪着双臂扭送就近的警局，也八成会引发一场骚乱的。');
INSERT INTO quotes (id, book_id) VALUES (782, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (782, 'zh', '我敢肯定，他这么做只不过是在享受那种善意地揶揄取笑的乐趣，在美国这无疑是雇主和雇员间关系良好、友善的一种表现，他们将其当作一种亲切友好的游戏而乐在其中。');
INSERT INTO quotes (id, book_id) VALUES (783, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (783, 'zh', '一想到现在也许终于可以开着车到那个区域去亲眼看看了，我就按捺不住万分激动的心情。');
INSERT INTO quotes (id, book_id) VALUES (784, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (784, 'zh', '只要是我感觉又有了什么新的想法，我都会反复探究它是否还有任何纰漏，从所有的角度对它一一进行检视。');
INSERT INTO quotes (id, book_id) VALUES (785, 11);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (785, 'zh', '除了招聘雇员这一事务之外，我的新雇主在好几个其他方面也发现有必要求助于那些我也许只是因为走运才拥有的才能和品质，并且发现它们—我不妨冒昧地直言—是值得信赖和托付的。');

-- 新建作者 pick #13 · 阿尔贝·加缪
INSERT INTO authors (id, emoji) VALUES (11, '🇫🇷');
INSERT INTO author_translations (author_id, language_code, name) VALUES (11, 'zh', '阿尔贝·加缪'), (11, 'en', 'Albert Camus');
-- pick #13 · weread bookId=3300047438 · 局外人（译文经典） · 83 条划线
INSERT INTO books (id, author_id, emoji) VALUES (12, 11, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (12, 'zh', '局外人（译文经典）'), (12, 'en', 'The Stranger');

INSERT INTO quotes (id, book_id) VALUES (786, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (786, 'zh', '过了一会儿，她问我爱不爱她。我对她说，这种话毫无意义，但我似乎觉得并不爱。');
INSERT INTO quotes (id, book_id) VALUES (787, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (787, 'zh', '后来，他要去打一局台球，我跟着去差一点儿输了。接着，他又要去逛妓院。我说不，因为我不喜欢。');
INSERT INTO quotes (id, book_id) VALUES (788, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (788, 'zh', '后来，加缪又在《局外人》英译本的序言中，对这个人物作出一连串的赞词：“他不耍花招，从这个意义上说，他是他所生活的那个社会里的局外人”，“他拒绝说谎……是什么，他就说是什么。他拒绝矫饰自己的感情，于是社会就感到受到了威胁”，“他是穷人，是坦诚的人，喜爱光明正大”，“一个无任何英雄行为而自愿为真理而死的人”。');
INSERT INTO quotes (id, book_id) VALUES (789, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (789, 'zh', '他对所有涉及自己的处境与将来而需要加以斟酌的事务，都采取了超脱淡然、全然无所谓的态度，');
INSERT INTO quotes (id, book_id) VALUES (790, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (790, 'zh', '他说我得给他作证。我表示怎么都行，但我不知道该作证些什么。照雷蒙的意思，只需说那个女人冒犯了他就行了。我答应为他提供这样的证词。');
INSERT INTO quotes (id, book_id) VALUES (791, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (791, 'zh', '但他却“只因在母亲葬礼上没有哭而被判死刑”，于是，默尔索在感受到人的生存荒诞性的同时，又面临着人类世俗与社会意识形态荒诞的致命压力。这是他双重悲剧的要害。');
INSERT INTO quotes (id, book_id) VALUES (792, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (792, 'zh', '人的生存如像推石上山、劳而无功是决定于人的生而必死这种生存荒诞性。');
INSERT INTO quotes (id, book_id) VALUES (793, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (793, 'zh', '夸张与过分是喜剧所需要的成分，而蕴藏，敛聚、深刻才是悲剧的风格，');
INSERT INTO quotes (id, book_id) VALUES (794, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (794, 'zh', '首先，这样一个淡然超脱、温良柔顺、老实本分、对社会、对人群没有任何进攻性、危害性的过失犯者');
INSERT INTO quotes (id, book_id) VALUES (795, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (795, 'zh', '他的命案是糊里糊涂犯下的，应该可以从轻量刑，对此不论是他本人还是旁观者清的读者都是一清二楚的');
INSERT INTO quotes (id, book_id) VALUES (796, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (796, 'zh', '我呢，我认为这仍然是把我这个人排斥出审判过程，把我化成一个零，又以某种方式，由他取代了我。');
INSERT INTO quotes (id, book_id) VALUES (797, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (797, 'zh', '接着，他继续用这种语气讲下去，每次谈到我这个被告时，他都自称为“我”。');
INSERT INTO quotes (id, book_id) VALUES (798, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (798, 'zh', '如此接近死亡，妈妈一定感受到了解脱，因而准备再重新过一遍。任何人，任何人都没有权利哭她。');
INSERT INTO quotes (id, book_id) VALUES (799, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (799, 'zh', '我认为我是睡着了，因为醒来时我发现满天星光洒落在我脸上。田野上万籁作响，直传到我耳际。夜的气味，土地的气味，海水的气味，使我两鬓生凉。');
INSERT INTO quotes (id, book_id) VALUES (800, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (800, 'zh', '既然注定只有一种命运选中了我，而成千上万的生活幸运儿都像他这位神甫一样跟我称兄道弟，那么他们所选择的生活，他们所确定的命运，他们所尊奉的上帝，对我又有什么重要？');
INSERT INTO quotes (id, book_id) VALUES (801, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (801, 'zh', '似乎我过去一直等待的就是这一分钟，就是我也许会被判无罪的黎明。');
INSERT INTO quotes (id, book_id) VALUES (802, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (802, 'zh', '。我正要请他离开，不要再管我，他却转身向我，突然大声叫嚷了起来：“不，我不信您的话，我确信您曾经盼望过另外一种生活。');
INSERT INTO quotes (id, book_id) VALUES (803, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (803, 'zh', '，他气得两手发抖，但他挺直身子，理顺了袍子上的皱褶。然后，称我为“朋友”');
INSERT INTO quotes (id, book_id) VALUES (804, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (804, 'zh', '我的耳朵从来没有听见过这么多声音，没有分辨出过这么细微的声响。');
INSERT INTO quotes (id, book_id) VALUES (805, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (805, 'zh', '我听见自己的心在跳动，我不能想像伴随着我这么多年的心跳声，有朝一日会停止。我从未有过真正的想像力。但我还是试图想像出心跳声不再传到脑子里的那短暂的片刻。');
INSERT INTO quotes (id, book_id) VALUES (806, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (806, 'zh', '一个人对他所不了解的东西，总是会有一些夸张失真的想法。');
INSERT INTO quotes (id, book_id) VALUES (807, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (807, 'zh', '然而，我不得不承认，从它被作出的那一秒钟起，它就是那么确切无疑，严峻无情，像眼前我的身体所依靠的牢房墙壁一样。');
INSERT INTO quotes (id, book_id) VALUES (808, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (808, 'zh', '当然，所谓希望，就是在街道的某处，奔跑之中被一颗流弹击倒在地。');
INSERT INTO quotes (id, book_id) VALUES (809, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (809, 'zh', '对过去生活的种种回忆突然涌入我的脑海，那生活已经不属于我了，但我从那里确曾得到过我最可怜、最难以忘怀的快乐，如夏天的气味、我所热爱的街区、傍晚时的天空、玛丽的笑声与裙子。');
INSERT INTO quotes (id, book_id) VALUES (810, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (810, 'zh', '下午，巨大的电扇不断地搅和着大厅里混浊的空气，陪审员们手里五颜六色的小草扇全朝一个方向扇动。');
INSERT INTO quotes (id, book_id) VALUES (811, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (811, 'zh', '说到这里，检察官擦了擦因汗水闪闪发光的脸，他最后说，他的职责是痛苦的，但他要坚决地去完成。');
INSERT INTO quotes (id, book_id) VALUES (812, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (812, 'zh', '特别是在今天，我们在此人身上所看到的如此大的灵魂黑洞，正在变成整个社会有可能陷进去的深渊，就更有必要这样做。');
INSERT INTO quotes (id, book_id) VALUES (813, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (813, 'zh', '我只是觉得自己似乎是在电车上，对面坐位上有一排不认识的乘客，他们审视着新上车的人，想在他们身上发现有什么可笑之处。');
INSERT INTO quotes (id, book_id) VALUES (814, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (814, 'zh', '日子，过起来当然就长，但是拖拖拉拉，日复一日，年复一年，最后就混淆成了一片。每个日子都丧失了自己的名字。对我来说，只有“昨天”与“明天”这样的字，才具有一定的意义。');
INSERT INTO quotes (id, book_id) VALUES (815, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (815, 'zh', '他的母亲与妹妹为了谋财，用大锤砸死了他，把尸体扔进了河里。第二天早晨，他的妻子来了，懵然不知真情，通报了这位店客的姓名。母亲上吊自尽，妹妹投井而死。');
INSERT INTO quotes (id, book_id) VALUES (816, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (816, 'zh', '这样，我愈是进行回想，愈是从记忆中挖掘出了更多的已被遗忘或当时就缺乏认识的东西。');
INSERT INTO quotes (id, book_id) VALUES (817, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (817, 'zh', '只有我身旁的小个子青年与他母亲之间，仍是无声无息，就像孤立于喧嚣海洋中的一个寂静的小岛。');
INSERT INTO quotes (id, book_id) VALUES (818, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (818, 'zh', '我一走进大厅，就听见一大片嗡鸣声在高大光秃的四壁之间回荡，强烈的阳光从天空倾泻到玻璃窗上，再反射到大厅里，这一切都使我感到头昏眼花。');
INSERT INTO quotes (id, book_id) VALUES (819, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (819, 'zh', '打字机一直紧追我们的对话，这时还在打那最后的几句。');
INSERT INTO quotes (id, book_id) VALUES (820, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (820, 'zh', '像往常那样，当我听某个人说话听烦了，想要摆脱他时，就装出欣然同意的样子');
INSERT INTO quotes (id, book_id) VALUES (821, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (821, 'zh', '他矮矮胖胖，相当年轻，头发梳得整整齐齐。天气很热，我没有穿外衣，他却穿着深色的套装，衬衣的领子硬硬的，系着一根怪怪的领带，上面有黑白两色的粗条纹。');
INSERT INTO quotes (id, book_id) VALUES (822, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (822, 'zh', '在我们进行谈话后，我端详了他一番，我看清楚他是一个面目清秀的人，蓝色的眼睛深陷在鼻梁旁，身材高大，蓄着长长的灰色唇髭，头发浓密，几乎全都白了。');
INSERT INTO quotes (id, book_id) VALUES (823, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (823, 'zh', '接着，我又对准那具尸体开了四枪，子弹打进去，没有显露出什么，这就像我在苦难之门上急促地叩了四下。');
INSERT INTO quotes (id, book_id) VALUES (824, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (824, 'zh', '已经有两个钟头了，白昼纹丝未动，已经有两个钟头了，白昼在沸腾着的金属海洋中抛下了锚。');
INSERT INTO quotes (id, book_id) VALUES (825, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (825, 'zh', '从沙砾上、从白色贝壳上、从玻璃碎片上，投射出来的反光像一道道利剑，刺得我睁不开眼，不得不牙关紧缩。');
INSERT INTO quotes (id, book_id) VALUES (826, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (826, 'zh', '大海在急速而憋闷地喘息着，层层细浪拍击着沙岸。我漫步走向那片岩石，感到脑袋在太阳照射下膨胀起来了。');
INSERT INTO quotes (id, book_id) VALUES (827, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (827, 'zh', '但是天气酷热，刺眼的阳光像大雨一样从空中洒落而下，即使站在那里一动不动，我也感到很难受。');
INSERT INTO quotes (id, book_id) VALUES (828, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (828, 'zh', '太阳几乎是直射在沙滩上，它照在海面上的强烈反光叫人睁不开眼睛。海滩上一个人也没有。散落在高地边缘、俯临着大海的那些木屋里，传出一阵阵刀叉盘碟的声音。');
INSERT INTO quotes (id, book_id) VALUES (829, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (829, 'zh', '我们都有些诧异，但马松说，我们的午饭吃得太早了，不过，这也很自然，肚子饿的时候，也就是该吃饭的时候。我不知道为什么，玛丽听了这话竟笑了起来。');
INSERT INTO quotes (id, book_id) VALUES (830, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (830, 'zh', '他那位朋友名叫马松，是个高高大大的汉子，腰粗膀壮，他的女人身材矮小，胖鼓鼓的，和善可亲，讲话巴黎口音。');
INSERT INTO quotes (id, book_id) VALUES (831, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (831, 'zh', '马松与我，稍为耽搁了一会儿。他说起话来慢吞吞的，而且，不论说什么，都要在前面加一句“我甚至还要说”，其实，他并没有补充什么新意。');
INSERT INTO quotes (id, book_id) VALUES (832, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (832, 'zh', '这时，我萌生出要结婚的念头，这也许是我生平的第一次。');
INSERT INTO quotes (id, book_id) VALUES (833, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (833, 'zh', '他们冷冷地盯着我们，不过他们看人的方式总是这个样子，就像被看的是石头、是枯树。');
INSERT INTO quotes (id, book_id) VALUES (834, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (834, 'zh', '到了街上，由于我感到疲倦，也由于在屋里时没有打开百叶窗，到了街上，光天化日之下强烈的阳光，照在我脸上，就像打了我一个耳光。');
INSERT INTO quotes (id, book_id) VALUES (835, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (835, 'zh', '她瞧着我说：“你就不想知道我有什么事吗？”我倒很想知道，但我没想去问她，对此，她显出要责怪我的样子。');
INSERT INTO quotes (id, book_id) VALUES (836, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (836, 'zh', '她又沉默了一会儿之后，低声咕哝说我真是个怪人，她正是因为这点才爱我的，但将来有一天也许会由于同样的原因而讨厌我。');
INSERT INTO quotes (id, book_id) VALUES (837, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (837, 'zh', '我把窗户大大敞开，感受着夏夜在我们的棕色皮肤上流走，真是妙不可言。');
INSERT INTO quotes (id, book_id) VALUES (838, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (838, 'zh', '玛丽教我玩一种游戏，那就是在游泳的时候，迎着浪尖喝一口水含在嘴里，然后转过身将水朝天喷出。那水既像泡沫花带一样在空中稍纵即逝，又像温热的雨丝洒落在脸上，但玩了一会儿之后，我的嘴就被苦咸的海水烧得发烫。');
INSERT INTO quotes (id, book_id) VALUES (839, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (839, 'zh', '我见了她就产生了强烈的欲望，因为她穿了一件漂亮的红色条纹连衣裙，脚上是一双皮凉鞋，乳房丰满坚挺，皮肤被阳光晒成了棕色，整个人就像一朵花。');
INSERT INTO quotes (id, book_id) VALUES (840, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (840, 'zh', '我像往常一样不喜欢到塞莱斯特的饭店去吃饭，因为，那里肯定有一熟人会向我提出种种问题，这我可不喜欢。');
INSERT INTO quotes (id, book_id) VALUES (841, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (841, 'zh', '主人与狗挤住在同一个小房间里，日子久了，沙拉玛诺老头终于也像那条狗了。');
INSERT INTO quotes (id, book_id) VALUES (842, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (842, 'zh', '今天，我在办公室干了很多的活儿。老板显得和蔼可亲。他关心地问我累不累，还问我妈妈有多大岁数。');
INSERT INTO quotes (id, book_id) VALUES (843, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (843, 'zh', '我在水里看见了玛丽·卡尔多娜，她以前是与我同一个办公室的打字员。那时，我很想把她弄到手。');
INSERT INTO quotes (id, book_id) VALUES (844, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (844, 'zh', '沙拉玛诺老头，他是我同楼层的邻居。他牵着狗，八年以来，人们都见他与狗形影不离。');
INSERT INTO quotes (id, book_id) VALUES (845, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (845, 'zh', '这时，街灯突然一齐亮了，使得在夜空中初升的星星黯然失色。');
INSERT INTO quotes (id, book_id) VALUES (846, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (846, 'zh', '这时，附近的电影院一股脑儿将所有的观众都倾泻在大街上。');
INSERT INTO quotes (id, book_id) VALUES (847, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (847, 'zh', '天色有点暗了。屋顶的上空变成淡红色，随着暮色渐至，那些假日出游的人陆续往回走。');
INSERT INTO quotes (id, book_id) VALUES (848, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (848, 'zh', '我把克吕逊盐业公司的一则广告剪下来，粘贴在一个旧本子上，报纸上种种叫我开心的东西，我都贴在那里面。');
INSERT INTO quotes (id, book_id) VALUES (849, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (849, 'zh', '贝雷兹最后在村口追上我们时的那张面孔。他又激动又难过，大颗大颗的眼泪流在脸颊上。但由于脸上皱纹密布，眼泪竟流不动，时而扩散，时而汇聚，在那张哀伤变形的脸上铺陈为一片水光。');
INSERT INTO quotes (id, book_id) VALUES (850, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (850, 'zh', '所有这一切，太阳、皮革味、马粪味、油漆味、焚香味，一夜没有睡觉的疲倦，使得我头昏眼花。');
INSERT INTO quotes (id, book_id) VALUES (851, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (851, 'zh', '我环顾周围的田野，一排排柏树延伸到天边的山岭上，田野的颜色红绿相间，房屋稀疏零散，却也错落有致，见到如此景象，我对妈妈有了理解。');
INSERT INTO quotes (id, book_id) VALUES (852, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (852, 'zh', '他头戴圆顶宽檐软毡帽，棺木经过的时候，他脱下了帽子。他长裤的裤管拧绞在一起，堆在鞋面上，他黑领带的结打得太小，而白衬衫的领口又太大，很不协调。');
INSERT INTO quotes (id, book_id) VALUES (853, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (853, 'zh', '大门口，停着一辆送葬车，长方形，漆得锃亮，像个文具盒。');
INSERT INTO quotes (id, book_id) VALUES (854, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (854, 'zh', '我走出门外，太阳已经高高升起。在那些把马朗戈与大海隔开的山丘之上，天空中红光漫漫。');
INSERT INTO quotes (id, book_id) VALUES (855, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (855, 'zh', '过了一会儿，又有一个老人醒了，他咳个不停。他把痰吐在一大块方格手帕上，每吐一口痰费劲得就像动一次手术。');
INSERT INTO quotes (id, book_id) VALUES (856, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (856, 'zh', '她与令堂大人很要好，她说令堂是她在这里惟一的朋友，现在她什么人都没有了');
INSERT INTO quotes (id, book_id) VALUES (857, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (857, 'zh', '男人们几乎都很瘦，个个拄着拐杖。在他们的脸上，使我大为惊奇的一个特点是：不见眼睛，但见一大堆皱纹之中有那么一点昏浊的亮光。');
INSERT INTO quotes (id, book_id) VALUES (858, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (858, 'zh', '几乎所有的女人都系着围裙，束在腰上的带子使得她们的肚子更为鼓出。我从来没有注意过年老的女人会有这么大的肚子。');
INSERT INTO quotes (id, book_id) VALUES (859, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (859, 'zh', '之后我想抽烟。但我有所犹豫，我不知道在妈妈遗体面前能不能这样做。我想了想，觉得这无伤大雅。我递给门房一支烟，我们两人就抽起来了。');
INSERT INTO quotes (id, book_id) VALUES (860, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (860, 'zh', '在巴黎，死者可以停放三天，有时甚至四天。');
INSERT INTO quotes (id, book_id) VALUES (861, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (861, 'zh', '整个房间这时充满了夕阳的余晖。两只大胡蜂冲着玻璃顶棚嗡嗡乱飞。我觉得困劲上来了。');
INSERT INTO quotes (id, book_id) VALUES (862, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (862, 'zh', '在棺材旁边，有一个阿拉伯女护士，身穿白色罩衫，头戴一块颜色鲜亮的方巾。');
INSERT INTO quotes (id, book_id) VALUES (863, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (863, 'zh', '我走进小屋，里面是一个明亮的厅堂，墙上刷了白灰，顶上是一个玻璃天棚，放着几把椅子与几个X形的架子，正中的两个架子支着一口已盖合上了的棺材。');
INSERT INTO quotes (id, book_id) VALUES (864, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (864, 'zh', '我们经过的时候，他们就不出声了。我们一走过，他们又聊起来了，就像是一群鹦鹉在聒噪。');
INSERT INTO quotes (id, book_id) VALUES (865, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (865, 'zh', '由于这个原因，自从去年以来我就几乎没来探望过她。当然，也由于来一次就得占用我的一个星期天，且不算赶公共汽车、买车票以及在路上走两个小时所费的气力。');
INSERT INTO quotes (id, book_id) VALUES (866, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (866, 'zh', '的确如此。妈妈在家的时候，一天到晚总是瞧着我，一言不发。刚来养老院的那段时间，她经常哭，但那是因为不习惯。');
INSERT INTO quotes (id, book_id) VALUES (867, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (867, 'zh', '这么一急，这么一跑，又加上汽车的颠簸与汽油味，还有天空与公路的反光，这一切使我昏昏沉沉，几乎一路上都在打瞌睡。');
INSERT INTO quotes (id, book_id) VALUES (868, 12);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (868, 'zh', '我有点儿烦，因为我还要上艾玛尼埃尔家去借黑色领带与丧事臂章。几个月前他刚死了伯父。');

-- 新建作者 pick #15 · 特德·姜
INSERT INTO authors (id, emoji) VALUES (12, '🇺🇸');
INSERT INTO author_translations (author_id, language_code, name) VALUES (12, 'zh', '特德·姜'), (12, 'en', 'Ted Chiang');
-- pick #15 · weread bookId=26991921 · 你一生的故事（译林幻系列） · 182 条划线
INSERT INTO books (id, author_id, emoji) VALUES (13, 12, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (13, 'zh', '你一生的故事（译林幻系列）'), (13, 'en', 'Stories of Your Life and Others');

INSERT INTO quotes (id, book_id) VALUES (869, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (869, 'zh', '美本身不是问题，人们滥用美才是问题。审美干扰镜好就好在这里：它让你对这个问题保持警惕。');
INSERT INTO quotes (id, book_id) VALUES (870, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (870, 'zh', '我真的一直都喜欢看真实的面孔。但如果加雷特想要免受相貌的诱惑，我觉得自己也应该这样做。');
INSERT INTO quotes (id, book_id) VALUES (871, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (871, 'zh', '我并不是说我和那些广告商一样坏！我爱加雷特，而他们却一心想赚钱。');
INSERT INTO quotes (id, book_id) VALUES (872, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (872, 'zh', '一旦广播上的每一位发言人都给人以丘吉尔或者马丁·路德·金的在场感，我们就会觉得正常使用副语言暗示的普通人枯燥无味，不善说服，就会对在现实生活中接触到的人感到不满意，因为他们没有我们通过相貌美化仪所看到的投影那么吸引人。');
INSERT INTO quotes (id, book_id) VALUES (873, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (873, 'zh', '如果你听不见人们的音调，也看不见其面部表情，那么你就丧失了与人交往的能力。这将成为一种高层次的孤独症。');
INSERT INTO quotes (id, book_id) VALUES (874, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (874, 'zh', '审美干扰镜并不意味着你永远看不见美丽的人了。当你看见真诚的微笑时，你就看见了美。当你看见勇敢或者慷慨的行为时，你就看见了美。最重要的是，当你望着自己的心上人时，你就看见了美。');
INSERT INTO quotes (id, book_id) VALUES (875, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (875, 'zh', '然而，我在年轻的时候，想不想安审美干扰镜呢？我不知道。那样做肯定可以使我对自己渐渐变得人老珠黄少感到一些悲哀。');
INSERT INTO quotes (id, book_id) VALUES (876, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (876, 'zh', '真正需要的是以女性为中心的审美观，让所有女性都对自己感觉良好，而不是使大多数女性感觉糟糕。');
INSERT INTO quotes (id, book_id) VALUES (877, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (877, 'zh', '美不仅可以向拥有美的人提供愉悦，也可以向接受美的人提供同样多的愉悦。');
INSERT INTO quotes (id, book_id) VALUES (878, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (878, 'zh', '我们对艺术的反应涉及诸多因素，但在什么时候某个具体的事例是成功的，对此却没有一致的看法。');
INSERT INTO quotes (id, book_id) VALUES (879, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (879, 'zh', '这就是经典的公共关系策略：躲藏在一个动听的名字后面，给人以替消费者利益说话的第三方的印象。');
INSERT INTO quotes (id, book_id) VALUES (880, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (880, 'zh', '安着审美干扰镜的感觉就好像我的父母待在我脑子里，审查我的思想。现在我把它关闭了，这才恍然大悟：我是在什么样的虐待中长大的。”');
INSERT INTO quotes (id, book_id) VALUES (881, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (881, 'zh', '并非只有天才才从他们自己的天赋那里获益，我们所有人都从中获益。或者，应该说我们所有人都可以从中获益。剥夺我们这种机会可真是作孽呀。');
INSERT INTO quotes (id, book_id) VALUES (882, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (882, 'zh', '比如“魅力”这个词最早是指具有魔力的符咒，“迷人”这个词也一样。还有像“迷惑”和“销魂”这样的词更是一眼就看出来了。');
INSERT INTO quotes (id, book_id) VALUES (883, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (883, 'zh', '每当我喜欢某个小伙儿的时候，我总是纳闷他在多大程度上对我的脸蛋感兴趣，又在多大程度上对我这个人感兴趣。');
INSERT INTO quotes (id, book_id) VALUES (884, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (884, 'zh', '画里的模特实在太……我的目光无法从她身上移开。我不是说我的感觉同那次在咖啡馆里看见那个帅小伙儿一样。其实我并不想认识她。我更像是……在观望晚霞，或者说观看焰火表演。');
INSERT INTO quotes (id, book_id) VALUES (885, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (885, 'zh', '技术正在被用来刺激我们的情感反应，控制我们，因此我们也用技术来保护自己，这是再正当不过的了。');
INSERT INTO quotes (id, book_id) VALUES (886, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (886, 'zh', '生物学家称之为“超常刺激物”：给一只母鸟一只塑料大蛋，它就会丢开自己亲生的蛋，去孵化这只塑料蛋。');
INSERT INTO quotes (id, book_id) VALUES (887, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (887, 'zh', '他的脸就好像一块磁铁，而我的目光就好像指南针，直往磁铁的方向转。');
INSERT INTO quotes (id, book_id) VALUES (888, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (888, 'zh', '审美干扰镜不会遮蔽你的双眼。是美丽的外表蒙住了你的眼睛，审美干扰镜使你睁开眼睛。');
INSERT INTO quotes (id, book_id) VALUES (889, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (889, 'zh', '成熟意味着看到差异，但又意识到差异并不重要。');
INSERT INTO quotes (id, book_id) VALUES (890, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (890, 'zh', '这个系统会分析：“这是适合领略美的环境吗？如果是，那就欣赏吧；如果不是，那就忽略吧。”但这样就圆满了吗？这就是人们谈论的“辅助性成熟”吗？');
INSERT INTO quotes (id, book_id) VALUES (891, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (891, 'zh', '但实际上，外表美仅仅是个人魅力的一小部分。无论一个人的相貌如何，更重要的是看这个人的举止言谈：他说什么，怎么说，他的一举手，一投足，他的身体语言。还有，他对你的反应如何。');
INSERT INTO quotes (id, book_id) VALUES (892, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (892, 'zh', '安有相貌识别干扰仪的人能够根据发式、服装、香水，甚至走路的方式来认识他人，他们的识别缺陷纯粹局限在脸部。');
INSERT INTO quotes (id, book_id) VALUES (893, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (893, 'zh', '十八岁是法定成熟年龄，到了这个年龄，人人都有权利作出自己的决定。因此，你能做的只有相信自己的孩子，希望有最好的结果。');
INSERT INTO quotes (id, book_id) VALUES (894, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (894, 'zh', '我们也许感觉不出某人身体左侧与右侧之间的毫厘之差，可是测量尺寸表明，被列为最俊美的人也是身体部位最匀称的。');
INSERT INTO quotes (id, book_id) VALUES (895, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (895, 'zh', '鸟儿鲜艳的羽毛、哺乳动物亮丽的皮毛一样，美丽的肌肤是青春与健康唯一的、最佳的标志，在每种文化里都受到青睐');
INSERT INTO quotes (id, book_id) VALUES (896, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (896, 'zh', '所有动物都具有评价它们未来配偶的生殖潜力的标准，并演化出识别这些标准的神经“线路”。');
INSERT INTO quotes (id, book_id) VALUES (897, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (897, 'zh', '爱无条件，亦无所求，甚至不求任何爱的回报。');
INSERT INTO quotes (id, book_id) VALUES (898, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (898, 'zh', '地狱的主要惩罚是对生前没有信仰上帝的悔恨');
INSERT INTO quotes (id, book_id) VALUES (899, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (899, 'zh', '他懂得了，生命中的一切都是关于爱——哪怕是痛苦，尤其是痛苦。');
INSERT INTO quotes (id, book_id) VALUES (900, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (900, 'zh', '进入天堂以后，两个人都会改变，他们将和所有被拯救的灵魂一样，既爱对方，也爱别的一切，两种爱混合在一起，无法区分。');
INSERT INTO quotes (id, book_id) VALUES (901, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (901, 'zh', '有时候，提出问题的人会指出，她从来没有享受过双腿健全的生活，自然不会产生对那种生活的向往。如果她出生时双腿没有毛病，后来才失去它们，那样的话，她的想法可能就不是这样了。');
INSERT INTO quotes (id, book_id) VALUES (902, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (902, 'zh', '或许真的应该生活在一个由宗教信仰构成的故事中。至少，故事里总是好人受赏，坏人遭灾。哪怕区别好坏的定义有点不清不楚，总比生活在一个毫无公道可言的现实中强点吧。');
INSERT INTO quotes (id, book_id) VALUES (903, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (903, 'zh', '接受痛苦，只有这样，你才能证明对上帝的爱。接受痛苦也许不能让你今生今世更加幸福，但抗拒痛苦只能加重对你的惩罚。');
INSERT INTO quotes (id, book_id) VALUES (904, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (904, 'zh', '接受自己不能理解的神迹，当地教堂的神父这样对他说。如果你在自己的问题无法解答的情况下仍旧敬爱上帝，这就更能说明你的虔诚。');
INSERT INTO quotes (id, book_id) VALUES (905, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (905, 'zh', '这伙堕落天使的回答千篇一律，只有一句话：自己的事自己决定，我们就是这么做的，建议你也这么做。');
INSERT INTO quotes (id, book_id) VALUES (906, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (906, 'zh', '这个团体的成员死的时候当然都下了地狱，但却是带着高傲自豪的态度下去的。');
INSERT INTO quotes (id, book_id) VALUES (907, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (907, 'zh', '你不能把敬爱上帝当成实现另一个目的的手段，敬爱上帝本身就是目的。如果你想以敬爱上帝的行为换取与配偶的团圆，这种爱显然是不真诚的。');
INSERT INTO quotes (id, book_id) VALUES (908, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (908, 'zh', '对尼尔来说，这就好比碰上一个绑票的劫匪，要他付出自己的爱，作为交还妻子的赎金。他或许会被迫屈从，但发自内心、真正的爱？这是他无法付出的赎金。');
INSERT INTO quotes (id, book_id) VALUES (909, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (909, 'zh', '但在内心深处，她以自己的方式默默地景仰上帝，为自己的生活感激上帝。她从来没有试图转变尼尔。她说，信仰发自内心，有就是有，没有就是没有。');
INSERT INTO quotes (id, book_id) VALUES (910, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (910, 'zh', '她解释说，她自己并不觉得他的腿是个多大的缺陷，但只要他们俩出现在公开场合，其他人总觉得她准有什么毛病');
INSERT INTO quotes (id, book_id) VALUES (911, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (911, 'zh', '他宁愿让她永世无缘于上帝，也不愿让她跟自己分开。他知道这种想法非常自私，可这是他的真实感受，他改变不了。他相信，无论是哪种情形，莎拉都会幸福。但他唯有跟她在一起时才会幸福。');
INSERT INTO quotes (id, book_id) VALUES (912, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (912, 'zh', '尼尔的情况跟他们不一样，但听到他们的话时，他的第一反应是羡慕不已——如果莎拉去了地狱，只要自杀，他的所有问题便迎刃而解了。');
INSERT INTO quotes (id, book_id) VALUES (913, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (913, 'zh', '下一次集会罗宾没有参加，再下一次集会时，大伙儿听说了她的消息：罗宾自杀了，为的是和丈夫团圆。');
INSERT INTO quotes (id, book_id) VALUES (914, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (914, 'zh', '他蜷缩成一团，哽咽着，抽搐着，涕泪横流，内心的绞痛一阵强似一阵，达到他从来不敢相信的程度。他再也忍受不下去了。');
INSERT INTO quotes (id, book_id) VALUES (915, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (915, 'zh', '在公开场合，尼尔还能掩饰自己的痛苦（社会对成年人就是这么要求的）​。但独自一人在家时，感情的闸门便訇然洞开。');
INSERT INTO quotes (id, book_id) VALUES (916, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (916, 'zh', '至于他自己，伊桑倒是很希望成为一名传教士，却又拿不出什么说得过去的材料证明自己的信仰。那种模模糊糊的期待感当然是不够的。他盼望遇上一次神迹，帮助自己明确生活方向。');
INSERT INTO quotes (id, book_id) VALUES (917, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (917, 'zh', '他们的信仰从来没有经受过什么严峻考验，真要有什么考验，恐怕也是顶不住的。他们对上帝的爱以对生活现状的满足为基础。');
INSERT INTO quotes (id, book_id) VALUES (918, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (918, 'zh', '至于痛苦的程度，这是个主观问题，不应该把每个个体所承受的痛苦拿来作比较。表面上承受的痛苦比他更大的人应该同情他，就像他也应该同情那些痛苦程度不及他的人一样。');
INSERT INTO quotes (id, book_id) VALUES (919, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (919, 'zh', '一位腿脚不利索的听众站起身来，对她发难了：难道她竟会把重获双腿的大好事拿来和他丧失妻子的悲惨遭遇相提并论吗？难道她当真以为，她面临的所谓考验和他的一样痛苦吗？');
INSERT INTO quotes (id, book_id) VALUES (920, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (920, 'zh', '她既不骄傲，也不愤慨，平静地接受了自己的宿命，认为自己的责任就是昭告世人，没有腿并不意味着软弱；相反，这是意志坚定的证明。');
INSERT INTO quotes (id, book_id) VALUES (921, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (921, 'zh', '但是现在，情况变了，莎拉去了天堂，尼尔最大的愿望就是重新和她在一起。他必须上天堂，而进入天堂的唯一办法就是全心全意爱戴上帝。');
INSERT INTO quotes (id, book_id) VALUES (922, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (922, 'zh', '地面突然化为透明，这时你就能清清楚楚地看见地狱，仿佛地板上出现了一个大洞，你可以从上往下看到洞里的情形。那些堕落的灵魂看上去和他们在世时没多大区别，不朽的身体继续保持着生前的模样。');
INSERT INTO quotes (id, book_id) VALUES (923, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (923, 'zh', '他恼火的是这些集会的基调：绝大多数人都说自己如何重新找到了对上帝的信仰，还一个劲儿地劝说那些死了亲人的人，说死者家属也应该有同样感受。');
INSERT INTO quotes (id, book_id) VALUES (924, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (924, 'zh', '他们毫无同情怜悯之心，具备在牺牲品情感甲胄上发现薄弱环节的本能，而且，压迫弱小反倒增强了他们之间的友谊。');
INSERT INTO quotes (id, book_id) VALUES (925, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (925, 'zh', '尼尔生活中发生的大悲剧非常惨痛，却又十分寻常：他的妻子莎拉去世了。');
INSERT INTO quotes (id, book_id) VALUES (926, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (926, 'zh', '人类这个物种将在其行为允许的范围内永远存在，兴衰纯粹取决于其自身的活动，不会因为天定寿限到头而消亡。像花朵随着季节绽放凋零一样，其他物种随着地质时代起起落落，而人类只要想继续存在就能存在下去。');
INSERT INTO quotes (id, book_id) VALUES (927, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (927, 'zh', '光影在地板和墙壁上舞动，将储藏室变成了德鲁伊的仪式地点。热力让自动机更猛烈地撞击房门，仿佛火蜥蜴祭司跳着越来越狂乱的舞步，紧接着自动机忽然定在了那里；名字着火，字母被烧掉了。');
INSERT INTO quotes (id, book_id) VALUES (928, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (928, 'zh', '男人说。他用猛禽和刺客狩猎时的眼神打量斯特拉顿。');
INSERT INTO quotes (id, book_id) VALUES (929, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (929, 'zh', '他和小组里的其他几位命名师合作，对命名可能性这棵参天大树分而治之，每人负责研究几个分支，剪去确定不会结果的枝杈，培育看似最有希望的枝杈。');
INSERT INTO quotes (id, book_id) VALUES (930, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (930, 'zh', '“科学进步并不总是一帆风顺，斯特拉顿先生，皇家学会有时候需要官方和非官方双管齐下。”');
INSERT INTO quotes (id, book_id) VALUES (931, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (931, 'zh', '“名字其实不是植入的，而是用特制针头铭印的。”');
INSERT INTO quotes (id, book_id) VALUES (932, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (932, 'zh', '有驱动力的名字的词序增加躯体的有序度，从而为自动机提供动力。');
INSERT INTO quotes (id, book_id) VALUES (933, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (933, 'zh', '斯特拉顿想象着后果。“随着时间过去，大众将越来越明显地失去生育能力。不等末日降临，人们就会陷入恐慌');
INSERT INTO quotes (id, book_id) VALUES (934, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (934, 'zh', '马车非常豪华，内部是上漆的红木、抛光的黄铜和拉毛的天鹅绒。拉车的牵引机也非常昂贵，是一匹青铜浇铸的战马，不需要御者将其引至熟悉的目的地。');
INSERT INTO quotes (id, book_id) VALUES (935, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (935, 'zh', '“提取的时候狗都还没凉透呢￼！没有比它更有效的了。”');
INSERT INTO quotes (id, book_id) VALUES (936, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (936, 'zh', '要是整个学徒期都在看着自动机替他们做事，那能培养出什么雕刻师呀？我绝不允许这么可敬的职业沦落为木偶戏。');
INSERT INTO quotes (id, book_id) VALUES (937, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (937, 'zh', '意图暂且不论，但你的自动机将让雕刻师失业。他们当了这么多年学徒，熬过了这么多年训练。到时候他们该怎么养活家人呢？”');
INSERT INTO quotes (id, book_id) VALUES (938, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (938, 'zh', '这些自动机的学习能力极其有限。它们能拼装模具，但永远没法设计模具；雕刻的核心工艺只能由雕刻师完成。');
INSERT INTO quotes (id, book_id) VALUES (939, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (939, 'zh', '你见过纺织厂雇用的童工吗？他们干活干得筋疲力尽，肺部被棉尘阻塞；他们病得厉害，很难相信他们能活到成年。');
INSERT INTO quotes (id, book_id) VALUES (940, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (940, 'zh', '我的最终目标是降低自动机引擎的制造费用，让大部分家庭都买得起。');
INSERT INTO quotes (id, book_id) VALUES (941, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (941, 'zh', '铸铁巨人不知疲倦地摇动曲柄，驱使齿轮转动。走过巨人的时候，斯特拉顿感觉到丝丝凉意，因为引擎正在从周围吸收热能。');
INSERT INTO quotes (id, book_id) VALUES (942, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (942, 'zh', '不同的罐子装着不同等级的黏土，从最常见的红土到最精细的白色高岭土都有，很像盛满液体巧克力或厚奶油的大杯子；但强烈的矿物味道打破了这个幻觉。');
INSERT INTO quotes (id, book_id) VALUES (943, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (943, 'zh', '一位柏林的命名师基于对热的新理解发明出了新的护符，能让一具躯体在一个地方吸收热能，然后到另一个地方释放出来。');
INSERT INTO quotes (id, book_id) VALUES (944, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (944, 'zh', '例如一位爱丁堡的命名师研究出了防止物品遗失的护符，他以此注册了一种家用自动机的专利，这种自动机能将物品放回指定的位置。');
INSERT INTO quotes (id, book_id) VALUES (945, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (945, 'zh', '由于一切事物都是神的映像，因此一切名字都是神名的映像。');
INSERT INTO quotes (id, book_id) VALUES (946, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (946, 'zh', '若是遇到墙壁，黏土小人儿只会一直向前踏步，直到将两臂和双腿碾成奇形怪状的鳍肢');
INSERT INTO quotes (id, book_id) VALUES (947, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (947, 'zh', '他张开嘴，想说他完全明白她的意思，他与她有同样的感受。但他没有说出来。因为这种感应将使他们分离，而不是凝聚在一起，所以他不能告诉她。');
INSERT INTO quotes (id, book_id) VALUES (948, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (948, 'zh', '夫妻俩坐在餐桌旁。她故意眺望窗外；这是她即将开始严肃谈话时的习惯。');
INSERT INTO quotes (id, book_id) VALUES (949, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (949, 'zh', '随之而起的是自我宽恕的条件反射。他这样想：你不可能要求别人在任何危机中都始终如一地支持你。');
INSERT INTO quotes (id, book_id) VALUES (950, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (950, 'zh', '卡尔知道安娜一直对他和马琳之间的心灵相通有一点儿嫉妒。他究竟有什么奥妙，能走进马琳的心灵，对此安娜一直感到纳闷。其实答案很简单。这就是同情与共鸣之间的差异。');
INSERT INTO quotes (id, book_id) VALUES (951, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (951, 'zh', '这种情形似曾相识，却又逆反得荒谬。他记得自己曾经待在一座建筑物房顶的一道锁着的门内，听见一位朋友在外面一边猛力敲门，一边向他吼叫别寻短见。');
INSERT INTO quotes (id, book_id) VALUES (952, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (952, 'zh', '数学的许多内容并没有实际用处，她的理论也可以仅仅作为一种形式而存在，研究它只是为了它所包含的智力美。');
INSERT INTO quotes (id, book_id) VALUES (953, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (953, 'zh', '当时的解决方法只是扩展语境，用在这里不起作用。虚数给数学增添了新的内容，而我的形式系统却是给已经存在的东西下定义。');
INSERT INTO quotes (id, book_id) VALUES (954, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (954, 'zh', '她心里想，现在要到关键处了。她意识到自己用力过大，下意识地放松握在手中的铅笔。');
INSERT INTO quotes (id, book_id) VALUES (955, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (955, 'zh', '她边写边咬牙切齿，写下那些文字时，感觉好像她正用指甲刮过黑板似的。');
INSERT INTO quotes (id, book_id) VALUES (956, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (956, 'zh', '数学包含或许是真实的，但在本质上却无法证明的陈述。');
INSERT INTO quotes (id, book_id) VALUES (957, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (957, 'zh', '雷内是成年人，不会像神童那样，因为发现自己正在成为平庸的成年人而感到幻灭的痛苦。');
INSERT INTO quotes (id, book_id) VALUES (958, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (958, 'zh', '他在倾听雷内在客厅对面她自己的书房里揉皱纸张的沙沙声。整个晚上她都在工作，可以感觉出她愈来愈焦躁不安。');
INSERT INTO quotes (id, book_id) VALUES (959, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (959, 'zh', '卡尔很吃惊；他能够辨认出什么样的脸经常微笑，什么样的脸经常皱眉，但是对她那张脸，他却捉摸不透。');
INSERT INTO quotes (id, book_id) VALUES (960, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (960, 'zh', '他被她那张脸吸引住了。那是一张异常平庸的脸，大多数时间不苟言笑，但在那次聚会期间，他看见她两度微笑，两度皱眉。');
INSERT INTO quotes (id, book_id) VALUES (961, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (961, 'zh', '我觉得如果让我给你从头到尾讲一遍的话，你可能会受我引导，只能得出和我相同的结论。');
INSERT INTO quotes (id, book_id) VALUES (962, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (962, 'zh', '这种形式具有一种内在的完美，由地砖那光滑、清凉的感觉所证实。还有，地砖彼此拼接，之间的线条严密得天衣无缝。她为这种精确性激动得浑身颤抖。');
INSERT INTO quotes (id, book_id) VALUES (963, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (963, 'zh', '他的父母来接他，回家途中，他母亲唠叨了一些空洞无物的话，什么大家见到他会多么高兴呀等等。他竭力抑制住自己，才没有甩开母亲搭在他肩膀上的手。');
INSERT INTO quotes (id, book_id) VALUES (964, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (964, 'zh', '她想干脆一把火把书稿烧了，但那样做只有象征意义。其实，只要对它们视而不见，效果是一样的。');
INSERT INTO quotes (id, book_id) VALUES (965, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (965, 'zh', '他视智慧为手段，我却视智慧为终极目标。');
INSERT INTO quotes (id, book_id) VALUES (966, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (966, 'zh', '我热爱美，他热爱人类。彼此都觉得对方忽视了大好机会。');
INSERT INTO quotes (id, book_id) VALUES (967, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (967, 'zh', '他的谈话速度和我一样快，他能够提出令我耳目一新的主意，他和我一样能够认知万物的本质，与这样的人讨论问题是多么惬意。他也怀着同样的渴望。');
INSERT INTO quotes (id, book_id) VALUES (968, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (968, 'zh', '他则不能容忍一个具有超常智慧的人单纯做个自了汉，置苍生于不顾');
INSERT INTO quotes (id, book_id) VALUES (969, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (969, 'zh', '这些幻觉使我创造人工大脑的决心更加坚定。只有拥有这种结构，我才能够真正把握我追求的本质，而不是仅仅停留在梦想里。要获得大彻大悟，我的脑神经衍生物还需要大量增生，突破临界值。');
INSERT INTO quotes (id, book_id) VALUES (970, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (970, 'zh', '我让自己的意识充分利用现有资源，不要超越这一范围。这很困难：我仿佛局处笼中，既坐不下去，也站不起来。一旦要放松或者延展身体，接踵而来的便是剧痛和疯狂。');
INSERT INTO quotes (id, book_id) VALUES (971, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (971, 'zh', '我再也无法正常做梦了。我缺乏任何可以叫作潜意识的东西，大脑的全部功能尽在我的控制之下，于是，梦成了过时货，不存在了。');
INSERT INTO quotes (id, book_id) VALUES (972, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (972, 'zh', '我头部的血液循环速度比常人快得多，所以我还得剃光头发，帮助头部更快散热。');
INSERT INTO quotes (id, book_id) VALUES (973, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (973, 'zh', '我周围满是令人目眩、欢快而又恐惧的对称。一切都与内在规律暗合，乃至于大千宇宙即将成为一幅丝丝入扣的图画。我正在接近终极规律：知识万象尽入其中，光芒万丈，是宇宙的黄钟大吕。');
INSERT INTO quotes (id, book_id) VALUES (974, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (974, 'zh', '性、侵略和自我保护的潜流，由我童年的环境生成，与理性发生冲突，有时候也乔装打扮成理性。我每一种情绪背后所有的原因，我每一个决定之下的动机，我无所不知。');
INSERT INTO quotes (id, book_id) VALUES (975, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (975, 'zh', '我不自夸能看见自己的神经细胞在燃烧，这种豪迈属于约翰·李利和他在二十世纪六十年代进行的致幻药试验。');
INSERT INTO quotes (id, book_id) VALUES (976, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (976, 'zh', '如果哥德尔在世，他宁愿抛弃一切也要见识一下这种语言。');
INSERT INTO quotes (id, book_id) VALUES (977, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (977, 'zh', '动用第四瓶荷尔蒙K？这个念头萦绕脑际，挥之不去。目前停滞状态中所经历的每一次挫折都提醒我，我是有可能达到更高境界的。');
INSERT INTO quotes (id, book_id) VALUES (978, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (978, 'zh', '也许这是魔鬼的诱惑，但毕竟是诱惑。而且，我找不出抗拒的理由。');
INSERT INTO quotes (id, book_id) VALUES (979, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (979, 'zh', '我不时想起孔子的“仁”这个概念：“仁慈”这个词远不足以表达“仁”的内涵，“仁”浓缩了人性的精华，只有通过与人接触才能获得，孤独者是无缘问津的。');
INSERT INTO quotes (id, book_id) VALUES (980, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (980, 'zh', '有关备忘录只是拐弯抹角地提及，这些计划漂浮在无伤大雅的文件形成的海洋中间，如果某个调查委员会审读全部档案，证据一定会被淹没在杂音里。然而，只要对那些暗藏玄机的备忘录作一番分析过滤，新闻界便一定会相信。');
INSERT INTO quotes (id, book_id) VALUES (981, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (981, 'zh', '只须拉长步伐，头略微上下移动，减少手臂的动作，再加上一身奇装异服，便足以让我在他们眼皮底下穿过那个地区。');
INSERT INTO quotes (id, book_id) VALUES (982, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (982, 'zh', '一个人扮演的是什么角色，年纪更长、更为成熟的人一眼就能看出来。在我眼里，世人就好像在游乐场嬉戏的孩童。我被他们的认真劲逗乐了，回想起当年我也是如此，不免感到几分尴尬。');
INSERT INTO quotes (id, book_id) VALUES (983, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (983, 'zh', '我不费吹灰之力就能看穿众生百相。漫步街头，我观察人们忙于各自的事情，虽然他们一言未发，但其心思昭然若揭。');
INSERT INTO quotes (id, book_id) VALUES (984, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (984, 'zh', '昨天晚上，我进入了卢卡斯防盗系统公司的服务数据库，这家公司向宾夕法尼亚信使公司出售掌纹锁。我在数据库里找到了一份加密文件，里面包含超越客户设置打开掌纹锁的密码。');
INSERT INTO quotes (id, book_id) VALUES (985, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (985, 'zh', '我策划这些行动就是为了让警方和中央情报局低估我的能力，以免他们采取严密的防范措施，这对我很有利。警方程序员在计算机上清除掉我的病毒后，会认为我的编程技术好是好，但谈不上杰出。');
INSERT INTO quotes (id, book_id) VALUES (986, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (986, 'zh', '研究人员的结论是：荷尔蒙K仅仅替换受伤的神经细胞，并不替换健康的神经细胞。对于大脑受伤的动物，新生的树突似乎并没有危害：经正电子发射断层扫描，大脑的新陈代谢没有显示出变化，');
INSERT INTO quotes (id, book_id) VALUES (987, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (987, 'zh', '我忍不住从书桌前站起来，放声大叫，好像我心爱的棒球队刚刚出人意料地打出一个本垒打。就是这个感觉。');
INSERT INTO quotes (id, book_id) VALUES (988, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (988, 'zh', '早在大学时代，我就接受了这样一个事实：感兴趣的东西很多，全部涉猎却不可能。现在却发现自己也许能够做到，这真让人欢欣鼓舞');
INSERT INTO quotes (id, book_id) VALUES (989, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (989, 'zh', '“不是副作用。荷尔蒙K疗法能够使大量受损的神经细胞获得再生，对你的大脑来说，这是个很大的变化，大脑不得不作出大幅度调整以适应这种变化。你做的噩梦可能就是调整的一个迹象。”');
INSERT INTO quotes (id, book_id) VALUES (990, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (990, 'zh', '我双手紧紧抓住羽绒被，浑身颤抖。我竭力镇定下来，放缓呼吸，却止不住地呜咽起来。梦里的感觉太真实了：那是死亡的滋味。');
INSERT INTO quotes (id, book_id) VALUES (991, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (991, 'zh', '我竭力挥拳敲打冰层，可是手臂动作缓慢。我的肺部准是迸裂了，大脑一片混沌。我觉得自己正在消融');
INSERT INTO quotes (id, book_id) VALUES (992, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (992, 'zh', '人类所能迈过的最长旅程并不能让他们冲破边界，而只会带领他们回到最初的出发点。');
INSERT INTO quotes (id, book_id) VALUES (993, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (993, 'zh', '不知怎么回事，上面天堂的地窖竟然在大地之下。尽管这两者相隔无数里格，却又仿佛紧紧相连，叠放在一起。');
INSERT INTO quotes (id, book_id) VALUES (994, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (994, 'zh', '他翻了个身，呻吟起来。肢体没有一处不疼，他全身赤裸，身上大片擦伤，没有擦伤的皮肤被水泡得起皱。尽管如此，他能呼吸到空气。');
INSERT INTO quotes (id, book_id) VALUES (995, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (995, 'zh', '终于，他再也屏不住呼吸了，不由自主地张嘴吸气。他在溺亡，黑暗包围了他，伸进他的肺中。');
INSERT INTO quotes (id, book_id) VALUES (996, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (996, 'zh', '他不知道另外两人听见没有。水面升至拱顶，他吸进他的最后一口空气，向上游进那道裂缝。他将死于天堂近旁，比之前的任何人离天堂更近。');
INSERT INTO quotes (id, book_id) VALUES (997, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (997, 'zh', '希拉鲁姆想象着自己正站在耶和华黑漆漆的食道里，而那位全能的神祇正大口地畅饮天堂之水，准备一口吞掉他们这些罪人。');
INSERT INTO quotes (id, book_id) VALUES (998, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (998, 'zh', '我们的劳作是出于对耶和华的爱。我们把一生都奉献给了耶和华，还有我们的父辈、祖辈，无数代先辈。虔诚如我辈，是不会被苛责的。');
INSERT INTO quotes (id, book_id) VALUES (999, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (999, 'zh', '天堂的窖底就在上面，伸直手臂，指尖就能触到。跳起来摸一把，感觉又光又凉。它的材质似乎是打磨得极其光滑的白色花岗石，没有丝毫瑕疵，没有任何与别处不同的特异之处——问题就出在这里。');
INSERT INTO quotes (id, book_id) VALUES (1000, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1000, 'zh', '这种从大地罅隙渗出的黏稠液体混合着砖头，在高高的塔顶凝结，固定，仿佛大地本身长出了一截肢体，伸进天空。');
INSERT INTO quotes (id, book_id) VALUES (1001, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1001, 'zh', '僧侣们带领大家向耶和华祈祷，感谢他允许他们看到这么多；然后乞求他的原谅，因为他们还想看到更多。');
INSERT INTO quotes (id, book_id) VALUES (1002, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1002, 'zh', '也许人类本来就不该生活在这样的地方。如果人类的天性限制了他们，不让他们过分接近天堂，那么，人类或许应该好好待在地面才是。');
INSERT INTO quotes (id, book_id) VALUES (1003, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1003, 'zh', '它就像一片岩层，其重量堪比整个世界，偏偏却没有任何支撑，这让希拉鲁姆产生了一种他身在矿井之下时从未有过的恐惧：害怕拱顶坍塌，把他埋在下面。');
INSERT INTO quotes (id, book_id) VALUES (1004, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1004, 'zh', '现在，与其说他们是爬向天空，不如说他们正攀向一片毫无特征、白茫茫的大平原。这片平原向各个方向延伸开去，大得无边无际。');
INSERT INTO quotes (id, book_id) VALUES (1005, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1005, 'zh', '这说明他们已经非常接近天堂的地窖，可以看清它的底部——那个拱形窖底就像一片硬壳，将整个天空容纳其中。');
INSERT INTO quotes (id, book_id) VALUES (1006, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1006, 'zh', '“它卡在墙里，烧得咝咝响，亮得让人不敢正眼看它。大伙儿本打算把它撬松，说不定它还能接着飞。可它实在太烫了，没法靠近，大家又不敢往上浇水。');
INSERT INTO quotes (id, book_id) VALUES (1007, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1007, 'zh', '银色的月光泻在高塔南壁，闪闪发亮，仿佛耶和华的眼睛在观察他们。没过多久，他们便和月亮的运行轨道齐平了。这是他们够到的第一尊天体。大家侧着脑袋，注视着坑坑洼洼的月面，赞叹地看着它不依靠任何支撑优雅地移动。');
INSERT INTO quotes (id, book_id) VALUES (1008, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1008, 'zh', '这些人生活在潮湿的云雾中，上下两个方向都能看到暴雨，还在空中收割庄稼——却完全不觉得人类不应该住在这种地方。这些居民并没有获得来自上苍的许诺或者鼓励，却丝毫也不担心，泰然自若地生活着。');
INSERT INTO quotes (id, book_id) VALUES (1009, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1009, 'zh', '仰视和俯视都令人惶恐——让人心里踏实的连续性消失了，他们不再是大地的一部分。这座塔完全可能是悬在半空中的一段线头，向下踏不着大地，向上挨不着天堂');
INSERT INTO quotes (id, book_id) VALUES (1010, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1010, 'zh', '库答的妻子阿丽特姆回答道：“没去过。我们去那里干什么？需要爬上爬下那么多天，再说我们这儿什么都不缺。”');
INSERT INTO quotes (id, book_id) VALUES (1011, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1011, 'zh', '库答耸耸肩，“我们住在通往天堂的大道上，我们所做的一切都是为了延伸这条大道。就算要离开这座塔，我们也会走上行坡道，走向天堂，而不是向下。”');
INSERT INTO quotes (id, book_id) VALUES (1012, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1012, 'zh', '平生头一次，他真正明白了黑夜是什么——它是这个世界投下的影子，投射在天空中。');
INSERT INTO quotes (id, book_id) VALUES (1013, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1013, 'zh', '希拉鲁姆翻过身来，向上望去，刚好赶上看见夜色飞快地漫过上面的塔身。慢慢地，太阳朝遥不可及的世界的边缘沉了下去，天空黯淡下来。');
INSERT INTO quotes (id, book_id) VALUES (1014, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1014, 'zh', '你们可以眼看着黑夜顺着这座塔爬上来，从地面爬到天空。爬得很快，但你们还是能看见这个过程。');
INSERT INTO quotes (id, book_id) VALUES (1015, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1015, 'zh', '“好好想想。太阳落到西边那些山巅后面的时候，示拿的平原就变成了黑夜。可在这儿，我们比那些山更高。所以哪怕太阳落到了山后，我们还是能看见它。要让我们这儿变成黑夜，太阳必须落到更远的地方。”');
INSERT INTO quotes (id, book_id) VALUES (1016, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1016, 'zh', '希拉鲁姆不愿意表现得像个胆怯的小孩子，但他实在鼓不起勇气就那么坐在塔边，脚下就是几千肘尺的绝壁，于是只好肚皮贴地趴下，只把脑袋探到塔边。');
INSERT INTO quotes (id, book_id) VALUES (1017, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1017, 'zh', '一路坠落，距离可不短啊，撞上地面之前能念完一段祷词。这个念头让希拉鲁姆打了个哆嗦。');
INSERT INTO quotes (id, book_id) VALUES (1018, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1018, 'zh', '“我完全没问题。”但他瞥了南尼一眼。究竟如何，他们自己清楚。 “手心直冒汗，对不对？”南尼悄声道。 希拉鲁姆在粗糙的纤绳上擦了擦手，点点头。');
INSERT INTO quotes (id, book_id) VALUES (1019, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1019, 'zh', '巴比伦城则是一幅由街巷和建筑织成的极其繁复的图样，阳光下，建筑上的石膏涂料闪闪发亮');
INSERT INTO quotes (id, book_id) VALUES (1020, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1020, 'zh', '在下面的城市，正午的时候，温度高得能把急匆匆爬过街道的四脚蛇热死在半道上。');
INSERT INTO quotes (id, book_id) VALUES (1021, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1021, 'zh', '路面铺砖，车辆通行数百年后，坡道上碾压出了两道深深的车辙。');
INSERT INTO quotes (id, book_id) VALUES (1022, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1022, 'zh', '希拉鲁姆的眼睛眨巴着，眯缝着，直到头晕目眩。他踉踉跄跄地后退了几步，打了个寒噤，转开了视线。');
INSERT INTO quotes (id, book_id) VALUES (1023, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1023, 'zh', '听说在塔顶工作的泥水匠如果失手掉落一块砖，他们会扯着头发痛哭号啕，因为四个月后才能补上这块砖；可如果一个人坠塔而死，谁都不会在意。请问这是真的吗？');
INSERT INTO quotes (id, book_id) VALUES (1024, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1024, 'zh', '在热腾腾的、闪烁着微光的空气中，它就像一束细细的麻线，飘飘荡荡，从宛如一个泥壳的巴比伦城升腾而上。');
INSERT INTO quotes (id, book_id) VALUES (1025, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1025, 'zh', '把一块砖放进这种拖车以后，要过四个月时间，它才会被人从拖车上搬下来，砌进塔身，成为这座塔的一部分。');
INSERT INTO quotes (id, book_id) VALUES (1026, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1026, 'zh', '我想对霍金以及所有比我年轻的人们说：耐心点。你的未来将会来到你面前，像只小狗一样躺在你脚边，无论你是什么样，它都会理解你，爱你。');
INSERT INTO quotes (id, book_id) VALUES (1027, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1027, 'zh', '那时，分娩过去还不久，我仍然觉得自己仿佛是一条绞干了水的毛巾。');
INSERT INTO quotes (id, book_id) VALUES (1028, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1028, 'zh', '在我学会以七肢桶语言B作为思维工具之前，我的记忆仿佛是一截烟灰，意识的香烟连续不断燃烧着当前，遗下一长条无数细小微粒组成的烟灰。');
INSERT INTO quotes (id, book_id) VALUES (1029, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1029, 'zh', '他对这场演出的脚本一无所知，但仍旧把自己角色的台词说得分毫不差。');
INSERT INTO quotes (id, book_id) VALUES (1030, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1030, 'zh', '空调带来的舒适几乎可以抵消和他谈话的不愉快。');
INSERT INTO quotes (id, book_id) VALUES (1031, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1031, 'zh', '“好啊，既然你知道故事是怎么写的，干吗非得我念给你听？” “我想听你念嘛！”');
INSERT INTO quotes (id, book_id) VALUES (1032, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1032, 'zh', '婚礼上人人都知道会有一句“我现在宣布你们结为夫妻”，这无关紧要。重要的是主婚人说出这一句话。没有这句话，单有其他仪式是不行的。对于述行语词而言，说话就是行动。');
INSERT INTO quotes (id, book_id) VALUES (1033, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1033, 'zh', '预知未来又与自由意志产生了矛盾。正因为能够自由选择，所以我不可能预知未来。反过来说，如果我已经知道了未来，我便不可能反抗这个既定的命运，也不可能把我知道的未来告诉其他人——这也是一种形式的反抗。');
INSERT INTO quotes (id, book_id) VALUES (1034, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1034, 'zh', '“婴儿”这个词源自拉丁语，意思是“不能说话的”。');
INSERT INTO quotes (id, book_id) VALUES (1035, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1035, 'zh', '考虑这样一句话，“兔子可以吃了”。如果把“兔子”一词当作“吃”这个动词的对象，这句话的含义就是饭准备好了。如果“兔子”这个词是主语，这句话的发生环境便可能是小姑娘告诉妈妈，她已经为兔子准备好了饲料。');
INSERT INTO quotes (id, book_id) VALUES (1036, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1036, 'zh', '小时候我曾经发过誓，等我当了妈妈，一定和孩子讲道理，把孩子当作一个有智力、有独立思考能力的人看待——所有誓言全都成了零。');
INSERT INTO quotes (id, book_id) VALUES (1037, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1037, 'zh', '“这些我原本知道。”我会说，“毕竟跟你父亲一块儿过了这么多年。只是有些事磨掉了，没想起来。” “');
INSERT INTO quotes (id, book_id) VALUES (1038, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1038, 'zh', '构成我的思维的是一团团图像式符号。有一天，我突然发现，自己的思维竟然不是通过内心的声音表达！而只是凭着心灵的眼睛看到一团团七语，像窗户玻璃上的雾气一样渐渐展开！那一瞬间真是让人心醉神迷。');
INSERT INTO quotes (id, book_id) VALUES (1039, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1039, 'zh', '男孩子会凝望着这双眼睛，就像我从前与未来凝望你父亲的眼睛时一样。这双眼睛啊，加上跟你父亲一样的黑头发，他们也会产生与我对你父亲一样的感情：惊叹不已，沉醉其中。今后，你会有很多很多的追求者');
INSERT INTO quotes (id, book_id) VALUES (1040, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1040, 'zh', '我将生出一个自己能走动的巫术小像。这个合约是我签下的，可签约时没人告诉我这一部分。这种交易向来如此吗？');
INSERT INTO quotes (id, book_id) VALUES (1041, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1041, 'zh', '你总是四处乱跑，每次绊倒在门槛上、擦破膝盖时，我自己的身体都会真切地感受到你的疼痛。我的身体好像延伸了，另外长出一条到处游走不定的肢体。');
INSERT INTO quotes (id, book_id) VALUES (1042, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1042, 'zh', '没多久前你还喜欢跟我一起逛商场。你飞快地长过一个阶段，进入另一个阶段，这种速度始终让我惊奇不已。和你生活在一起像瞄准不断移动的目标。你将永远比我想象的更快一步。');
INSERT INTO quotes (id, book_id) VALUES (1043, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1043, 'zh', '居然会是那个需要我抱起来才能够到饮水机的小女孩，那个摇摇晃晃跑出我的卧室，身上拖拖拉拉裹着从我衣橱里偷走的长裙、帽子和四条丝巾的小女孩。这是同一个人吗？');
INSERT INTO quotes (id, book_id) VALUES (1044, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1044, 'zh', '你会好好考虑，你的小眉头上会皱起两个小窝窝，每当你绞你的小脑汁时就会这样。');
INSERT INTO quotes (id, book_id) VALUES (1045, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1045, 'zh', '你会把一只行李箱填得满满的，把想带的衣服和玩具全都塞进去。你还会拖着行李箱满屋子走，看你拉着它能走多远。');
INSERT INTO quotes (id, book_id) VALUES (1046, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1046, 'zh', '其实我心里想的是，你跟我不一样，完全不一样。这件事将再一次提醒我，你不是我的复制品。你是一个奇迹，是我每日的快乐，但我不能自称为你唯一的创造者。');
INSERT INTO quotes (id, book_id) VALUES (1047, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1047, 'zh', '问一个土著“这东西叫什么”。土著说：“Kanguru。”从此以后，库克和他的手下便用这个词称呼这种动物（袋鼠）。很久以后他们才明白，Kanguru在土著语言中的意思是：你说什么来着？');
INSERT INTO quotes (id, book_id) VALUES (1048, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1048, 'zh', '七肢桶的身体周围排着一圈眼睛，共有七只，没有眼皮。');
INSERT INTO quotes (id, book_id) VALUES (1049, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1049, 'zh', '外星人有七根长肢，从四周向中央辐辏，轴心处挂着一个圆桶。整个形体极度对称，七肢中任何一肢都可以起到腿的作用，同时任何一肢也都可以当作手臂。');
INSERT INTO quotes (id, book_id) VALUES (1050, 13);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1050, 'zh', '我们跳的是一支慢舞，一对三十来岁的夫妻在溶溶月光下舞动身躯，就像两个孩子。');

-- 新建作者 pick #16 · 钱穆
INSERT INTO authors (id, emoji) VALUES (13, '🇨🇳');
INSERT INTO author_translations (author_id, language_code, name) VALUES (13, 'zh', '钱穆'), (13, 'en', 'Qian Mu');
-- pick #16 · weread bookId=23523072 · 中国历代政治得失 · 29 条划线
INSERT INTO books (id, author_id, emoji) VALUES (14, 13, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (14, 'zh', '中国历代政治得失'), (14, 'en', 'Chinese Political History Through the Ages');

INSERT INTO quotes (id, book_id) VALUES (1051, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1051, 'zh', '可见任何制度有利亦有弊，并不是我们的传统政治只是专制黑暗，无理性，无法度；却是一切合理性有法度的制度全都该不断改进，不断生长。');
INSERT INTO quotes (id, book_id) VALUES (1052, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1052, 'zh', '把人才分成九品，上上、上中、上下，中上、中中、中下，下上、下中、下下。');
INSERT INTO quotes (id, book_id) VALUES (1053, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1053, 'zh', '唐代设“御史台”，所谓三省、六部、一台，御史台成为一独立之机构，不属于三省。换言之，监察权是脱离相权而独立了。此即是唐代监察制度与汉代相异之点。');
INSERT INTO quotes (id, book_id) VALUES (1054, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1054, 'zh', '唐县分上、中、下三等：六千户以上为上县，六千户以下、三千户以上为中县，三千户以下为下县。汉县仅分二级：万户以上为大县，其长官称“令”。万户以下为二级县，其长官称“长”。可见唐代的县比汉县为小。唐代的州也分上、中、下三级：十万户以上为上州，二万户以上为中州，二万户以下为下州。');
INSERT INTO quotes (id, book_id) VALUES (1055, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1055, 'zh', '唐代地方行政最低一级为“县”，和汉代一样。唐玄宗时，全国有一千五百七十三个县，比汉代多出两百多县。县级以上为“州”。唐之“州”与汉“郡”是平等的。');
INSERT INTO quotes (id, book_id) VALUES (1056, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1056, 'zh', '吏部：主管人事及任用之权。官吏必先经过考试，再由吏部分发任用。五品以上官，由宰相决定，但吏部可以提名。五品以下官，宰相不过问，全由吏部依法任用。 户部：掌管民政、户口等事。 礼部：主管宗教、教育事宜。 兵部：掌军事。 刑部：掌司法。 工部：主管建设。');
INSERT INTO quotes (id, book_id) VALUES (1057, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1057, 'zh', '尚书省是政府里最高最大的行政机构。尚书省共分六部，即吏部、户部、礼部、兵部、刑部、工部。此六部制度，自唐代以至清代末年，推行了一千多年，不过六部次序有时略有改动。');
INSERT INTO quotes (id, book_id) VALUES (1058, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1058, 'zh', '开会时有一主席，称为“执笔”。讨论结果，由他综合纪录，等于现在之书记长。');
INSERT INTO quotes (id, book_id) VALUES (1059, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1059, 'zh', '故唐制遇下诏勅，便先由门下省和中书省举行联席会议。会议场所称为“政事堂”。');
INSERT INTO quotes (id, book_id) VALUES (1060, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1060, 'zh', '中国政治上的传统观念，对一意见之从违抉择，往往并不取决于多数，如西方所谓之民主精神。而中国人传统，则常求取决于贤人。');
INSERT INTO quotes (id, book_id) VALUES (1061, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1061, 'zh', '若门下省反对此项诏书，即将原诏书批注送还，称为“涂归”，意即将原诏书涂改后送还中书省重拟之意。涂归亦称“封驳”“封还”“驳还”等，其意义略相同');
INSERT INTO quotes (id, book_id) VALUES (1062, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1062, 'zh', '后来人却说赵普以半部《论语》治天下。大概他读《论语》，也没有好好仔细读。');
INSERT INTO quotes (id, book_id) VALUES (1063, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1063, 'zh', '不过事情隔久了，这事情演变之本原意义忘失了，后人便只见得皇帝之尊严与宰相之卑微了。');
INSERT INTO quotes (id, book_id) VALUES (1064, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1064, 'zh', '荆公是要重新厘定三司权限，要把当时所谓中书治民、枢密主兵、三司理财的军、民、财政之职权三分重新馆合。');
INSERT INTO quotes (id, book_id) VALUES (1065, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1065, 'zh', '武官有勋无职，因此并不干预政治，而自有其尊荣。');
INSERT INTO quotes (id, book_id) VALUES (1066, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1066, 'zh', '府地距离中央五百里的，宿卫一次得五番。一千里的七番，一千五百里者八番，二千里十番，二千里以外十二番。');
INSERT INTO quotes (id, book_id) VALUES (1067, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1067, 'zh', '简单说，好像汉代是在社会上层节制资本，而下层则没有力量管，唐代注意社会下层，由国家来计划分配，而让上层的富民能自由发展。');
INSERT INTO quotes (id, book_id) VALUES (1068, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1068, 'zh', '据当时一般意见说，租庸调制三个项目分得很清楚，现在归并在一起，虽说手续简单，但日久相沿，把原来化繁就简的来历忘了；遇到政府要用钱，要用劳役，又不免要增加新项目。');
INSERT INTO quotes (id, book_id) VALUES (1069, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1069, 'zh', '“账”则是壮丁册子，在今年即预定明年课役的数目。这是庸的根据。唐制每岁一造账，三岁一造籍。壮丁册子一年重造一次，户籍册子则三年重造一次，一次称“一比”，因其可以用来和上期的簿账相比对。');
INSERT INTO quotes (id, book_id) VALUES (1070, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1070, 'zh', '“租”即是粟米之征，“庸”是力役之征，“调”是布帛之征。');
INSERT INTO quotes (id, book_id) VALUES (1071, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1071, 'zh', '其实革命的本质，应该是推翻制度来迁就现实的，决非是推翻现实来迁就制度的。');
INSERT INTO quotes (id, book_id) VALUES (1072, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1072, 'zh', '于是做官的也各务奔竞，袭取社会名誉，却不管自己本官职务与实际工作，而其上司也无法奈何他。');
INSERT INTO quotes (id, book_id) VALUES (1073, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1073, 'zh', '假使此项监察使巡视边疆，在边防重地停驻下来，中央要他对地方事务随宜应付，临时得以全权支配；这即成为“节度使”。“节”是当时一种全权印信，受有此全权印信者，便可全权调度，故称“节度使”。');
INSERT INTO quotes (id, book_id) VALUES (1074, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1074, 'zh', '姑设一浅譬');
INSERT INTO quotes (id, book_id) VALUES (1075, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1075, 'zh', '在汉制，刺史规定六条视察，');
INSERT INTO quotes (id, book_id) VALUES (1076, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1076, 'zh', '唐代则迁调虽速，下级的永远沉沦在下级，轻易不会升迁到上级去。于是在官品中渐分清浊，影响行政实际效力极大。');
INSERT INTO quotes (id, book_id) VALUES (1077, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1077, 'zh', '因此当时虽非封建社会，爵位不世袭，而书本却可世袭。虽不是世代簪缨，却是世代经学。世代经学，便可世代跑进政治圈子，使无异一封建传袭的贵族了。');
INSERT INTO quotes (id, book_id) VALUES (1078, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1078, 'zh', '当时规定，奴隶也须缴人口税，而且须加倍缴。但这是由养奴隶的主人家负担的，不干奴隶自身事。因此汉代的奴隶特别多。');
INSERT INTO quotes (id, book_id) VALUES (1079, 14);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1079, 'zh', '丞相、太尉、御史大夫称三公。丞相管行政，是文官首长；太尉管军事，是武官首长；御史大夫掌监察，辅助丞相来监察一切政治设施，他是副丞相。');

-- 新建作者 pick #23 · 刘亮程
INSERT INTO authors (id, emoji) VALUES (14, '🇨🇳');
INSERT INTO author_translations (author_id, language_code, name) VALUES (14, 'zh', '刘亮程'), (14, 'en', 'Liu Liangcheng');
-- pick #23 · weread bookId=3300115431 · 本巴（第十一届茅盾文学奖获奖作品） · 38 条划线
INSERT INTO books (id, author_id, emoji) VALUES (15, 14, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (15, 'zh', '本巴（第十一届茅盾文学奖获奖作品）'), (15, 'en', 'Benba');

INSERT INTO quotes (id, book_id) VALUES (1080, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1080, 'zh', '“如果说你会失去什么，你只会失去好汉的美名；如果说我会失去什么，我只会失去良驹的名声。除此之外，没有什么别的会失去。');
INSERT INTO quotes (id, book_id) VALUES (1081, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1081, 'zh', '天很快黑了，星星一个一个地冒出来，忙着布置深绿色的夜空。山也黑黑地围拢过来。山谷朝上，好像漫天繁星是它张口说出的。');
INSERT INTO quotes (id, book_id) VALUES (1082, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1082, 'zh', '羊命短，它就不住地往前世来世里喊。 这样能把命喊长吗？赫兰说。 羊的命已经被它们咩咩咩地喊长了，我们在史诗里听到的羊、东归路上回来的羊，都是今天的羊，也是明天明年的羊。忽闪说。');
INSERT INTO quotes (id, book_id) VALUES (1083, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1083, 'zh', '我们的奶茶中只是加了点盐，并没有像史诗中那样，加入地老天荒的时间');
INSERT INTO quotes (id, book_id) VALUES (1084, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1084, 'zh', '，牧游重在参与，大家都把自己放到故事里，就好玩了。就像史诗里的人，他们知道自己是故事人，并不真的存在。但每个人都专心致志把自己的故事演绎好。');
INSERT INTO quotes (id, book_id) VALUES (1085, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1085, 'zh', '树每天新生出一条影子来，朝西朝东丈量过大地，然后带着这个世界的长短远近去了梦里。');
INSERT INTO quotes (id, book_id) VALUES (1086, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1086, 'zh', '这丝孤独像是一条影子，静悄悄地爬在心里。 赫兰想，待它积累得厚重了，便会爬出来，忽长忽短地消受世上的光阴吧。');
INSERT INTO quotes (id, book_id) VALUES (1087, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1087, 'zh', '他继而感到喝进嘴里的酒也没有味道。或许齐只说了酒让人醉，让人热血沸腾，却没有说出它的味道。在一场场的酒宴中，江格尔和勇士们喝到嘴里的酒，都没有味道。');
INSERT INTO quotes (id, book_id) VALUES (1088, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1088, 'zh', '坐了一圈的众勇士都愣愣地听着，面无表情，仿佛讲述此时此刻的齐，没有给他们表情，也没有给他们知道真相后的惊奇和慌乱。');
INSERT INTO quotes (id, book_id) VALUES (1089, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1089, 'zh', '腿关节依旧冷飕飕地疼痛，似乎那里有一场没刮走的寒风。');
INSERT INTO quotes (id, book_id) VALUES (1090, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1090, 'zh', '我越来越相信，在我所经历的一切中，只有这场梦中的迁徙是真的，它在真实地消耗着人畜的生命和体力。 我在吹着他们的寒风中感到了从未有过的寒冷。 我在那里看见了真正的死亡。 每个人每头牛羊，都真实地在死去和活着。');
INSERT INTO quotes (id, book_id) VALUES (1091, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1091, 'zh', '哈日王说，你不用为我的牧民操心，他们需要太阳，会自己梦见，不需要，挂在头顶也会遗忘。');
INSERT INTO quotes (id, book_id) VALUES (1092, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1092, 'zh', '辽阔平坦的拉玛草原上，白色宫殿的巨大影子，铺展成汗的铁青色夜晚。牛羊纷乱的影子伸长成牛羊的夜晚。酥油草和蚂蚱的影子长大成各自的夜晚。');
INSERT INTO quotes (id, book_id) VALUES (1093, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1093, 'zh', '这群做梦的人和牛羊，倏忽间已经把天走黑。');
INSERT INTO quotes (id, book_id) VALUES (1094, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1094, 'zh', '赫兰还是母腹中一团模糊的梦时，他看见自己长出眼睛，以前以后多少年的生活铺展在眼前。长出耳朵，从生到死的所有声音一时间响起来。长出嘴，却再也说不出那时的样子。');
INSERT INTO quotes (id, book_id) VALUES (1095, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1095, 'zh', '贾登不知道，他在夜夜的梦里为巴登高兴，他脸上的微笑是巴登的，心里的幸福也是巴登的。');
INSERT INTO quotes (id, book_id) VALUES (1096, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1096, 'zh', '天色也灰暗，像被用旧的一个破烂白天，又拿过来罩在今天的草原上。');
INSERT INTO quotes (id, book_id) VALUES (1097, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1097, 'zh', '我在你看我的昏花眼神中认出你小时候的明亮眼神，从你老态龙钟的脚步中认出你幼年的步子，从你跟我说话的粗哑声音中，认出我在母腹听见的你的清脆童音。');
INSERT INTO quotes (id, book_id) VALUES (1098, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1098, 'zh', '他是本巴唯一的老人，他一个人过着所有人的老年。');
INSERT INTO quotes (id, book_id) VALUES (1099, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1099, 'zh', '江格尔说，我也能在别人的梦中做梦，可是，这个梦太强大，他捕到我深藏心中的想法，让我心甘情愿把这个梦做到底。我该如何破了这个我愿意一直做下去的梦呢。');
INSERT INTO quotes (id, book_id) VALUES (1100, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1100, 'zh', '您在梦中看见父亲被铁链拴在孤独的老年，但从您父亲那里看，我们也都被铁链拴在二十五岁的青年。只是我们看不见拴住自己的铁链，也不知道需要谁来解救。');
INSERT INTO quotes (id, book_id) VALUES (1101, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1101, 'zh', '父亲活在我的身体里。他所经历的我都在经历。我坐在他坐过的王位上，感觉自己坐在他怀里。我一岁岁活成他的样子。我看人看近处远处的眼神是他的，微笑和皱眉是他的，说话和咳嗽的声音是他的。');
INSERT INTO quotes (id, book_id) VALUES (1102, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1102, 'zh', '他们把他扔到冰雪翻天的老风口，他便做一个春暖花开的梦。把他扔到日头毒烈的沙漠中，他便做一个凉风习习的梦');
INSERT INTO quotes (id, book_id) VALUES (1103, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1103, 'zh', '江格尔和策吉走出班布来宫殿，天上闲散地堆着几朵白云，与地上的白毡房遥相对应，仿佛它们彼此是对方的影子。');
INSERT INTO quotes (id, book_id) VALUES (1104, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1104, 'zh', '既看见莽古斯匆忙逃跑的后背，又同时看见他们担惊受怕的脸和前胸。这样的感觉让他无所不在，仿佛自己在万物中，睁开眼睛。');
INSERT INTO quotes (id, book_id) VALUES (1105, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1105, 'zh', '赫兰很快习惯了洪古尔对他的好，他把洪古尔躺下时平坦的胸脯当草原，把洪古尔站起时弯曲的脊背当山梁，把洪古尔仰脸眺望的头颅当山峰，他在那里顺着洪古尔的眼睛望去，九色十层的班布来宫殿竖立在眼前。');
INSERT INTO quotes (id, book_id) VALUES (1106, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1106, 'zh', '她让有蹄子和脚的都离开路，让她的两个儿子顺利走来。她让有舌头的都变成哑巴，只剩下她孩子的声音。');
INSERT INTO quotes (id, book_id) VALUES (1107, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1107, 'zh', '赫兰沿着被他们追赶藏匿的路往回走，他这才发现，往回走的路是多么遥远。 当时他逃跑躲藏时后面有脚步和喊声追赶，他不知疲倦。 现在，他要费劲地从自己曾经藏匿的一处处草丛和树林中走出来，从一座座近山和远山后面走出来，从一个个白天和黑夜中走出来。');
INSERT INTO quotes (id, book_id) VALUES (1108, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1108, 'zh', '本巴草原，被称为天下最平坦的草原，在马背上放一只装满圣水的宝瓶，打马走过，宝瓶里的水都不会溢出一滴。');
INSERT INTO quotes (id, book_id) VALUES (1109, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1109, 'zh', '他们的喊叫声裹在风撕扯树梢的声音里，急促的脚步声藏在风吹响沙土的声音里。他们开始隐蔽地找他，而不像以前那样大喊大叫，这让他更加恐惧。');
INSERT INTO quotes (id, book_id) VALUES (1110, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1110, 'zh', '他无法成为一个不相干的人，也没有单独的一条路让他回家。');
INSERT INTO quotes (id, book_id) VALUES (1111, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1111, 'zh', '声音空空散开，没有一只耳朵接住。');
INSERT INTO quotes (id, book_id) VALUES (1112, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1112, 'zh', '江格尔环顾一周，见没一个挺身而起的英雄。无论嘴快的、腿快的、眼快的还是脑子快的，都沉默不语，眼睛全看着策吉。他是本巴的大谋士，大家都在说话时，他的话最有理，大家都没话说时，他的话最有用。');
INSERT INTO quotes (id, book_id) VALUES (1113, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1113, 'zh', '早晨出发时以为在迁往另一个山谷的另一片草场，傍晚重新搭建毡房时又觉得还在老地方，一样的蒲公英开在身边，一样的星星和月亮挂在毡房上头，这让人觉得，这个世界其实就在一个山谷里，移动的只是光阴和人畜的脚步。');
INSERT INTO quotes (id, book_id) VALUES (1114, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1114, 'zh', '羊有四个蹄子，每个蹄子都在耽误时间。');
INSERT INTO quotes (id, book_id) VALUES (1115, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1115, 'zh', '每个山谷吹来的风也不一样，因为山谷里长的草不一样，开的花不一样，马的颜色和味道不一样。');
INSERT INTO quotes (id, book_id) VALUES (1116, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1116, 'zh', '告诉你，我站在这座山顶，朝她望了九九八十一年，还没望见宫殿的顶圈。');
INSERT INTO quotes (id, book_id) VALUES (1117, 15);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1117, 'zh', '她一张口，整个宫殿瞬间亮堂起来，醉眼昏花的男人们，在她美丽容颜的光芒里，看见沉在碗底的经年酒垢，恍然明白自己已经喝了多少年月的酒，沉在心里的酒垢也被瞬间照亮。');

-- 新建作者 pick #30 · 约恩·卡尔曼·斯特凡松
INSERT INTO authors (id, emoji) VALUES (15, '🇮🇸');
INSERT INTO author_translations (author_id, language_code, name) VALUES (15, 'zh', '约恩·卡尔曼·斯特凡松'), (15, 'en', 'Jón Kalman Stefánsson');
-- pick #30 · weread bookId=3300058976 · 冰岛往事.1，狂暴海 · 32 条划线
INSERT INTO books (id, author_id, emoji) VALUES (16, 15, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (16, 'zh', '冰岛往事.1，狂暴海'), (16, 'en', 'About the Night and About the Children of the Night');

INSERT INTO quotes (id, book_id) VALUES (1118, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1118, 'zh', '他们听到海尔加的脚步声越来越近，迅速而平静的脚步。有些人走路就是这样，似乎什么都不能让他们失去平衡，似乎他们走什么道路都毫无困难，也有一些人除了犹豫什么都不会。');
INSERT INTO quotes (id, book_id) VALUES (1119, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1119, 'zh', '盖尔普特或许看了他一眼，海尔加比盖尔普特多看了他几眼，但是船长失明的眼睛自始至终都在盯着他，目不转睛，那冰冷的、没有生命的、暗淡的窗户，什么都出不来，什么都进不去。');
INSERT INTO quotes (id, book_id) VALUES (1120, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1120, 'zh', '盖尔普特带着科尔本穿过村庄，到了她的房子，就好比一条可怜的老狗，杀了它也会是慈悲的行为。');
INSERT INTO quotes (id, book_id) VALUES (1121, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1121, 'zh', '盖尔普特接着说道：要从精致的杯子里喝水或是使用精美的餐具吃饭，并不需要拥有特殊的才能，不过很多人对此的认识当然都是错误的。');
INSERT INTO quotes (id, book_id) VALUES (1122, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1122, 'zh', '男孩笔直地坐在豪华沙发上，为身上尽是污点的羊毛裤而感到羞愧。然而朋友不久前才死去，就冻死在他的面前，生命显得毫无目的、毫无意义，自己甚至打算今夜在海里结束生命，这种时候却要因为脏兮兮的裤子而羞愧，真是够悲哀的。');
INSERT INTO quotes (id, book_id) VALUES (1123, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1123, 'zh', '有时醒来，感到身体里有冰冷的手。它们比冰还冷，每天都离我的心脏更近一些。');
INSERT INTO quotes (id, book_id) VALUES (1124, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1124, 'zh', '带着三瓶啤酒的人在这个世界上没必要匆匆忙忙。');
INSERT INTO quotes (id, book_id) VALUES (1125, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1125, 'zh', '被冰困住了，连同哥本哈根的学生寄来的所有的信，那些信件有的倾诉了对家人的苦苦想念和爱的告白，信中表达的感情是如此炽热，完全可以让它们从船头悬吊下去融化坚冰，开出一条水路。');
INSERT INTO quotes (id, book_id) VALUES (1126, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1126, 'zh', '他强迫自己细嚼慢咽，因为周围的环境所需的礼仪和用餐举止要比他平时所习惯的更加优雅。');
INSERT INTO quotes (id, book_id) VALUES (1127, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1127, 'zh', '时间一眨眼，她就成了角落里衰弱的老太太，只能回味着乏味的回忆和别人都想不起来的名字。');
INSERT INTO quotes (id, book_id) VALUES (1128, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1128, 'zh', '想搞清楚自己为什么活着，想知道生活中是否有自己的位置。');
INSERT INTO quotes (id, book_id) VALUES (1129, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1129, 'zh', '等待他的还能有什么呢？只是呼吸，吃东西，上厕所，读书，在别人和他交谈时回应。人为什么活着呢？');
INSERT INTO quotes (id, book_id) VALUES (1130, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1130, 'zh', '多云的四月之光洒到他身上，扫掉了黑暗，照在屋里。');
INSERT INTO quotes (id, book_id) VALUES (1131, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1131, 'zh', '这里冬天的傍晚是如此漫长，将黑暗从一个山头串联到另一个山头。');
INSERT INTO quotes (id, book_id) VALUES (1132, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1132, 'zh', '教堂塔楼上有个雪白的十字架，只不过黎明时分常有两只乌鸦停在屋脊上，扯着沙哑的嗓子哇哇叫，就好像是在提醒我们别忘了永恒的黑夜。');
INSERT INTO quotes (id, book_id) VALUES (1133, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1133, 'zh', '宽敞的两层小楼和高高的阁楼，这就是古特杨送给盖尔普特的结婚礼物。他们的房子建在村子地势最高的街道上，在教区长的住宅旁边，整条街上住的都是有地位的人，包括治安官、医生、富有的船长。');
INSERT INTO quotes (id, book_id) VALUES (1134, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1134, 'zh', '生活对我们两个都没有意义，所以结婚是符合逻辑的，年龄差异并不重要。');
INSERT INTO quotes (id, book_id) VALUES (1135, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1135, 'zh', '早婚在这里是司空见惯的事。我们都早早就成了家，这样在黑夜和寒冷统治世界时我们就能躺在一起取暖了。');
INSERT INTO quotes (id, book_id) VALUES (1136, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1136, 'zh', '她收到的下一封信会很厚，会是来自死者的充满激情的话语。');
INSERT INTO quotes (id, book_id) VALUES (1137, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1137, 'zh', '她问风、问雪，却没有得到回答。它们不需要回答她。风继续吹，它来也匆匆去也匆匆；雪花继续从天上飘落，所以它们才是白色的，样子就像天使的翅膀。上天从不需要解释什么，拱形的天空就高悬在我们头顶，凌驾于我们的生活之上。天空总是那么遥远，不论我们是站在屋顶还是站在山上，都永远无法接近它，哪怕是借助词语或交通工具都没有用。');
INSERT INTO quotes (id, book_id) VALUES (1138, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1138, 'zh', '这种暖意很快就完全离开了划船放钓线的四个人，另两个人也感到了寒冷，不过为了证明自己的强壮，他们并没有流露出来。当然，他们或许并不强壮，只不过是怕被人瞧不起。人们的念头有时很荒谬。');
INSERT INTO quotes (id, book_id) VALUES (1139, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1139, 'zh', '那常常是在隆冬最黑暗的时候，那黑暗是如此浓郁，你仿佛可以抽出刀把姓名的首字母刻入黑暗，让夜晚把你的名字带进早晨。');
INSERT INTO quotes (id, book_id) VALUES (1140, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1140, 'zh', '他哆嗦了一下，迅速转身，大步走向他的房屋。在渔船争先出发后笼罩夜晚的平静中，他的动作如此迅速而突然，甚至搅动了环绕在屋子周围的空气，仿佛让空气微微颤抖。');
INSERT INTO quotes (id, book_id) VALUES (1141, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1141, 'zh', '男孩把乳清桶举到船上。人的心脏又能承受多少东西呢？船装满了。');
INSERT INTO quotes (id, book_id) VALUES (1142, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1142, 'zh', '空气在颤抖，仿似有什么庞然大物被撕裂了，他们听到太阳坠落到大地上发出的碰撞声。人们活着时，有属于他们的时刻，有属于他们的亲吻和大笑、拥抱和亲密的话语、喜悦和哀愁。');
INSERT INTO quotes (id, book_id) VALUES (1143, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1143, 'zh', '咖啡滚烫，同最黑的夜晚一样黑，但是咖啡里可以加方糖。如果能把糖加进夜晚，让它变得甜美，那该多好啊。');
INSERT INTO quotes (id, book_id) VALUES (1144, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1144, 'zh', '培图尔眯着眼睛，等着睡意完全消失，做过的梦消散无形，感官恢复清醒。他站在那里，弯着腰，驼着背，像一只令人无法理解的野兽，嗅着空气，瞥视着黑暗的云，倾听着、感受着风中的信息，发出半是哼哼半是咆哮的声音。');
INSERT INTO quotes (id, book_id) VALUES (1145, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1145, 'zh', '吉斯利喝酒后身体不舒服，连着三天没有出现在学校里了，他压力很大，除了喝酒还必须教书。');
INSERT INTO quotes (id, book_id) VALUES (1146, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1146, 'zh', '房屋两边的山墙都装了窗户，一扇框住了山，另一扇框住了天空和海，而它们框住了我们的存在。');
INSERT INTO quotes (id, book_id) VALUES (1147, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1147, 'zh', '人们或许永远不可能买到最有意义的东西，不可能买到。当然不可能，很遗憾。然而从正面说就是，感谢上帝，这些东西买不到。');
INSERT INTO quotes (id, book_id) VALUES (1148, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1148, 'zh', '在那黑暗来临之处，天空不再是无边的蓝色，空气中有夜晚的气息。');
INSERT INTO quotes (id, book_id) VALUES (1149, 16);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1149, 'zh', '那些人于你而言仅仅意味着倾斜的十字架和损毁的墓碑上的名字，生命和记忆都被时间的律令无情地抹去了，这正是我们想改变的。');

-- pick #32 · weread bookId=3300021172 · 显克维奇中短篇小说选（人文社外国文学名著经典·网格本） · 60 条划线
INSERT INTO books (id, author_id, emoji) VALUES (17, 8, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (17, 'zh', '显克维奇中短篇小说选（人文社外国文学名著经典·网格本）'), (17, 'en', 'Selected Short Stories');

INSERT INTO quotes (id, book_id) VALUES (1150, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1150, 'zh', '那少女开始说起话来，声音低得就像莲花的白色花瓣被夏日的和风亲吻时所发出的响声一样。');
INSERT INTO quotes (id, book_id) VALUES (1151, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1151, 'zh', '她之所以能出污泥而不染，甚至不是她努力的结果，而是出自她的天性，哪里还能找到这样的姑娘呢？');
INSERT INTO quotes (id, book_id) VALUES (1152, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1152, 'zh', '然而你从她们的言谈举止中可以看出她们的愉快，主要是来自她们结识了一位正人君子，而不是因为他给了她们帮助的缘故。');
INSERT INTO quotes (id, book_id) VALUES (1153, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1153, 'zh', '所有刚才的那些想法，现在就像那空虚和黑夜所产生的梦幻一样，一下子消失得无影无踪了。刚刚他还认为是合情合理的事情，是务必实行和容易办到的事情，现在却觉得是荒谬的胡思乱想了，甚至是不诚实的表现。');
INSERT INTO quotes (id, book_id) VALUES (1154, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1154, 'zh', '才能把对恶的感受变成为斗争和改革的动力，而不能只是一种到了明天就会减弱的印象！');
INSERT INTO quotes (id, book_id) VALUES (1155, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1155, 'zh', '那时候他第一次看见了意大利、罗马、西西里岛、大海、非洲海岸，但是任何印象都不能抹去他心中对所爱女人的思念。无论是在佛罗伦萨和罗马的画廊里，还是在大海或沙漠中，她都是在伴随着他的，他总是通过她来感受那一切的，他到处对她说“你看”，仿佛她就在他面前似的。');
INSERT INTO quotes (id, book_id) VALUES (1156, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1156, 'zh', '他说完这句话后，一想到艾尔曾夫人已把他们的婚约看成是确定了，需要把这件事告诉大家，心里就感到有些不安。可是艾尔曾夫人的亲热态度，她的美貌和妩媚，又使他如获至宝，心里乐滋滋的。');
INSERT INTO quotes (id, book_id) VALUES (1157, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1157, 'zh', '而在波兰人当中看到的却是相反的东西，除了几个或者十几个人是例外，大多数波兰画家有才华，但缺乏思想，思维不发达，没有受过教育，他们赖以生存的只是从法国餐桌上打扫下来的一些迂腐学说的残羹剩饭，而从来也没有想过要发表自己关于艺术的独特见解，更没有想到要独立自主地去创作具有波兰风格的艺术作品。');
INSERT INTO quotes (id, book_id) VALUES (1158, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1158, 'zh', '不管他愿意不愿意，他都必须把艾尔曾夫人和她的两个孩子安置在他的生命之舟中了。一想起这点，他简直无法忍受。在这种时候，因为他是个诚实的人，他不愿去责怪艾尔曾夫人，于是他只好骂罗莫拉和勒莫，怪他们的不会发“r”音，怪他们那像小鸟一样的脑壳。');
INSERT INTO quotes (id, book_id) VALUES (1159, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1159, 'zh', '要是认为她不再希冀过宁静和纯洁的生活，不再有对和平和欢乐的憧憬，那也是无稽之谈！正因为这些原因，这样的女人甚至会比别的人更加珍惜一个正直男人所给予她的一切保障哩！”这最后一条理由，他认为击中要害，入木三分。');
INSERT INTO quotes (id, book_id) VALUES (1160, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1160, 'zh', '舞台的布景，晚上看起来是那样的辉煌动人，白天阳光一照，却成了一幅拙劣的绘画。生活中也往往出现类似的现象。');
INSERT INTO quotes (id, book_id) VALUES (1161, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1161, 'zh', '既然我知道，这些破碎的灵魂在悲剧之前有男人，悲剧完了之后又会得到情人，那还有什么悲剧可谈呢？她又会像以前一样去迷惑人，一切又会是同样的结果。这全是谎话，全是不健康的道德观念，全是对真实的伪造，把人搞得晕头转向！只要想一想，在我们国家里，大家都热衷于读这样的小说，还认为它是好作品，把这些女人客厅里的滑稽戏当成了正剧，竟认真地去看待它们！');
INSERT INTO quotes (id, book_id) VALUES (1162, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1162, 'zh', '他觉得，就连到这里来的流氓也是高级流氓，他们是不屑于偷一条手帕的。这里也能看到江洋大盗。但是除了这些人之外，世界上最有名望和最富有的人也来到这里，巨大财富和高贵门第在这里相互拜访，相互敬重，这样一来，世界才会日新月异。克瓦茨基先生应该读读《悲剧的田园诗》​，那时他就会相信，除了那些卑贱下流的人外，这里还能遇见“社会上最上等的人”​，同福米达博号上的人一样，正因为有了这样的人，福米达博号上的电灯才会大放光明。');
INSERT INTO quotes (id, book_id) VALUES (1163, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1163, 'zh', '这西沉的太阳真是又伟大又美妙。在它的下面，那轻盈的飘散开来的浮云都像一片片棕榈林似的，散发出万道金光。近岸的海面都已经被阴影遮住了，然后在远处，在广阔的海面上，却霞光万丈。在下面，淡紫色的背景更加鲜明地衬托出那些寂静不动的柏树。');
INSERT INTO quotes (id, book_id) VALUES (1164, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1164, 'zh', '下面是沸腾的生活，与上面死一般沉寂的荒山，形成了一种奇异的对比。荒山的上面是万里无云的天空，它是那样的透明，犹如玻璃一般，给人以淡然冷漠之感。在这里，在这些寂静的巨石中间，一切生物都消失了，都显得微小了，就连这辆载人的马车，看上去也像一只趴在岩石上的小甲虫，骄傲地在这高地上爬行。');
INSERT INTO quotes (id, book_id) VALUES (1165, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1165, 'zh', '当拜访结束，她低头送别我们时，我的眼睛简直无法离开她了，就连艾娃也受到了她的强烈吸引，整天都在毫无意识地模仿她的鞠躬行礼和注视人的模样儿。');
INSERT INTO quotes (id, book_id) VALUES (1166, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1166, 'zh', '镜子前面放着许多化妆用品，一杯未喝完的黑咖啡，几瓶口红和香粉，画眉毛的画笔，几双依然保持着手的形状的手套，上面放着两条假发辫。旁边那堵墙上挂满了白的、粉红的、深色的、浅色的和黑色的衣服，地上还放着两筐女人的用品。房间里全是香水和香粉的气味。到处都凌乱不堪！仿佛这里的一切都是匆匆忙忙乱放在一起，由于煤气灯光的摇曳，形成了无数的色彩和反光，产生了形形色色的光和影的效果。');
INSERT INTO quotes (id, book_id) VALUES (1167, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1167, 'zh', '那些太太小姐们在跳舞时，老是向她们的男舞伴们唠叨，说她们是多么思念乌克兰，实际上，正像我的一位朋友说的，你就是用牵引机来拉她们，也无法把她们从华沙、从狂欢节拉回到乌克兰去。');
INSERT INTO quotes (id, book_id) VALUES (1168, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1168, 'zh', '真的，在全世界的美术展览馆里，你很难找出比这更美丽的头部来。我活了这样久，也从未见过这样明亮的眼睛。通过这双眼睛，你简直可以看见一个人的全部感情，就像明净的溪水那样清澈见底。');
INSERT INTO quotes (id, book_id) VALUES (1169, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1169, 'zh', '格罗齐￼见到她准会死而复活的，接着他又会因为自己画了那样一些稻草人而悬梁自尽。');
INSERT INTO quotes (id, book_id) VALUES (1170, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1170, 'zh', '于是他发表了简短的演说，在他说教时，我数了一百下，以后又从一开始数了起来。公民苏斯沃夫斯基，官吏苏斯沃夫斯基，父亲苏斯沃夫斯基，罗马人苏斯沃夫斯基——现在可有了机会来表现他心灵的伟大了……那些孩子、双亲、职责、未来、祝福、烦恼、绝洁的良心等词句，就像一群黄蜂在我的耳边嗡嗡直叫，它们停在我的脑袋上，叮咬我的耳朵、肩膀和额头……');
INSERT INTO quotes (id, book_id) VALUES (1171, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1171, 'zh', '我从商业银行取出了五个法郎的清一色的金路易。活到现在，我还从来没有一次见过这样多的钱。我像一头骡子似的把它驮了回来。');
INSERT INTO quotes (id, book_id) VALUES (1172, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1172, 'zh', '这个时刻是如此的庄严肃穆，连河马都会为之心潮澎湃、潸然泪下。苏斯沃夫斯基太太伸出双手，用抽泣的声调说话，更增加了这种庄严的气氛。');
INSERT INTO quotes (id, book_id) VALUES (1173, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1173, 'zh', '她的身上还散发着刚刚睡醒的暖意，浅蓝色的带皱褶的印花布衣服上散发出从公园里带回来的早晨的清新。她刚刚脱下帽子，头发有点乱。她满脸笑容，她的眼睛在笑，她那甜润的嘴唇也在笑……她自己就是真正的早晨。');
INSERT INTO quotes (id, book_id) VALUES (1174, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1174, 'zh', '原来我是坐在一块离地面不到一英尺半高的岩石上，四周是长满青苔的草地，一定是草地上的苔藓让那些石块的声音消失了，因为草地很平坦，远处是一条大路，路上有一群乌鸦，我却把它们当成了山鹰。我们只要把腿往岩石下面一伸，就能平安无事地回到住所。');
INSERT INTO quotes (id, book_id) VALUES (1175, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1175, 'zh', '还是在很久以前，他曾在自己的村里放过整夜的哨，现在，那早已成为过去的景象又突然历历在目地出现在他的眼前。他又成了一个枪骑兵，又在那里站岗放哨。');
INSERT INTO quotes (id, book_id) VALUES (1176, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1176, 'zh', '斯卡文斯基读到这里，再也读不下去了，字母仿佛在他的眼前跳动着，好像有什么东西在他心里翻腾，如同海浪那样越来越往上涌，堵住了他的喉咙，使他读不出声来……');
INSERT INTO quotes (id, book_id) VALUES (1177, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1177, 'zh', '他对这一点并没有清楚的认识，只是一种无意识的感觉而已，以至于到了最后，他觉得天空、海水、岩石、灯塔、金黄色沙滩、鼓满风的船帆、海鸥、退潮和涨潮—全都化成了一个巨大的整体，成为一个巨大的神秘的灵魂；而他自己也陷入在这样的神秘之中，感应到了在他周围活动和生息的那个灵魂。他沉浸在其中，受到它们陶醉，终于忘记了自身的存在。');
INSERT INTO quotes (id, book_id) VALUES (1178, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1178, 'zh', '他也十分清楚，在这些人迹罕至的荒原里，一个人的生活是多么的艰险，那里的一片树叶也要比人大十倍，这种地方又是吸血的蚊蚋、水蛭和巨大的毒蜘蛛遍布成灾的场所。他亲自体验过这一切，亲自看见过这一切，也受过这一切的折磨。现在他从高处望着那些荒原，观赏它们的美丽，而自己又不再受到它们的侵害，就觉得无比的欣喜了。');
INSERT INTO quotes (id, book_id) VALUES (1179, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1179, 'zh', '只要这一点还在发亮，巴尔特克就一直盯住它看，但是等到这一亮点都看不见了的时候，巴尔特克的心里便涌起了无限的惆怅。');
INSERT INTO quotes (id, book_id) VALUES (1180, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1180, 'zh', '似乎那些法国人特别仇恨波格伦坪人、上下克日夫达人、维夫瓦什齐涅茨人、聂多拉人和米日罗夫人，至少那些读过布告的人会产生这样的印象。');
INSERT INTO quotes (id, book_id) VALUES (1181, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1181, 'zh', '我想起这些的时候，现在是不会咬牙切齿的了，但我不相信人值得活在世上。因此，我对别人的任何不幸都有一种深切的同情。');
INSERT INTO quotes (id, book_id) VALUES (1182, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1182, 'zh', '但是在西边，红色的、金黄色的和橘色的晚霞，犹如一条条长带布满了整个天空。山峦在夕阳中傲然屹立，仙人掌显示出种种奇异的形状，有的像人，有的像动物。');
INSERT INTO quotes (id, book_id) VALUES (1183, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1183, 'zh', '“那本‘好书’上说，人应该劳动，所以我有时候也要跳跳铁圈，跳一个、两个铁圈，跳三个、四个铁圈。”');
INSERT INTO quotes (id, book_id) VALUES (1184, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1184, 'zh', '他那强壮粗犷的身体仿佛是用斧头随意砍削而成。他不单具有一般马戏团里的大力士的全部特征，而且还发展到这样粗壮的程度，竟使他看起来就像一个漫画式的人物');
INSERT INTO quotes (id, book_id) VALUES (1185, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1185, 'zh', '这些群众听到这蒸汽呼哨出来的歌声，个个兴奋得不能自制，美国人大声呼叫：“呼啦！”德国人高喊：“啊嘿！”墨西哥人则是叫着：“哎，维瓦！”卡菲拉人高兴得像野兽得到美味那样狂呼乱叫。');
INSERT INTO quotes (id, book_id) VALUES (1186, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1186, 'zh', '《星期六评论》最后写道：“谁若是在高杆上，或是在马背上看见过她一次，他将一辈子也不会忘记她，因为当代最伟大的艺术家，就连那个为皇宫旅馆作画的旧金山人哈尔维大师，也无法画出像她这样美貌的人物来。”');
INSERT INTO quotes (id, book_id) VALUES (1187, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1187, 'zh', '四郊来的太太们衣着都非常时髦，骄傲地靠在她们那些皮肤晒得黝黑的男人肩膀上。这些男人大多是头戴一顶旧帽子，上面穿一件法兰绒衬衣，下面穿一条斜纹布裤子。由于没有打领带，领子上的纽扣都扣得紧紧的。');
INSERT INTO quotes (id, book_id) VALUES (1188, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1188, 'zh', '为此她花了四个兹罗提六个格罗什。');
INSERT INTO quotes (id, book_id) VALUES (1189, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1189, 'zh', '那无出路的穷境，那对于无能为力、软弱和压迫的深刻而又苦痛的感受，那种犹如暴风雨中一片树叶的角色，还有那种对从天上地下都无法得到救助的沉重的感觉，所有这一切都会激发雅德维佳小姐说出一段充满灵感和激情的独白来。我只要把这段独白抄录下来，就可以名扬四海了。');
INSERT INTO quotes (id, book_id) VALUES (1190, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1190, 'zh', '热巴老婆也退到了花园篱笆前面，毕恭毕敬地站在那里，可是她等了很长的时间，贵族夫妇都在和客人谈笑取乐，时时有欢快的笑声传到她的耳朵里，这使她心里很难过，因为她这个不幸的女人不是来这里听笑声的。');
INSERT INTO quotes (id, book_id) VALUES (1191, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1191, 'zh', '雅德维佳小姐脸现愁容，维克多甚至在她的眼睛里看到了眼泪。于是为了驱散她的悲哀，他便谈起克拉舍夫斯基￼和文学海洋中那些较小的鱼儿来。谈话又渐渐活跃起来，不久他们两人便完全忘记了“那个不愉快的事件”。');
INSERT INTO quotes (id, book_id) VALUES (1192, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1192, 'zh', '下午大约五点钟的时候，在茅舍中间的大道上，远远地就能看到一把浅蓝色的阳伞，米黄色的帽子飘着蓝带，杏色的裙子上面有天蓝色的镶边，那是饭后出来散步的雅德维佳小姐，走在她旁边的是她的表兄弟维克多先生。');
INSERT INTO quotes (id, book_id) VALUES (1193, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1193, 'zh', '随后他们便看到了他们当初乘船离开的那个汉堡港。许多城市在他眼前闪过，周围听到的又是德国话了。不过火车还在向前飞奔，于是瓦夫章觉得离家乡越来越近了，心中顿时涌起了巨大的欢乐。他的故乡以一种亲切的气氛在迎接他。那是什么？国界！这个可怜农民的那颗心像槌子敲打似的跳动着……他们依然在朝前驶去。啊！上帝啊上帝！这里已是马奇科的田地和梨园了……还有灰色的房屋和教堂。那边有一个戴羊皮帽的农民正在用犁耕地。瓦夫章从火车里伸出手去招呼他：啊，朋友！朋友！他说不出声来。火车还在飞驰，那边又是什么地方呢？是普齐伦布列城，过了普齐伦布列城就是利宾采。');
INSERT INTO quotes (id, book_id) VALUES (1194, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1194, 'zh', '四周的景色无比美好，空气中充满了某种幸福和巨大的欢乐，似乎整个世界都在兴高采烈，唯有他们父女俩最为不幸，是两个被人遗忘的人。');
INSERT INTO quotes (id, book_id) VALUES (1195, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1195, 'zh', '因为只有处在幸福之中的人才会忘记，而在不幸和孤独的时候，一个人的情思总是围绕着他所爱的人，犹如忽布藤围绕着白杨树一样。');
INSERT INTO quotes (id, book_id) VALUES (1196, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1196, 'zh', '这里所看到的，已不是美国喜欢的那种直线条，而是奇怪的曲线。屋顶和墙壁一点也不整齐一致，而是高高低低、歪歪扭扭地杂挤在一起，真正是破陋不堪的贫民区。');
INSERT INTO quotes (id, book_id) VALUES (1197, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1197, 'zh', '在轮船上，他们在陌生人中间，曾感到孤独，也曾觉得那广袤的海水令人胆战心惊而又凶暴可恶。他们曾祈求上帝指引他们，像迷途的孩子那样，渡过那海洋的深渊。他们曾以为，只要他们的双脚踏上陆地，不幸就会结束。现在，他们已经来到了陆地上，身处在大城市中间，然而就是在这个城市里，在这些熙熙攘攘的人群中，他们顿时觉得他们比在轮船上的时候更加孤独、更加可怕。');
INSERT INTO quotes (id, book_id) VALUES (1198, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1198, 'zh', '然而，船上却有另一种繁忙的活动，因为在美丽的黄昏之后，夜晚往往并不那样宁静。所以船员们的哨子还在不停地吹着，水手们都在收紧绳索。');
INSERT INTO quotes (id, book_id) VALUES (1199, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1199, 'zh', '随后就只能看见满天霞光，再过一会儿，整个西边都是一片玫瑰色。而在这片光辉中，谁都无法分清：哪儿是耀眼的海水终结的地方，哪儿是苍天开始的地方。碧海苍天都在慢慢地消失，霞光映红的海洋发出单调的海涛声，但是很温和，仿佛在念晚祷似的。');
INSERT INTO quotes (id, book_id) VALUES (1200, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1200, 'zh', '太阳渐渐西沉，朝大海中落了下去。在起伏不停的波涛上，夕阳照成了一条宽广的大道，一直向船后伸展过去，形成了许多金色的鳞片，在变幻闪烁，在发光燃烧，最后消失在远方。轮船在这条金光大道上航行，仿佛是在追赶那没落的太阳。从烟囱里喷射的烟雾都变成了红色，船帆和潮湿的绳索也都披上了一层玫瑰色，');
INSERT INTO quotes (id, book_id) VALUES (1201, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1201, 'zh', '暴风雨来临了，天空一片昏暗，一道道耀眼的闪电划破重重乌云。有时整个天空都是一片火光，接着便是一片深沉的黑暗，雨水像一道道溪流似的倾泻下来。道路两旁的树木痉挛似的朝四面八方扭动着。我的马被我疯狂地鞭打着，被马刺踢着前进，开始喘息、呻吟起来了，我自己也愤怒得喘不过气来。');
INSERT INTO quotes (id, book_id) VALUES (1202, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1202, 'zh', '太阳终于西沉了，沉入在翻腾的云层里，云呈黄色，预示着一场冰雹和暴风雨的来临。好几次，听到了西方天空中远远传来的雷鸣声，像是即将来临的暴风雨在咆哮，空气显得沉闷、燥热，充满了雷电。小鸟躲在屋檐下或者大树上，只有燕子在空中来回飞翔。树叶不再沙沙作响了，而是昏昏欲睡地垂挂在那里。庄园里传来了从田里回来的牲口的哞叫声。一种沉闷的不安笼罩着整个大自然。');
INSERT INTO quotes (id, book_id) VALUES (1203, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1203, 'zh', '打从那个时候起，不知水面上涌起过多少波涛，也不知天上飘逝过多少云彩，但是生了翅膀的记忆不停地把那种场面展现在我的眼前');
INSERT INTO quotes (id, book_id) VALUES (1204, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1204, 'zh', '等我到达家里，金牛宫七星已经升上了天空，这意味着已是午夜了，村里各家的窗户都已没有灯光了，只有在远处的森林里，还能看见松脂坊里幽暗的灯光。');
INSERT INTO quotes (id, book_id) VALUES (1205, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1205, 'zh', '这时候，我们心里有什么样的感受，这是大家都能体会出来的，只要他回想起他青春年少时，在一个如此美好的夏日早晨，重返故乡的情景就够了。');
INSERT INTO quotes (id, book_id) VALUES (1206, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1206, 'zh', '我们深信，人类一旦发生危险，需要有人去拯救的话，那么这个人必然是他，必然是这个伟大的天才。');
INSERT INTO quotes (id, book_id) VALUES (1207, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1207, 'zh', '好心的卢德维克神父满脸堆上了笑容，但他闻了闻鼻烟，又用有颜色的手绢捂住鼻子来掩饰他的微笑。戴维斯夫人却一脸不高兴，虽然她心地善良，但由于她出身于法国的贵族世家，因而贵族派头十足。而小男仆弗兰齐什克却张着大嘴，惊讶地望着我。');
INSERT INTO quotes (id, book_id) VALUES (1208, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1208, 'zh', '脸颊上有两条伤痕的圣母的黝黑脸孔和蔼地望着我们，仿佛她也要来分担我们家的悲伤、忧虑、苦难和不幸，并对这些跪在她脚下的人们表示祝福。');
INSERT INTO quotes (id, book_id) VALUES (1209, 17);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1209, 'zh', '我也无法祈祷，成百上千种的印象和情感在我的脑海里、心里不断涌现。种种不同的景象从我眼前掠过。然而从这种种混乱的思绪中，渐渐引导出一种思想、一种情感，这就是：这个闭着双眼，脸色苍白，偎靠在我肩膀上的小脸蛋，这个孤苦无依的小姑娘，现在成了我心爱的妹妹，为了她，我愿献出自己的生命，为了她，如果有必要，我可以向全世界挑战。');

-- 新建作者 pick #39 · 弗雷德里克·巴克曼
INSERT INTO authors (id, emoji) VALUES (16, '🇸🇪');
INSERT INTO author_translations (author_id, language_code, name) VALUES (16, 'zh', '弗雷德里克·巴克曼'), (16, 'en', 'Fredrik Backman');
-- pick #39 · weread bookId=814146 · 一个叫欧维的男人决定去死（同名电影原著） · 33 条划线
INSERT INTO books (id, author_id, emoji) VALUES (18, 16, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (18, 'zh', '一个叫欧维的男人决定去死（同名电影原著）'), (18, 'en', 'A Man Called Ove');

INSERT INTO quotes (id, book_id) VALUES (1210, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1210, 'zh', '帕尔瓦娜的女儿又过生日了，不等人解释究竟是怎么回事儿，三岁女孩已经变成了六岁女孩。就像所有没大没小的三岁女孩一样。');
INSERT INTO quotes (id, book_id) VALUES (1211, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1211, 'zh', '每个人一生中最恼人的那一刻可能就是突然意识到自己已经到了回忆比展望更多的年龄。');
INSERT INTO quotes (id, book_id) VALUES (1212, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1212, 'zh', '死亡是一桩奇怪的事情。人们终其一生都在假装它并不存在，尽管这是生命的最大动机之一。我们其中一些人有足够时间认识死亡，他们得以活得更努力、更执着、更壮烈。有些人却要等到它真正逼近时才意识到它的反义词有多美好。另一些人深受其困扰，在它宣布到来之前就早早地坐进等候室。我们害怕它，但我们更害怕它发生在身边的人身上。对死亡最大的恐惧，在于它与我们擦肩而过，留下我们独自一人。');
INSERT INTO quotes (id, book_id) VALUES (1213, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1213, 'zh', '但脑中的疼痛，像玻璃和钢铁碎片交织的雨中一长串灯泡一个接一个爆裂般难以忍受。');
INSERT INTO quotes (id, book_id) VALUES (1214, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1214, 'zh', '七岁女孩上床睡觉前在欧维手上塞了一张写着“生日聚会邀请信”的纸。欧维把它当作公寓转让声明之类的法律文件一样严肃地读了一遍。');
INSERT INTO quotes (id, book_id) VALUES (1215, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1215, 'zh', '她在十字路口左转时那种漫不经心的样子让欧维担心她随时可能吹起口哨。');
INSERT INTO quotes (id, book_id) VALUES (1216, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1216, 'zh', '一年夏天，租房的三个年轻人无畏地想把房子改造成避难所，收容那些瘾君子、皮条客和在逃犯。狂欢昼夜不息，啤酒瓶的玻璃碎片礼花般撒满房子之间的小道，音乐轰鸣，震得欧维和索雅家客厅墙壁上的涂料纷纷坠落。');
INSERT INTO quotes (id, book_id) VALUES (1217, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1217, 'zh', '于是就出现了如下场景：一只猫、一个过敏的大胖子、一个玻璃和一个叫欧维的男人，一大清早一起在小区里巡逻。');
INSERT INTO quotes (id, book_id) VALUES (1218, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1218, 'zh', '鲁尼从未对此发表意见，但认识他很长时间的人都发现，之后的几年里，他矮了好几公分，就好像他在深深叹了口气后塌陷下去，从此再没能真正喘上气来。');
INSERT INTO quotes (id, book_id) VALUES (1219, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1219, 'zh', '鲁尼专心致志地看了他几秒钟，就像头脑正与什么外部干扰奋力斗争以便强挤出一片记忆来。');
INSERT INTO quotes (id, book_id) VALUES (1220, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1220, 'zh', '她知道你最有意思，所以总是把你画成彩色的。”帕尔瓦娜说。');
INSERT INTO quotes (id, book_id) VALUES (1221, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1221, 'zh', '“我失去太多了，欧维。感觉我的心就像在身体之外跳动。”');
INSERT INTO quotes (id, book_id) VALUES (1222, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1222, 'zh', '那只蠢笨的老胖猫恩斯特，索雅那么爱它，每次一见到它，她的心就跳得能弹起五克朗的硬币来。');
INSERT INTO quotes (id, book_id) VALUES (1223, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1223, 'zh', '不行不行，那他可得学学。”他最后把烟斗往嘴里一塞，走进客厅，嘟囔着。 索雅从没听他给过任何人更高的评价。');
INSERT INTO quotes (id, book_id) VALUES (1224, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1224, 'zh', '周围的世界渐渐在进口车、电脑、信贷和所有其他垃圾的怀抱中苏醒过来。');
INSERT INTO quotes (id, book_id) VALUES (1225, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1225, 'zh', '欧维的表情就像有机玻璃背后的男人刚问他是不是阳痿。那个男人闭上了嘴。');
INSERT INTO quotes (id, book_id) VALUES (1226, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1226, 'zh', '不到四十年之后，房子周围已经没有什么树林，只有其他房子。一天她躺在医院的病床上握着他的手，让他不要难过。');
INSERT INTO quotes (id, book_id) VALUES (1227, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1227, 'zh', '他当时当然不知道，他的一生将有多少个一刻钟要用来等待她，要是他父亲知道了，一定会气坏的。但当她身着一条印花长裙和一件红得让欧维不得不挪动一下脚步的羊毛衫出现时，欧维当即决定，她不守时的毛病也可以原谅。');
INSERT INTO quotes (id, book_id) VALUES (1228, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1228, 'zh', '她穿双红色的鞋，戴硕大的黄色发卡，胸前别着的一枚金色胸针调皮地反射着从车窗投进来的阳光。');
INSERT INTO quotes (id, book_id) VALUES (1229, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1229, 'zh', '当然，他还做不到不去设想一下：要是太太在场会怎么对他说。欧维沮丧地意识到，猜出她的想法也不难。');
INSERT INTO quotes (id, book_id) VALUES (1230, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1230, 'zh', '他实际上并不是在考虑自己应该做什么，而是在想父亲会怎么做。既然有了这个想法，下一步也就别无选择了。');
INSERT INTO quotes (id, book_id) VALUES (1231, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1231, 'zh', '都说下坠的时候脑子运转得更快。就像突然爆发的动能迫使大脑功能加速到极限，让周围的一切在印象中都呈现出一种慢镜头的效果。');
INSERT INTO quotes (id, book_id) VALUES (1232, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1232, 'zh', '晚上欧维烧香肠和土豆，坐在厨房操作台前透过玻璃窗向外张望，盛出晚餐。最后他站起身，端着盘子出门，坐到萨博里吃。');
INSERT INTO quotes (id, book_id) VALUES (1233, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1233, 'zh', '“总经理问你愿不愿意继续在这儿出色地工作下去。”');
INSERT INTO quotes (id, book_id) VALUES (1234, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1234, 'zh', '欧维坐在那儿大约一个小时，就一直盯着这张照片');
INSERT INTO quotes (id, book_id) VALUES (1235, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1235, 'zh', '维的视线极不情愿地转到鲁尼的太太身上。她还站在那儿。感觉自从上回见她，至今已经好几年了。或者说自从上回正眼看她后，她老了。');
INSERT INTO quotes (id, book_id) VALUES (1236, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1236, 'zh', '她的笑声吓了他一跳。就像她是灌了气的，打开得太快，气泡喷得到处都是。这笑声在灰色水泥和四方地砖之间显得很突兀，这是混乱无序的笑声，规矩不守方圆不成。');
INSERT INTO quotes (id, book_id) VALUES (1237, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1237, 'zh', '要不是下午还有更重要的事要做，他早就追上去把那只雪地靴做成拖把了。');
INSERT INTO quotes (id, book_id) VALUES (1238, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1238, 'zh', '欧维家隔壁住着个体重近四分之一吨的二十五岁男人。');
INSERT INTO quotes (id, book_id) VALUES (1239, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1239, 'zh', '因为自杀就撒手不管工作，这算哪门子的事？');
INSERT INTO quotes (id, book_id) VALUES (1240, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1240, 'zh', '因此父亲和欧维从来没有过多的交谈，但他们喜欢彼此的陪伴。沉默地分别坐在餐桌的两端就很满足。');
INSERT INTO quotes (id, book_id) VALUES (1241, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1241, 'zh', '他默不作声地站在那儿转着手指上的婚戒，仿佛在寻找新的话题。引导谈话方向这活儿对他来说还是太痛苦。这本来就是她的专职之一。他负责回答。现在这种新情况，他们俩都还得适应。');
INSERT INTO quotes (id, book_id) VALUES (1242, 18);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1242, 'zh', '“粉红色，你喜欢的。温室栽培。店里的人管它叫‘常年花’，我他妈才不信呢。这么冷的天，它们显然会被冻死，店里的人也承认了，不过他们这么说只是为了推销更多垃圾给你。”');

-- 复用已有作者 id=2 · 赫尔曼·黑塞
-- pick #40 · weread bookId=3300052230 · 荒原狼（果麦经典） · 45 条划线
INSERT INTO books (id, author_id, emoji) VALUES (19, 2, '📚');
INSERT INTO book_translations (book_id, language_code, title) VALUES (19, 'zh', '荒原狼（果麦经典）'), (19, 'en', 'Steppenwolf');

INSERT INTO quotes (id, book_id) VALUES (1243, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1243, 'zh', '如果生命终将结束于坟墓中，我们又为何致力于艰辛地塑造自我，探索永恒？');
INSERT INTO quotes (id, book_id) VALUES (1244, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1244, 'zh', '这邪恶的金属漏斗果然喷出嚼烂的橡胶和支气管黏液的混合物，喷出留声机的拥有者和收音机用户们齐声称为“音乐”的东西');
INSERT INTO quotes (id, book_id) VALUES (1245, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1245, 'zh', '涂红的嘴唇在毫无血色的脸上越来越红。这副僵硬的嘴唇就像我的一生，像我可怜的幸福和爱情：一点红，画在一张死人的脸上。');
INSERT INTO quotes (id, book_id) VALUES (1246, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1246, 'zh', '那年三月的一个周日，他在岩石上遇见罗莎，摘下了受坚信礼时戴的帽子。但打那以后，他老了几百岁。');
INSERT INTO quotes (id, book_id) VALUES (1247, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1247, 'zh', '确实不能。他们也不能为亚当偷食禁果负责，但他们不得不为此赎罪。');
INSERT INTO quotes (id, book_id) VALUES (1248, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1248, 'zh', '“我们在《唐璜》的最后一幕，莱波雷洛￼已经跪下。出色的一幕，音乐也值得一听。其中还有各种人性的意味，但仍能感受到彼岸的气息。比如那笑声——不是吗？”');
INSERT INTO quotes (id, book_id) VALUES (1249, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1249, 'zh', '我几乎错过了她们每一个人，跌跌撞撞，逃之夭夭，随后将她们遗忘——但在这里，她们被保存下来，一个不缺，数以百计。现在我看见她们，献身于她们，沉沦于她们玫瑰色的昏暗的阴曹地府。');
INSERT INTO quotes (id, book_id) VALUES (1250, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1250, 'zh', '阳光更炽热，星辰更醉人，但罗莎和伊姆加德都不属于我。我不得不一级级攀登，去经历，去学习，不得不失去伊姆加德，又失去安娜。');
INSERT INTO quotes (id, book_id) VALUES (1251, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1251, 'zh', '我们起身比身高，我实际比她高一指，但我不承认，说我们一般高，说我们注定相爱，这是上帝的旨意，说我们以后要结婚。');
INSERT INTO quotes (id, book_id) VALUES (1252, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1252, 'zh', '我正重温少年时的最后一幕，那是个早春的礼拜日下午。那天，我独自散步时遇见罗莎·克莱斯勒。');
INSERT INTO quotes (id, book_id) VALUES (1253, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1253, 'zh', '那是少年和青年时的气息，而我心中竟流淌着当年的血。');
INSERT INTO quotes (id, book_id) VALUES (1254, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1254, 'zh', '貌似哈里的驯兽师突然深深弯腰，将鞭子放在狼脚下，开始像先前的狼一样瑟瑟发抖，缩成一团，样子十分痛苦。而狼却笑着舔舔嘴，抖落了原本的抽搐和装模作样，凶光毕露，整个身体结实有力，重新焕发出兽性。');
INSERT INTO quotes (id, book_id) VALUES (1255, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1255, 'zh', '您可以将今日令您不堪忍受的傀儡，那些败坏您游戏的形象，降级为明日无关紧要的配角。您可以将那些似乎注定一时倒霉、交厄运的可怜小角色在下一场游戏中变为公主。祝您愉快，我的先生。”');
INSERT INTO quotes (id, book_id) VALUES (1256, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1256, 'zh', '整个房间静谧安详。夕阳西下，照在我的图书馆中许多书脊的金字上闪闪发光。');
INSERT INTO quotes (id, book_id) VALUES (1257, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1257, 'zh', '莫扎特。他当时如何？在他的时代，谁统治世界，谁获利最多，谁定下基调、判断价值：是莫扎特还是商人？是莫扎特还是庸众？他是怎么死的？怎么被埋葬的？');
INSERT INTO quotes (id, book_id) VALUES (1258, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1258, 'zh', '今天，活得快活的人，绝非你我之辈。想要真正的音乐，剔除噪音，希望灵魂取代金钱，真正的工作取代生意，真正的激情取代消遣——对于有这些愿望的人来说，这个华丽的世界绝非他的家园……”');
INSERT INTO quotes (id, book_id) VALUES (1259, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1259, 'zh', '因此，请您放下这副眼镜，最好将您尊贵的人格留在衣帽间。如果您愿意，您可以随时取回，它们随时供您使用。');
INSERT INTO quotes (id, book_id) VALUES (1260, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1260, 'zh', '但是，每个真实行动的画面、真正情感的力量，即便无人知晓，无人看见，无人为后人记录保存下来，也隶属永恒。在永恒中，没有后世，唯有当下。”');
INSERT INTO quotes (id, book_id) VALUES (1261, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1261, 'zh', '如果你为了美好事物和理想战斗，并认为你一定会成功，那倒要平庸得多。难道理想都能实现？我们人活着，难道是为战胜死亡？不，我们活着，是为畏惧死亡，再爱上它。正因为它，微弱的生命才绽放短暂的光芒。');
INSERT INTO quotes (id, book_id) VALUES (1262, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1262, 'zh', '我再次领略了我在痛苦中长久遗忘的东西。它们是我一生的财富，并将继续不可磨灭地存在下去。这些经历已化作星辰，尽管被遗忘，却永恒不灭。');
INSERT INTO quotes (id, book_id) VALUES (1263, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1263, 'zh', '此外，买东西让人开心。开心的事要好好享受。你要学的东西还真不少。”');
INSERT INTO quotes (id, book_id) VALUES (1264, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1264, 'zh', '。也许她不能完全理解我的精神生活，无法彻底明白我与音乐、歌德、诺瓦利斯和波德莱尔的关系？但这一点非常可疑，或许对她来说，理解这一切根本不是难事。');
INSERT INTO quotes (id, book_id) VALUES (1265, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1265, 'zh', '思想家哈里已经一百岁，舞蹈家哈里却出生不足半天。我们现在要继续培育舞蹈家哈里和他众多同样幼稚愚蠢、尚未长大的小兄弟。”');
INSERT INTO quotes (id, book_id) VALUES (1266, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1266, 'zh', '而不是拉我进入这个混乱陌生、光怪陆离的游戏世界。在这个世界里，我永远是个陌生人，我身上最好的东西在此荒废受苦！');
INSERT INTO quotes (id, book_id) VALUES (1267, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1267, 'zh', '你内心本有一幅生活愿景，有信仰，有需求。你本打算有所成就，并愿意为此受苦，甚至牺牲——可你逐渐意识到，这个世界根本不需要你的作为和牺牲。');
INSERT INTO quotes (id, book_id) VALUES (1268, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1268, 'zh', '但你这个怪人的奇特之处在于，你很容易着魔，甚至在别人眼中看不见、读不到任何东西，一切都与你无关。而你这个怪人一旦发现了一张真正凝视你的脸，在这张脸上感受到回应和默契，是的，你当然尤其喜悦。');
INSERT INTO quotes (id, book_id) VALUES (1269, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1269, 'zh', '看，小家伙，这是鸭腿，从骨头上剔下鲜艳漂亮的鸭肉就是一场庆典，让人满心欢喜和感激，胃口大开，就像一个情人第一次帮他的姑娘脱下外套。');
INSERT INTO quotes (id, book_id) VALUES (1270, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1270, 'zh', '当他充满渴望，心怀好意地舒展双臂，准备迎接束缚，接受群体时，已经于事无补：没人愿意跟他站在一起。他并非遭人憎恶或令人讨厌，相反，他有很多朋友。许多人喜欢他，但那不过是出于同情和善意。');
INSERT INTO quotes (id, book_id) VALUES (1271, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1271, 'zh', '找不到我的故土和挚友，只能找到舞台前安静的观赏席位，观看陌生人上演陌生的剧目');
INSERT INTO quotes (id, book_id) VALUES (1272, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1272, 'zh', '路灯模糊的泪眼照着寒夜的阴霾，又从湿漉漉的路面汲取慵懒的反光。');
INSERT INTO quotes (id, book_id) VALUES (1273, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1273, 'zh', '浮士德曾说过一句教师们十分熟悉，庸人们分外赞赏的话：“啊，我胸中住着两个灵魂！”但他忘了，他胸中还住着梅菲斯特和一大群其他灵魂。我们的荒原狼也认为他胸中住着两个灵魂（狼和人），还认为他的胸膛因此拥挤不堪。一个人的胸膛、身躯向来只有一个，但居住其中的，却绝不止两个或五个灵魂，而是无数个灵魂。');
INSERT INTO quotes (id, book_id) VALUES (1274, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1274, 'zh', '与之相反，我经历的为数不多的快乐，那些愉悦、狂喜、巅峰体验，世人或许最多在文艺作品中见识过、寻觅过、热爱过。而在现实生活中，他们必定认为那不合常理、荒诞不经。');
INSERT INTO quotes (id, book_id) VALUES (1275, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1275, 'zh', '我看见牧师和几个赚死人钱的殡葬师各尽其职，极力装出一副庄重悲伤的样子，可他们过度的表演既让人尴尬又显得虚假，费尽周折反而滑稽');
INSERT INTO quotes (id, book_id) VALUES (1276, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1276, 'zh', '孩子们也绝不是幸福的，他们也有种种矛盾、种种分裂，承受着种种痛苦。');
INSERT INTO quotes (id, book_id) VALUES (1277, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1277, 'zh', '幽默是那些在完成伟大使命的过程中重重受阻，那些接近成为悲剧人物、不幸的非凡人物的美妙发明。');
INSERT INTO quotes (id, book_id) VALUES (1278, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1278, 'zh', '并为此付出了生命和感情的强度——追求绝对和极端生活之人才能赢得的强度。');
INSERT INTO quotes (id, book_id) VALUES (1279, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1279, 'zh', '他们的理想不是献身，而是自保。他们所追求的既不是神圣性，亦不是神圣性的对立面。一切绝对性他们都难以承受。他们虽侍奉上帝，却也贪图享乐，虽志愿品行端正，却也要在尘世中享有轻松舒适。');
INSERT INTO quotes (id, book_id) VALUES (1280, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1280, 'zh', '我倒要看看，一个人究竟能承受多少不幸！一旦到了痛苦的极致，我只要打开太平门，就能逃走。”许多自杀者都从这种想法中获得非凡的力量。');
INSERT INTO quotes (id, book_id) VALUES (1281, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1281, 'zh', '这些人虽活得极不安宁，却能在为数不多的幸福瞬间，强烈地经验到难以言状的美好事物。');
INSERT INTO quotes (id, book_id) VALUES (1282, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1282, 'zh', '他爱人或被爱时，也令别人不幸。因为所有爱他的人，总是只看到他的一面。有些人爱他，视他为正派、聪明而优雅的人，一旦发现他身上的狼性，就既吃惊又失望。');
INSERT INTO quotes (id, book_id) VALUES (1283, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1283, 'zh', '智力好的人能学会的东西，他学了不少，是个相当聪明的人。但他学不会的，却是对自己和生活感到满意。');
INSERT INTO quotes (id, book_id) VALUES (1284, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1284, 'zh', '我小小的所谓家里，靠椅、火炉、墨水瓶、颜料盒、诺瓦利斯和陀思妥耶夫斯基在等我，就像一个人回到真正的家中，母亲、妻子、孩子、女仆，狗或猫在等他一样。');
INSERT INTO quotes (id, book_id) VALUES (1285, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1285, 'zh', '在束手无策地渴望温暖中折磨自己是多么可笑！孤独就是独立。多年来，我终于拥有了我一直渴求的孤独。孤独是冰冷的，哦，是的！');
INSERT INTO quotes (id, book_id) VALUES (1286, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1286, 'zh', '谁又将它纳入灵魂？谁爱它？谁能捕捉它轻柔消逝的颜色魔力？修士们的古籍，泛着柔和色泽的插画，被人遗忘的百年甚至两百年前的德国诗人的诗作，所有那些发霉残破的古卷，老音乐家的手稿和印刷本，那些扎紧的泛黄乐谱，凝固的声音之梦——谁还倾听他们充满生机、戏谑和渴望的声音？谁还心怀书中的精神与魔力，步入截然不同的陌生年代？谁还念着古比奥山上那棵幼小坚韧的柏树？它被滚落的巨石切裂，却保住了性命，长出崭新稚嫩的枝丫。谁留意了住在二楼的勤劳主妇和她的南洋杉？谁在夜晚辨识浓雾中莱茵河上空浮动的云状字符？唯有荒原狼。谁在他生命的废墟上寻找残破的意义，忍受着无意义之事的折磨，过着近乎疯狂的日子，却秘密地在最后的迷狂与混乱中，渴望启示和亲近上帝？');
INSERT INTO quotes (id, book_id) VALUES (1287, 19);
INSERT INTO quote_translations (quote_id, language_code, content) VALUES (1287, 'zh', '全部的文字意味着一次地狱之旅，一次时而忧惧时而英勇的旅行，在幽暗的灵魂世界的混沌中，以意志穿越地狱，直面混沌，忍受邪恶，直至终点。 哈勒说过的一番话，是我');

-- 合计: 15 本书, 1169 条 quote (id 119–1287)
SELECT COUNT(*) AS quotes_total FROM quotes;
